function lukTrinketMultiplier(luk, level) {
    const safeLuk = Math.max(0, Number(luk || 0));
    const safeLevel = Math.max(1, Number(level || 1));
    return 1 + safeLuk / (safeLuk + 10 + 2 * safeLevel);
}

function equippedTrinket(crew, owner) {
    const slot = owner === 'tansy' ? 'neck' : 'amulet';
    const item = crew?.gear?.[owner]?.[slot];
    const stat = Number(item?.stat ?? item?.rawStat ?? 0);
    return item?.trinket?.id && stat > 0 ? item : null;
}

function trinketBudget(item, luk, level, vitalsActive = false) {
    const stat = Number(item?.stat ?? item?.rawStat ?? 0);
    if (!item?.trinket?.id || stat <= 0) return 0;
    const base = stat * 2;
    const scaled = base * lukTrinketMultiplier(luk, level) * (vitalsActive ? 1.5 : 1);
    return Math.max(1, Math.round(scaled));
}

function rollTrinketFromState(
    state,
    zone,
    rarity = 'uncommon',
    source = 'instance',
    sourceId = null
) {
    assert(ZONES[zone], `Unknown trinket zone: ${zone}`);
    const owner = roll(state, 2) === 1 ? 'tansy' : 'qtik';
    const slot = owner === 'tansy' ? 'neck' : 'amulet';
    const pool = KEYSTONE_TRINKETS[owner];
    const def = pool[roll(state, pool.length) - 1];
    const variant = owner === 'tansy'
        ? (roll(state, 2) === 1 ? 'luck' : 'vitality')
        : (roll(state, 2) === 1 ? 'bulwark' : 'vitality');
    const rarityInfo = LOOT_RARITY_INFO[rarity];
    assert(rarityInfo, `Unsupported trinket rarity: ${rarity}`);
    const rawStat = lootStatFromRarity(zone, rarity);

    return {
        name: `${ZONE_LOOT_MATERIALS[zone]} ${def.name}`,
        owner,
        slot,
        variant,
        rarity: rarityInfo.label,
        rarityColor: rarityInfo.color,
        rawStat,
        sellValue: rawStat * 2,
        bound: false,
        classRestricted: false,
        tradeStreamEligible: true,
        bonus: lootBonus(owner, slot, variant, rawStat),
        trinket: {
            id: def.id,
            name: def.name,
            summary: def.summary
        },
        acquiredFrom: source,
        ...(sourceId ? { acquiredAtSource: sourceId } : {})
    };
}

const SHADOW_UNLOCK_LEVEL = 10;

const SHADOW_SOURCE_ROLE_MAP = {
    archer: 'archer',
    mender: 'mender',
    hexer: 'hexer',
    brute: 'warder'
};

const SHADOW_TYPE_LABELS = {
    archer: 'Shadow-Ranged',
    mender: 'Shadow-Mender',
    hexer: 'Shadow-Hexer',
    warder: 'Shadow-Warder'
};

function shadowTierFromLevel(level) {
    return Math.ceil(int(level, 'shadow.sourceMobLevel', 1) / 5);
}

function shadowSummaryText(type, tier) {
    if (type === 'archer') {
        return '+5 ATK · Ranged (immune to Carapace & Cleave · 3 slots)';
    }
    if (type === 'mender') {
        return `Drains ${1 + tier} HP/exch to lowest-HP% ally · 1 cleanse/turn (3 slots)`;
    }
    if (type === 'hexer') {
        return `+${tier} ATK · −${2 * tier} Target DEF (3 slots)`;
    }
    if (type === 'warder') {
        const bleedRed = Math.floor((tier + 1) / 2);
        return `+${tier} ATK · −${bleedRed} Frontline Bleed · 1/fight lethal save (3 slots)`;
    }
    return '';
}

function detectPostCombatShadowImprints(state) {
    if ((state.crew?.level || 1) < SHADOW_UNLOCK_LEVEL) return null;
    const foes = state.encounter?.foes || [];
    if (!foes.length) return null;

    const bestByType = new Map();
    for (const foe of foes) {
        const shadowType = SHADOW_SOURCE_ROLE_MAP[foe.role];
        if (!shadowType) continue;
        const prev = bestByType.get(shadowType) || 0;
        if (foe.level > prev) bestByType.set(shadowType, foe.level);
    }

    const deck = state.crew.shadows?.deck || [];
    const imprints = [];

    for (const [type, sourceMobLevel] of bestByType.entries()) {
        const existing = deck.find(entry => entry.type === type);
        const tier = shadowTierFromLevel(sourceMobLevel);

        if (!existing) {
            imprints.push({
                type,
                shadowId: `shadow-${type}`,
                sourceMobLevel,
                shadowTier: tier,
                isNew: true,
                previousLevel: null,
                previousTier: null
            });
        } else if (type !== 'archer') {
            const prevTier = shadowTierFromLevel(existing.sourceMobLevel);
            if (tier > prevTier) {
                imprints.push({
                    type,
                    shadowId: existing.id,
                    sourceMobLevel,
                    shadowTier: tier,
                    isNew: false,
                    previousLevel: existing.sourceMobLevel,
                    previousTier: prevTier
                });
            }
        }
    }

    if (imprints.length === 0) return null;

    return {
        encounterId: state.encounter.id,
        zone: state.encounter.zone,
        imprints
    };
}

function shadowMechanics(crew) {
    const active = crew.shadows?.active || [];
    const deck = crew.shadows?.deck || [];
    assert(Array.isArray(active) && Array.isArray(deck),
        'Shadow deck and active shadows must be arrays');

    const result = {
        slots: 0, attack: 0, archerAttack: 0,
        menderDrain: 0, hexStrip: 0, bruteReduction: 0
    };
    const ids = new Set();
    const uniqueRoles = new Set();

    for (const shadow of active) {
        assert(shadow && typeof shadow.id === 'string' && !ids.has(shadow.id),
            'Active shadows need unique deck IDs');
        ids.add(shadow.id);

        const entry = deck.find(item => item.id === shadow.id);
        assert(entry && entry.type === shadow.type &&
            entry.sourceMobLevel === shadow.sourceMobLevel,
            `Active shadow ${shadow.id} must match its deck entry`);

        const count = int(shadow.count, `${shadow.id}.count`, 1);
        const tier = shadowTierFromLevel(shadow.sourceMobLevel);
        assert(shadow.shadowTier === tier,
            `${shadow.id} has an incorrect Shadow Tier`);

        if (shadow.type !== 'archer') {
            assert(count === 1 && !uniqueRoles.has(shadow.type),
                `Only one active Shadow ${shadow.type} is allowed`);
            uniqueRoles.add(shadow.type);
        }

        result.slots += 3 * count;
        if (shadow.type === 'archer') {
            // 5 ATK per Shadow-Ranged (~83% of 3 loose weasels' 6 ATK): always the
            // safe ranged trade-off without overtaking loose-weasel DPS.
            result.archerAttack += count * 5;
            result.attack += count * 5;
        } else if (shadow.type === 'mender') {
            result.menderDrain += 1 + tier;
        } else if (shadow.type === 'hexer') {
            result.attack += tier;
            result.hexStrip += 2 * tier;
        } else if (shadow.type === 'warder') {
            result.attack += tier;
            result.bruteReduction += Math.floor((tier + 1) / 2);
        } else {
            throw new Error(`Unsupported active shadow type: ${shadow.type}`);
        }
    }
    return result;
}

