const QUEST_ARCHETYPES_BY_CHANNEL = {
    social: new Set([
        'local_bounty',
        'field_job',
        'courier_recovery',
        'missing_person'
    ]),
    overland: new Set([
        'local_bounty',
        'field_job',
        'courier_recovery',
        'missing_person',
        'sealed_cache',
        'dormant_hazard'
    ]),
    instance: new Set([
        'sealed_cache',
        'dormant_hazard'
    ])
};

function eligibleQuestScenarios(_state, archetype, _zone, rank, channel = 'overland') {
    const allowedForChannel =
        QUEST_ARCHETYPES_BY_CHANNEL[channel] ||
        QUEST_ARCHETYPES_BY_CHANNEL.overland;

    if (!allowedForChannel.has(archetype.id)) return [];

    // Rank F errands belong to Town social contacts only.
    if (rank === 'F' && channel !== 'social') return [];

    return (archetype.scenarios || []).filter(scenario => {
        if (
            Array.isArray(scenario.ranks) &&
            !scenario.ranks.includes(rank)
        ) {
            return false;
        }

        if (rank === 'F') {
            return [
                'local_bounty',
                'field_job',
                'courier_recovery',
                'missing_person'
            ].includes(archetype.id) &&
                scenario.ranks?.includes('F') === true;
        }

        if (archetype.id !== 'missing_person') return true;

        if (scenario.variantId === 'lost') {
            return ['F', 'E', 'D'].includes(rank);
        }
        if (scenario.variantId === 'abducted') {
            return rank === 'C' || rank === 'B';
        }

        return false;
    });
}

function eligibleQuestArchetypes(state, zone, rank, channel = 'overland') {
    return QUEST_ARCHETYPES
        .map(archetype => ({
            archetype,
            scenarios: eligibleQuestScenarios(
                state,
                archetype,
                zone,
                rank,
                channel
            )
        }))
        .filter(entry => entry.scenarios.length > 0);
}

function buildQuestFacts(
    state,
    archetype,
    zone,
    eligibleScenarios,
    rank
) {
    assert(
        eligibleScenarios.length > 0,
        `Quest archetype ${archetype.id} has no scenario compatible with Zone ${zone}`
    );

    let variantRoll = null;
    let variantId =
        archetype.variantId ||
        eligibleScenarios[0].variantId ||
        null;

    let scenarios = eligibleScenarios;

    if ([
        'missing_person',
        'sealed_cache',
        'dormant_hazard'
    ].includes(archetype.id)) {

        const variants = [
            ...new Set(
                eligibleScenarios.map(scenario => scenario.variantId)
            )
        ];

        assert(
            variants.every(id => typeof id === 'string' && id.length > 0),
            `${archetype.label} scenarios need authored variantId values`
        );

        variantRoll = roll(state, variants.length);
        variantId = variants[variantRoll - 1];

        scenarios = eligibleScenarios.filter(
            scenario => scenario.variantId === variantId
        );
    }

    const scenarioRoll = roll(state, scenarios.length);
    const scenario = scenarios[scenarioRoll - 1];

    assert(
        scenario &&
        typeof scenario.pitch === 'string' &&
        scenario.facts &&
        typeof scenario.facts === 'object',
        `Quest archetype ${archetype.id} has an invalid scenario`
    );

    const facts = clone(scenario.facts);
    const stakesByArchetype = {
        sealed_cache: {
            E: 'a minor unclaimed stash tucked inside old stonework',
            D: 'a sealed Pre-Calamity cache untouched since the fall',
            C: 'a well-hidden Imperial strongbox holding high-grade salvage',
            B: 'a sealed Magistrate-grade vault cache of rare value'
        },
        dormant_hazard: {
            E: 'a localized Pre-Calamity hazard stirring inside an old ruin',
            D: 'an active construct or breached vault threatening nearby ground',
            C: 'a dangerous dormant security site encroaching on the region',
            B: 'a major Pre-Calamity threat holding a sealed inner site'
        },
        missing_person: {
            F: 'a local contact who got stranded or pinned down near town',
            E: 'a missing local whose safe return matters to their crew or kin',
            D: 'one lost person whose safe return matters to the affected party',
            C: 'one abducted person held by a hostile group',
            B: 'an abducted person whose loss has serious consequences beyond one household'
        },
        local_bounty: {
            F: 'a minor local threat disrupting everyday work or safety',
            E: 'a persistent threat pressuring local workers or travelers',
            D: 'a dangerous threat blocking important local business or routes',
            C: 'a serious hostile force disrupting the settlement',
            B: 'a major regional threat endangering the wider territory'
        },
        field_job: {
            F: 'a routine hands-on job near the settlement',
            E: 'a practical field task locals cannot easily handle themselves',
            D: 'a delicate or risky on-site job with real local stakes',
            C: 'an urgent field operation affecting settlement affairs',
            B: 'a high-stakes site operation with region-wide consequences'
        },
        courier_recovery: {
            F: 'a misplaced item or small consignment left near town',
            E: 'missing goods or records needed for local business',
            D: 'valuable property whose loss hurts a local faction or owner',
            C: 'critical goods or proof needed by the settlement',
            B: 'region-critical cargo or evidence with major fallout'
        }
    };

    const rankStakes = stakesByArchetype[archetype.id]?.[rank];
    if (rankStakes) facts.stakes = rankStakes;

    return {
        variantRoll,
        variantId: scenario.variantId || variantId,
        scenarioRoll,
        pitch: scenario.pitch,
        truth: scenario.truth,
        facts
    };
}

/*
 * COMPLETE QUEST STRUCTURES — VERSION 2
 *
 * These structures are setting-independent mechanics, not story scripts.
 * The narrator dresses the current scene but cannot add mandatory stages.
 *
 * Each supported gate count has a complete structure ending in the
 * decisive objective. Delivery follows field completion and is not
 * counted as an additional field gate.
 *
 * Trigger contracts for the forthcoming controller integration:
 * - arrival: saved travel arrival at this gate's location.
 * - discovery: validated FOUND event for this gate's authored discovery.
 * - linked_combat: this gate's engine-created encounter is cleared.
 *
 * New offers are created from these complete structures, and their
 * progression resolves through arrival, discovery, and linked-combat
 * events. Existing saves are reset before beta, so retired catalog
 * archetypes and their fixed-site preparation code are not retained.
 */

const QUEST_V2_STRUCTURES = {
    retrieve_item: {
        1: ['recover'],
        2: ['approach', 'recover'],
        3: ['approach', 'locate', 'recover'],
        4: ['approach', 'locate', 'reach_inner_site', 'recover'],
        5: ['approach', 'locate', 'reach_inner_site', 'find_access', 'recover']
    },
    rescue_person: {
        lost: {
            1: ['find_person'],
            2: ['approach', 'find_person'],
            3: ['approach', 'track', 'find_person']
        },
        abducted: {
            3: ['approach', 'track', 'defeat'],
            4: ['approach', 'track', 'reach_lair', 'defeat'],
            5: ['approach', 'track', 'reach_lair', 'find_person', 'defeat']
        }
    },
    defeat_elite: {
        1: ['defeat'],
        2: ['approach', 'defeat'],
        3: ['approach', 'track', 'defeat'],
        4: ['approach', 'track', 'reach_lair', 'defeat'],
        5: ['approach', 'track', 'reach_lair', 'find_target', 'defeat']
    }
};

const QUEST_V2_STAGES = {
    retrieve_item: {
        approach:         { mode: 'traversal_discovery', trigger: 'arrival' },
        locate:           { mode: 'brain_social_heist',  trigger: 'discovery' },
        reach_inner_site: { mode: 'traversal_discovery', trigger: 'discovery' },
        find_access:      { mode: 'brain_social_heist',  trigger: 'discovery' },
        recover:          { mode: 'brain_social_heist',  trigger: 'discovery', decisive: true }
    },
    rescue_person: {
        approach:         { mode: 'traversal_discovery',   trigger: 'arrival' },
        track:            { mode: 'brain_social_heist',    trigger: 'discovery' },
        reach_lair:       { mode: 'traversal_discovery',   trigger: 'discovery' },
        find_person:      { mode: 'brain_social_heist',    trigger: 'discovery' },
        defeat:           { mode: 'combat_twist_showdown', trigger: 'linked_combat', decisive: true }
    },
    defeat_elite: {
        approach:         { mode: 'traversal_discovery',   trigger: 'arrival' },
        track:            { mode: 'brain_social_heist',    trigger: 'discovery' },
        reach_lair:       { mode: 'traversal_discovery',   trigger: 'discovery' },
        find_target:      { mode: 'brain_social_heist',    trigger: 'discovery' },
        defeat:           { mode: 'combat_twist_showdown', trigger: 'linked_combat', decisive: true }
    }
};

function validateQuestV2Structure(plan) {
    assert(plan?.version === 2, 'Expected a V2 quest structure');
    assert(
        QUEST_V2_STRUCTURES[plan.family],
        `Unsupported quest family: ${plan.family}`
    );
    int(plan.gateCount, 'quest structure gate count', 1);

    assert(
        Array.isArray(plan.gates) &&
        plan.gates.length === plan.gateCount,
        'Quest structure gate count does not match its stages'
    );

    const decisiveGates = plan.gates.filter(gate => gate.decisive);

    assert(
        decisiveGates.length === 1 &&
        plan.gates.at(-1).decisive === true,
        'Quest must end with exactly one decisive objective'
    );

    const expectedSequence =
        plan.family === 'rescue_person'
            ? QUEST_V2_STRUCTURES.rescue_person[
                plan.variantId
              ]?.[plan.gateCount]
            : QUEST_V2_STRUCTURES[plan.family][plan.gateCount];

    assert(expectedSequence, 'Unsupported quest structure length');

    for (let index = 0; index < plan.gates.length; index++) {
        const gate = plan.gates[index];

        assert(
            gate.stage === expectedSequence[index] &&
            gate.step === index + 1 &&
            gate.total === plan.gateCount,
            'Quest stages do not match the selected complete structure'
        );

        assert(
            ['arrival', 'discovery', 'linked_combat']
                .includes(gate.trigger),
            `Unsupported quest stage trigger: ${gate.trigger}`
        );
    }

    return plan;
}

function buildQuestV2Structure(family, gateCount, facts) {
    int(gateCount, 'quest structure gate count', 1);
    assert(
        facts && typeof facts === 'object',
        'Quest structure requires authored facts'
    );
    const variantId =
        family === 'rescue_person'
            ? facts.rescueVariant
            : null;

    const sequence =
        family === 'rescue_person'
            ? QUEST_V2_STRUCTURES.rescue_person[
                variantId
              ]?.[gateCount]
            : QUEST_V2_STRUCTURES[family]?.[gateCount];

    assert(
        sequence,
        `No complete ${family} structure for ${gateCount} gates` +
            (variantId ? ` (${variantId})` : '')
    );

    function fact(key) {
        const value = facts[key];
        assert(
            typeof value === 'string' && value.trim().length > 0,
            `Quest family ${family} requires fact '${key}'`
        );
        return value;
    }

    const objectiveFor = {
        retrieve_item: {
            approach:
                () => `Reach ${fact('destination')} safely.`,
            locate:
                () => `Find the authored clue identifying where ${fact('item')} is held.`,
            reach_inner_site:
                () => `Follow the established clue to the location of ${fact('item')}.`,
            find_access:
                () => `Discover the authored means of accessing ${fact('item')}.`,
            recover:
                () => `Recover ${fact('item')} from ${fact('destination')}.`
        },
        rescue_person: {
            approach:
                () => `Reach ${fact('place')} safely.`,
            track:
                () => `Follow the established signs of ${fact('person')}'s route.`,
            reach_lair:
                () => `Find the way to where ${fact('person')} is held.`,
            find_person:
                () => `Find ${fact('person')} and establish their situation.`,
            defeat:
                () => `Defeat the threat holding ${fact('person')}.`
        },
        defeat_elite: {
            approach:
                () => `Reach ${fact('territory')} safely.`,
            track:
                () => `Follow the authored evidence of ${fact('target')}'s route.`,
            reach_lair:
                () => `Reach ${fact('target')}'s lair at ${fact('lair')}.`,
            find_target:
                () => `Locate ${fact('target')} using the authored signs.`,
            defeat:
                () => `Defeat the engine-linked threat: ${fact('target')}.`
        }
    }[family];

    assert(
        objectiveFor,
        `Unsupported V2 quest family: ${family}`
    );

    const gates = sequence.map((stage, index) => {
        const definition = QUEST_V2_STAGES[family]?.[stage];
        const objectiveBuilder = objectiveFor[stage];

        assert(
            definition && objectiveBuilder,
            `Missing authored definition for ${family}.${stage}`
        );

        return {
            step: index + 1,
            total: gateCount,
            stage,
            mode: definition.mode,
            trigger: definition.trigger,
            objective: objectiveBuilder(),
            decisive:
                definition.decisive === true ||
                (
                    family === 'rescue_person' &&
                    variantId === 'lost' &&
                    stage === 'find_person'
                )
        };
    });

    return validateQuestV2Structure({
        version: 2,
        family,
        variantId,
        gateCount,
        gates
    });
}

function buildQuestV2PlanForOffer(state, archetype, gateCount, facts, variantId = null) {
    const familyByArchetype = {
        sealed_cache: 'retrieve_item',
        field_job: 'retrieve_item',
        courier_recovery: 'retrieve_item',
        missing_person: 'rescue_person',
        dormant_hazard: 'defeat_elite',
        local_bounty: 'defeat_elite'
    };

    const family = familyByArchetype[archetype.id];
    if (!family) return null;

    let v2Facts;
    if (archetype.id === 'sealed_cache') {
        v2Facts = { item: facts.cache, destination: facts.place };
    } else if (archetype.id === 'field_job') {
        v2Facts = { item: facts.task, destination: facts.place };
    } else if (archetype.id === 'courier_recovery') {
        v2Facts = { item: facts.item, destination: facts.place };
    } else if (archetype.id === 'missing_person') {
        v2Facts = { person: facts.person, place: facts.place, evidence: facts.evidence, variantId };
    } else {
        v2Facts = { target: facts.threat, territory: facts.site, lair: facts.site };
    }

    const structureFacts =
        family === 'rescue_person'
            ? {
                ...v2Facts,
                rescueVariant: variantId
            }
            : v2Facts;

    if (family === 'rescue_person') {
        const validGateCounts =
            variantId === 'lost' ? [1, 2, 3] :
            variantId === 'abducted' ? [3, 4, 5] :
            [];

        assert(
            validGateCounts.includes(gateCount),
            `Missing Person variant ${variantId} does not support ${gateCount} gates`
        );
    }

    const structure = buildQuestV2Structure(
        family,
        gateCount,
        structureFacts
    );

    return {
        ...structure,
        facts: clone(v2Facts)
    };
}

function registerQuestDestination(state, quest) {
    state.places ||= {};
    state.leads ||= {};
    state.routeEdges ||= [];

    const label =
        quest.facts?.site ||
        quest.facts?.place ||
        quest.facts?.wreck;

    const destinationLabel =
        typeof label === 'string' && label.trim().length > 0
            ? label
            : `Quest destination, Zone ${quest.seed.zone}`;

    const placeId = `quest-place-${quest.id}`;
    const leadId = `quest-lead-${quest.id}`;

    const originSettlement = quest.originSettlementId
        ? Object.values(state.world?.settlements || {})
            .find(entry => entry.id === quest.originSettlementId)
        : savedPrimarySettlement(state, quest.seed.zone);

    assert(
        originSettlement,
        'Quest origin settlement is missing'
    );

    const originId =
        quest.originLocationId ||
        originSettlement.locationId;

    state.places[placeId] ||= {
        id: placeId,
        label: destinationLabel,
        zone: quest.seed.zone,
        kind: 'quest_site',
        visited: false
    };

    state.leads[leadId] ||= {
        id: leadId,
        kind: 'quest',
        label: `${quest.title}: ${destinationLabel}`,
        claim: quest.pitch,
        targetType: 'place',
        targetId: placeId,
        status: 'known'
    };

    if (!Array.isArray(state.routeEdges)) {
        state.routeEdges = [];
    }

    if (!state.routeEdges.some(edge =>
        (
            edge.fromId === originId &&
            edge.toId === placeId
        ) ||
        (
            edge.fromId === placeId &&
            edge.toId === originId
        )
    )) {
        state.routeEdges.push({
            fromId: originId,
            toId: placeId,
            length: 2
        });
    }

    quest.destinationId = placeId;

    quest.turnIn ||= {
        locationId: originSettlement.locationId,
        settlementId: originSettlement.id,
        recipient:
            quest.facts?.sponsor ||
            originSettlement.label
    };

    return { placeId, leadId };
}

function ensureQuestJournal(state) {
    state.quests ||= {};

    assert(
        state.quests &&
        typeof state.quests === 'object' &&
        !Array.isArray(state.quests),
        'state.quests must be an object'
    );

    for (const bucket of [
        'offered',
        'accepted',
        'completed',
        'failed',
        'declined',
        'abandoned',
        'cancelled'
    ]) {
        state.quests[bucket] ||= [];

        assert(
            Array.isArray(state.quests[bucket]),
            `state.quests.${bucket} must be an array`
        );
    }

    const active = state.activeQuest;

    if (
        active &&
        typeof active === 'object' &&
        typeof active.id === 'string'
    ) {
        const journalQuest = Object.values(state.quests)
            .flatMap(bucket => bucket)
            .find(quest => quest?.id === active.id);

        if (journalQuest) {
            /*
             * JSON reload may separate these objects. The journal owns
             * quest progress; reconnect the selected compatibility pointer
             * to its record rather than overwriting the record with a
             * potentially stale selection.
             */
            state.activeQuest = journalQuest;
        } else {
            /*
             * Import a genuinely journal-less legacy selected quest once.
             * Do not recreate an unsupported/retired quest as an offer.
             */
            const bucket = questJournalBucketForStatus(
                active.status
            );

            if (bucket) {
                state.quests[bucket].push(active);
            }
        }
    }

    return state.quests;
}

function questJournalBucketForStatus(status) {
    return {
        offered: 'offered',
        in_progress: 'accepted',
        complete: 'completed',
        failed: 'failed',
        declined: 'declined',
        abandoned: 'abandoned',
        cancelled: 'cancelled'
    }[status] || null;
}

function removeQuestFromJournal(state, questId) {
    ensureQuestJournal(state);

    for (const bucket of Object.values(state.quests)) {
        const index = bucket.findIndex(
            quest => quest?.id === questId
        );

        if (index >= 0) {
            bucket.splice(index, 1);
        }
    }
}

function saveQuestToJournal(state, quest) {
    assert(
        quest &&
        typeof quest.id === 'string' &&
        quest.id.length > 0,
        'Cannot save a quest without a stable ID'
    );

    const bucket = questJournalBucketForStatus(quest.status);

    assert(
        bucket,
        `Unsupported quest journal status: ${quest.status}`
    );

    removeQuestFromJournal(state, quest.id);
    state.quests[bucket].push(quest);

    if (state.activeQuest?.id === quest.id) {
        state.activeQuest = quest;
    }

    return quest;
}

function findQuestById(state, questId) {
    ensureQuestJournal(state);

    if (questId === undefined || questId === null) {
        return state.activeQuest || null;
    }

    assert(
        typeof questId === 'string' &&
        questId.length > 0,
        'Quest ID must be a non-empty string'
    );

    for (const bucket of Object.values(state.quests)) {
        const quest = bucket.find(
            entry => entry?.id === questId
        );

        if (quest) return quest;
    }

    return null;
}

function resolveQuestSeed(test) {
    assert(test.state && typeof test.state === 'object', 'quest requires state');
    const state = clone(test.state);
    state.inquiries ||= {};
    ensureQuestJournal(state);

    const zone = test.zone ?? state.zone;
    assert(Number.isInteger(zone) && ZONES[zone], `Unknown zone: ${zone}`);

    const issuerSettlement = questIssuerSettlement(state, test);
    assert(issuerSettlement.zone === zone, `Quest issuer ${issuerSettlement.label} is not in Zone ${zone}`);

    const repRecord = state.reputation?.[issuerSettlement.reputationKey];
    assert(repRecord, `No reputation record exists for ${issuerSettlement.label}`);
    const rep = normalizeQuestRepTier(test.repTier || repRecord.tier);

    const inquiryRecord = test.inquiryId !== undefined
        ? state.inquiries?.[`rumor:${test.inquiryId}`]
        : test.socialId !== undefined
            ? state.socialOpportunities?.contacts?.[`${issuerSettlement.id}:${test.socialId}`]
            : null;
    const breadcrumb = test.breadcrumbId !== undefined
        ? state.breadcrumbs?.[test.breadcrumbId]
        : null;

    assert(
        [test.inquiryId, test.socialId, test.breadcrumbId].filter(v => v !== undefined).length <= 1,
        'Quest offer requires only one named trigger'
    );
    assert(
        (test.inquiryId === undefined && test.socialId === undefined) || inquiryRecord,
        'Unknown locked quest trigger'
    );
    assert(test.breadcrumbId === undefined || breadcrumb, 'Unknown saved breadcrumb');

    const namedTrigger = inquiryRecord || breadcrumb;
    if (namedTrigger) assert(zone === namedTrigger.zone, 'Quest zone does not match its locked trigger');
    if (breadcrumb) assert(breadcrumb.settlementId === issuerSettlement.id, 'Breadcrumb issuer does not match its saved settlement');

    const trigger = namedTrigger || state.encounter;
    assert(trigger && typeof trigger === 'object', 'Quest offer requires an encounter or rumor inquiry');

    const sourceSeed = trigger.questSeed;
    assert(
        sourceSeed && ['genuine_unclaimed_quest_or_dungeon_hook', 'diegetic_quest_breadcrumb'].includes(sourceSeed.result),
        'Quest offer requires a locked quest-trigger seed'
    );
    // Each trigger produces at most one offer; active quests do not block new offers from distinct triggers.
    assert(trigger.questSeedConsumed !== true, 'This quest trigger was already consumed');

    const channel = sourceSeed.source === 'social'
        ? 'social'
        : (breadcrumb?.fromInstance === true || sourceSeed.fromInstance === true)
            ? 'instance'
            : 'overland';

    const availableRanks = rep.ranks
        .map(rank => ({ rank, archetypes: eligibleQuestArchetypes(state, zone, rank, channel) }))
        .filter(entry => entry.archetypes.length > 0);
    assert(
        availableRanks.length > 0,
        `No authored quest offers are available for Zone ${zone} at ${rep.label} reputation`
    );

    // Weight Rank F higher on a settlement's first social offer without guaranteeing it.
    const firstSocialOffer =
        test.socialId !== undefined &&
        state.socialOpportunities?.settlements?.[issuerSettlement.id]?.offers === 0;
    const rankPool = firstSocialOffer && availableRanks.some(entry => entry.rank === 'F')
        ? [...availableRanks, ...Array(2).fill(availableRanks.find(entry => entry.rank === 'F'))]
        : availableRanks;

    const questRoll = roll(state, rankPool.length);
    const selectedRank = rankPool[questRoll - 1];
    const gateCountRoll = roll(state, 2);
    const salvageSlotRoll = roll(state, QUEST_SALVAGE_SLOTS.length);

    const rank = selectedRank.rank;
    const row = QUEST_REWARD_TABLES[zone][rank];
    assert(row, 'No quest table entry exists for these inputs');

    const progression = QUEST_PROGRESSION[row.rank];
    assert(progression, `No quest progression settings for rank ${row.rank}`);

    const gates = progression.minGates +
        (gateCountRoll === 2 && progression.maxGates > progression.minGates ? 1 : 0);
    const referencePackXp = canonicalMixedPackXp(zone, state.crew.level);
    const questPackMultiplier =
        progression.packMultiplier + Math.max(0, gates - 1) * EXTRA_QUEST_GATE_PACK_MULTIPLIER;

    const terminalThreat = rollQuestTerminalThreat(state, row.rank, zone);
    const salvage = makeQuestSalvage(state, zone, salvageSlotRoll, row);

    // Exclude the settlement's last offered archetype when alternatives exist.
    state.lastQuestArchetypeBySettlement ||= {};
    const lastArchetypeId = state.lastQuestArchetypeBySettlement[issuerSettlement.id] || null;
    const nonRepeating = selectedRank.archetypes.filter(entry => entry.archetype.id !== lastArchetypeId);
    const eligibleArchetypes = nonRepeating.length > 0 ? nonRepeating : selectedRank.archetypes;
    const archetypeRoll = roll(state, eligibleArchetypes.length);
    const selectedArchetype = eligibleArchetypes[archetypeRoll - 1];
    const archetype = selectedArchetype.archetype;
    state.lastQuestArchetypeBySettlement[issuerSettlement.id] = archetype.id;

    const authored = buildQuestFacts(state, archetype, zone, selectedArchetype.scenarios, rank);
    if (archetype.id === 'local_bounty') {
        authored.facts.threat = terminalThreat.kind === 'normal_pack' ? 'the hostile group' : 'the dangerous foe';
    }

    const structureV2 = buildQuestV2PlanForOffer(state, archetype, gates, authored.facts, authored.variantId);
    assert(
        structureV2?.version === 2 && Array.isArray(structureV2.gates) && structureV2.gates.length === gates,
        `New quest archetype ${archetype.id} lacks a complete V2 plan`
    );

    // Non-combat contracts earn +0.5 pack XP to offset having no linked mob kills.
    const hasLinkedCombat = structureV2.gates.some(gate => gate.trigger === 'linked_combat');
    const finalPackMultiplier = questPackMultiplier + (hasLinkedCombat ? 0 : 0.5);
    const finalQuestXp = Math.round(referencePackXp * finalPackMultiplier);

    const questGatesData = clone(structureV2.gates);
    const seed = {
        zone,
        repTier: rep.label,
        questRoll,
        gateCountRoll,
        salvageSlotRoll,
        archetypeRoll,
        archetypeId: archetype.id,
        variantRoll: authored.variantRoll,
        variantId: authored.variantId,
        scenarioRoll: authored.scenarioRoll,
        source: sourceSeed.source,
        channel,
        sourceRoll: sourceSeed.roll,
        sourceResult: sourceSeed.result,
        terminalThreat: {
            kind: terminalThreat.kind,
            zone: terminalThreat.zone,
            roll: terminalThreat.roll
        }
    };

    const zoneSpine = state.world?.zones?.[zone]?.spine;
    let spineTieIn = 'independent';
    if (zoneSpine?.established === true) {
        if (channel === 'social') spineTieIn = roll(state, 10) <= 7 ? 'fallout' : 'ordinary';
        else if (channel === 'overland') spineTieIn = roll(state, 10) <= 4 ? 'ripple' : 'independent';
    }

    const triggerPrefix = breadcrumb
        ? breadcrumb.id
        : inquiryRecord
            ? (test.socialId !== undefined
                ? `social-${issuerSettlement.id}-${inquiryRecord.id}`
                : `rumor-${inquiryRecord.id}`)
            : state.encounter.id;

    const quest = {
        id: `quest-${triggerPrefix}-${row.rank}-${questRoll}-${archetype.id}`,
        title: `Rank ${row.rank} ${archetype.label}`,
        rank: row.rank,
        archetype: { id: archetype.id, label: archetype.label },
        variant: authored.variantId ? { id: authored.variantId } : null,
        gates,
        gatesData: questGatesData,
        structureV2,
        status: 'offered',
        seed,
        pitch: authored.pitch,
        facts: authored.facts,
        // Internal truth: never include in narrator-facing offer packets.
        coreTruth: authored.truth,
        currentGate: { ...questGatesData[0] },
        objectiveResolution: null,
        payout: {
            xp: finalQuestXp,
            silver: row.silver,
            repSteps: row.repSteps,
            xpBasis: referencePackXp,
            xpBasisType: 'canonical_mid_mixed_pack',
            packMultiplier: finalPackMultiplier
        },
        salvage,
        terminalThreat: {
            kind: terminalThreat.kind,
            zone: terminalThreat.zone,
            revealed: false,
            resolved: false
        },
        town: issuerSettlement.reputationKey,
        originSettlementId: issuerSettlement.id,
        originLocationId: issuerSettlement.locationId,
        repTierAtOffer: rep.label,
        requiresDelivery: !['sealed_cache', 'field_job'].includes(archetype.id),
        spineTieIn,
        targetId: null
    };

    quest.targetId = `quest-target-${quest.id}`;
    for (const gate of quest.gatesData) {
        if (gate.trigger === 'linked_combat') gate.linkedTargetId = quest.targetId;
    }
    if (quest.currentGate?.trigger === 'linked_combat') {
        quest.currentGate.linkedTargetId = quest.targetId;
    }

    registerQuestDestination(state, quest);
    quest.turnIn ||= {
        locationId: issuerSettlement.locationId,
        settlementId: issuerSettlement.id,
        recipient: quest.facts?.sponsor || issuerSettlement.label
    };

    saveQuestToJournal(state, quest);
    if (!state.activeQuest || !['offered', 'in_progress'].includes(state.activeQuest.status)) {
        state.activeQuest = quest;
    }

    prepareRetrievalQuestDiscovery(quest);
    prepareV2QuestDiscoveries(quest);
    validateRetrievalQuestDiscoveries(quest);

    trigger.questSeedConsumed = true;
    if (breadcrumb) {
        breadcrumb.questId = quest.id;
        if (state.encounter?.id === breadcrumb.encounterId) {
            state.encounter.questSeedConsumed = true;
        }
    }

    return { ok: true, created: true, quest, state };
}

/*
 * Retrieval offers must be complete when created. Validate their authored
 * requirements before consuming the trigger or saving the offer.
 *
 * This validates new offers only. Existing saved quests retain their locked
 * records and are not rewritten or rerolled by this check.
 */
function validateRetrievalQuestDiscoveries(quest) {
    if (quest.structureV2?.family !== 'retrieve_item') {
        return;
    }

    const discoveries = quest.discoveries || [];

    for (const gate of quest.gatesData) {
        if (gate.trigger !== 'discovery') continue;

        const discovery = discoveries.find(
            item => item.id === gate.requiredDiscoveryId
        );

        assert(
            discovery,
            `Retrieval gate ${gate.step} has no authored discovery`
        );

        assert(
            discovery.locationId === quest.destinationId &&
            typeof discovery.hidingPlace === 'string' &&
            discovery.hidingPlace.trim().length > 0 &&
            typeof discovery.significance === 'string' &&
            discovery.significance.trim().length > 0,
            `Retrieval gate ${gate.step} has incomplete discovery details`
        );

        assert(
            gate.requiredDiscoveryState === 'acquired' &&
            discovery.acquisitionPolicy === 'auto_on_reveal',
            `Retrieval gate ${gate.step} has incompatible acquisition rules`
        );
    }

    const finalGate = quest.gatesData.at(-1);
    const cargo = discoveries.find(
        item => item.id === quest.turnIn?.discoveryId
    );

    assert(
        finalGate?.stage === 'recover' &&
        finalGate.decisive === true &&
        cargo?.kind === 'quest_item' &&
        finalGate.requiredDiscoveryId === cargo.id,
        'Retrieval quest must recover and deliver the same authored cargo'
    );
}

function prepareRetrievalQuestDiscovery(quest) {
    if (
        quest?.structureV2?.family !== 'retrieve_item' ||
        !quest.destinationId
    ) {
        return null;
    }

    const type = quest.archetype?.id;
    const place = quest.facts?.place || 'the target site';
    const evidence = quest.facts?.evidence || 'signs at the site';
    const obstacle = quest.facts?.obstacle || 'the site obstacle';

    const specs = {
        sealed_cache: {
            subject: quest.facts?.cache,
            clue: 'cache-clue',
            approach: 'cache-approach',
            access: 'cache-release',
            final: 'sealed-cache',
            action: 'open_sealed_cache',
            cargo: false,
            finalSig: 'Opening and claiming this stash completes the contract immediately.'
        },
        field_job: {
            subject: quest.facts?.task,
            clue: 'open-clue',
            approach: 'open-approach',
            access: 'open-access',
            final: 'field-job-done',
            action: 'complete_field_job',
            cargo: false,
            finalSig: 'Completing this on-site task finishes the contract immediately.'
        },
        courier_recovery: {
            subject: quest.facts?.item,
            clue: 'open-clue',
            approach: 'open-approach',
            access: 'open-access',
            final: 'recovered-item',
            action: 'recover_item',
            cargo: true
        }
    };

    const spec = specs[type];
    if (!spec) return null;

    const subject = spec.subject || 'the objective';
    quest.discoveries ||= [];
    quest.turnIn ||= {
        locationId: quest.originLocationId,
        settlementId: quest.originSettlementId,
        recipient: spec.cargo ? (quest.facts?.sponsor || 'the sponsor') : 'System'
    };

    const definitions = {
        locate: {
            suffix: spec.clue,
            kind: 'evidence',
            name: `Lead pointing to ${subject}`,
            hidingPlace: `${evidence} at ${place}`,
            significance: `Pinpoints where ${subject} can be handled.`
        },
        reach_inner_site: {
            suffix: spec.approach,
            kind: 'evidence',
            name: `Way past ${obstacle}`,
            hidingPlace: `within ${place}`,
            significance: `Clears or bypasses ${obstacle} to reach ${subject}.`
        },
        find_access: {
            suffix: spec.access,
            kind: 'evidence',
            name: `Means to access ${subject}`,
            hidingPlace: `at ${place}`,
            significance: `Gives direct access to complete or recover ${subject}.`
        },
        recover: {
            suffix: spec.final,
            kind: 'quest_item',
            name: subject,
            hidingPlace: `at ${place}, beyond ${obstacle}`,
            significance:
                spec.finalSig ||
                `Must be brought back to ${quest.turnIn.recipient || 'the sponsor'}.`,
            requiredAction: spec.action,
            questCargo: spec.cargo
        }
    };

    for (const gate of quest.gatesData) {
        const def = definitions[gate.stage];
        if (!def || gate.trigger !== 'discovery') continue;

        const id = `${quest.id}-${def.suffix}`;
        let discovery = quest.discoveries.find(item => item.id === id);

        if (!discovery) {
            discovery = {
                id,
                kind: def.kind,
                name: def.name,
                locationId: quest.destinationId,
                state: 'hidden',
                acquisitionPolicy: 'auto_on_reveal',
                hidingPlace: def.hidingPlace,
                significance: def.significance,
                ...(def.requiredAction ? { requiredAction: def.requiredAction } : {}),
                ...(def.questCargo ? { questCargo: true } : {})
            };
            quest.discoveries.push(discovery);
        }

        gate.requiredDiscoveryId = id;
        gate.requiredDiscoveryState = 'acquired';

        if (quest.currentGate?.step === gate.step) {
            quest.currentGate.requiredDiscoveryId = id;
            quest.currentGate.requiredDiscoveryState = 'acquired';
        }
    }

    const finalId = `${quest.id}-${spec.final}`;
    assert(
        quest.discoveries.some(item => item.id === finalId),
        `${type} has no final discovery`
    );

    quest.turnIn.discoveryId = finalId;
    return quest.discoveries.find(item => item.id === finalId);
}

 function prepareV2QuestDiscoveries(quest) {
    const family = quest?.structureV2?.family;

    if (
        quest?.status !== 'in_progress' ||
        !['defeat_elite', 'rescue_person'].includes(family) ||
        !quest.destinationId
    ) {
        return null;
    }

    quest.discoveries ||= [];

    function bind(stage, definition) {
        const gate = quest.gatesData.find(
            entry =>
                entry.stage === stage &&
                entry.trigger === 'discovery'
        );

        if (!gate) return null;

        const id = `${quest.id}-${definition.suffix}`;
        let discovery = quest.discoveries.find(
            item => item.id === id
        );

        if (!discovery) {
            discovery = {
                id,
                kind: 'evidence',
                name: definition.name,
                locationId: quest.destinationId,
                state: 'hidden',
                acquisitionPolicy: 'auto_on_reveal',
                hidingPlace: definition.hidingPlace,
                significance: definition.significance
            };
            quest.discoveries.push(discovery);
        }

        gate.requiredDiscoveryId = id;
        gate.requiredDiscoveryState = 'acquired';

        if (quest.currentGate?.step === gate.step) {
            quest.currentGate.requiredDiscoveryId = id;
            quest.currentGate.requiredDiscoveryState = 'acquired';
        }

        return discovery;
    }

    const target =
        family === 'rescue_person'
            ? quest.facts.person
            : quest.structureV2.facts.target;

    const trail = bind('track', {
        suffix: 'target-trail',
        name: `Fresh signs of ${target}`,
        hidingPlace:
            quest.facts?.evidence ||
            'among the recent signs at the quest site',
        significance:
            `The signs show the route taken by ${target}.`
    });
    if (family === 'defeat_elite') {
        /*
         * Longer structures stay at the established quest destination.
         * These are local discoveries, not repeat arrivals or new map nodes.
         * Finding the target reveals the linked fight through clear_gate;
         * it does not engage or defeat that encounter.
         */
        const targetName = quest.structureV2.facts.target;

        const lair = bind('reach_lair', {
            suffix: 'lair-route',
            name: `Route to ${targetName}'s lair`,
            hidingPlace:
                quest.facts?.evidence ||
                'among the signs at the quest site',
            significance:
                `The signs establish a route through ${quest.facts?.obstacle || 'the site'} toward ${targetName}.`
        });

        const foundTarget = bind('find_target', {
            suffix: 'target-location',
            name: `Location of ${targetName}`,
            hidingPlace:
                `at ${quest.structureV2.facts.lair}`,
            significance:
                `The signs establish where ${targetName} can be confronted.`
        });

        return trail || lair || foundTarget;
    }

    const variantId = quest.variant?.id;

    assert(
        variantId === 'lost' || variantId === 'abducted',
        'Missing Person requires a saved lost or abducted variant'
    );

    const lair = bind('reach_lair', {
        suffix: 'holding-place',
        name: `Way to ${target}'s holding place`,
        hidingPlace: `along the trail beyond ${quest.facts.place}`,
        significance:
            `The signs establish a way past ${quest.facts.obstacle}.`
    });

    const person = bind('find_person', {
        suffix: 'missing-person',
        name: `Found ${target}`,
        hidingPlace:
            variantId === 'lost'
                ? `beyond ${quest.facts.evidence}`
                : `at the established holding place beyond ${quest.facts.place}`,
        significance:
            variantId === 'lost'
                ? `${target} is alive and can return to ${quest.turnIn.recipient}.`
                : `${target} is alive, but the linked threat still holds them.`
    });

    return person || trail || lair;
}


function advanceQuestFromDiscovery(state, discovery, questId) {
    assert(
        typeof questId === 'string' &&
        questId.length > 0,
        'Discovery progression requires an explicit questId'
    );

    const quest = findQuestById(state, questId);
    const gate = quest?.currentGate;
    const requiredState = gate?.requiredDiscoveryState || 'acquired';

    const satisfied =
        gate?.requiredDiscoveryId === discovery.id &&
        (
            discovery.state === requiredState ||
            (
                requiredState === 'found' &&
                discovery.state === 'acquired'
            )
        );

    if (!satisfied) {
        return { state, questGate: null };
    }

    assert(
        !['active', 'spotted'].includes(state.encounter?.status),
        'Resolve or avoid the encounter before completing this gate'
    );

    const evidence =
        `Secured ${discovery.name} at ` +
        `${state.places?.[discovery.locationId]?.label ||
            discovery.locationId}.`;

    if (gate.step < quest.gates) {
        const progression = resolveQuestAction({
            state,
            questId,
            action: 'clear_gate',
            objectiveCompleted: true,
            completionEvidence: evidence
        });

                return {
            state: progression.state,
            questGate: {
                questId: quest.id,
                completed: progression.completedGate,
                next: progression.nextGate,
                linkedEncounter: progression.linkedEncounter || null
            }
        };
    }

    if (quest.objectiveResolution) {
        return { state, questGate: null };
    }

    const progression = resolveQuestAction({
        state,
        questId,
        action: 'resolve_objective',
        objectiveCompleted: true,
        objectiveRoute:
            gate.mode === 'combat_twist_showdown'
                ? 'combat'
                : gate.mode === 'brain_social_heist'
                    ? 'heist'
                    : 'other',
        completionEvidence: evidence
    });

    const updatedQuest = findQuestById(
        progression.state,
        questId
    );
    updatedQuest.completedGates ||= [];

    if (!updatedQuest.completedGates.some(item => item.step === gate.step)) {
        updatedQuest.completedGates.push({
            ...gate,
            completionEvidence: evidence
        });
    }
    // resolve_objective completes ordinary quests immediately and creates
    // the safety-return lead itself for Missing Person quests.
    return {
        state: progression.state,
        questGate: {
            questId,
            completed: clone(gate),
            next: null,
            objectiveSecured: true,
            questCompletion: progression.questCompletion || null
        }
    };
}

function findQuestByDiscoveryId(state, discoveryId) {
    assert(
        typeof discoveryId === 'string' &&
        discoveryId.length > 0,
        'Quest discovery requires a stable discovery ID'
    );

    const journal = ensureQuestJournal(state);
    const matches = journal.accepted.filter(
        quest =>
            quest?.status === 'in_progress' &&
            quest.discoveries?.some(
                discovery => discovery.id === discoveryId
            )
    );

    assert(
        matches.length <= 1,
        `Discovery ${discoveryId} belongs to multiple quests`
    );

    return matches[0] || null;
}

function resolveQuestEvent(test) {
    assert(
        test.state &&
        typeof test.state === 'object',
        'Quest event requires state'
    );

    const state = clone(test.state);
    ensureQuestJournal(state);

    const quest =
        test.questId !== undefined
            ? findQuestById(state, test.questId)
            : findQuestByDiscoveryId(state, test.questItemId);

    /*
     * On-site contracts (field_job, sealed_cache) complete immediately on
     * their decisive FOUND event and move into journal.completed. A
     * duplicate render notification for the same assistant reply must
     * return a no-op instead of rejecting as missing.
     */
    if (test.event === 'found') {
        const completedOwner =
            quest?.status === 'complete'
                ? quest
                : !quest && test.questId === undefined
                    ? state.quests.completed.find(
                        entry =>
                            entry?.status === 'complete' &&
                            entry.discoveries?.some(
                                item => item.id === test.questItemId
                            )
                    )
                    : null;

        const completedDiscovery = completedOwner?.discoveries?.find(
            item => item.id === test.questItemId
        );

        if (
            completedDiscovery &&
            ['acquired', 'delivered'].includes(completedDiscovery.state)
        ) {
            return {
                ok: true,
                created: false,
                action: 'quest_event',
                event: test.event,
                discovery: clone(completedDiscovery),
                state
            };
        }
    }

    assert(
        quest?.status === 'in_progress',
        test.questId !== undefined
            ? `Quest ${test.questId} is not in progress`
            : `No in-progress quest owns discovery ${test.questItemId}`
    );

    return resolveSelectedQuestEvent({
        ...test,
        questId: quest.id,
        state
    });
}

function resolveSelectedQuestEvent(test) {
    assert(
        test.state && typeof test.state === 'object',
        'Quest event requires state'
    );

    const state = clone(test.state);
    ensureQuestJournal(state);

    assert(
        typeof test.questId === 'string' &&
        test.questId.length > 0,
        'Quest event requires an explicit questId'
    );

    const quest = findQuestById(state, test.questId);

    assert(
        quest?.status === 'in_progress',
        `Quest ${test.questId} is not in progress`
    );

    assert(
        test.event === 'found',
        `Unsupported quest discovery event: ${test.event}`
    );

    /*
     * Older saved Missing Cargo quests may reach the recovery gate
     * without its authored cargo ID copied onto currentGate. Re-run the
     * idempotent preparation after selecting the owning quest so the
     * search action can be authorized and validated.
     */
    if (quest.structureV2?.family === 'retrieve_item') {
        prepareRetrievalQuestDiscovery(quest);
    }

    const discovery = (quest.discoveries || []).find(
        item => item.id === test.questItemId
    );

    assert(discovery, 'Unknown authored quest discovery');
    assert(
        state.currentLocationId === discovery.locationId,

        'Quest discovery is at the wrong location'
    );

    // Repeated message/render events must not acquire or advance twice.
    if (discovery.state === 'acquired') {
        return {
            ok: true,
            created: false,
            action: 'quest_event',
            event: test.event,
            discovery: clone(discovery),
            state
        };
    }

    const gate = quest.currentGate;
    const allowedIds = [
        ...(gate?.discoveryIds || []),
        ...(gate?.requiredDiscoveryId
            ? [gate.requiredDiscoveryId]
            : [])
    ];

    assert(
        allowedIds.includes(discovery.id),
        'Discovery is not authorized for the current gate'
    );

    assert(
        ['hidden', 'searched', 'found'].includes(discovery.state),
        `Cannot find discovery from state ${discovery.state}`
    );

    const isImmediateOnSiteCompletion =
        gate?.step === quest.gates &&
        !quest.objectiveResolution &&
        !(quest.structureV2?.family === 'retrieve_item' && quest.requiresDelivery !== false) &&
        quest.structureV2?.family !== 'rescue_person';

    if (test.deferCompletion === true && isImmediateOnSiteCompletion) {
        state.pendingQuestCompletions ||= [];
        const pendingId = `found:${discovery.id}`;
        if (state.pendingQuestCompletions.some(entry => entry.id === pendingId)) {
            return {
                ok: true,
                created: false,
                deferred: true,
                action: 'quest_event',
                event: 'found',
                questId: quest.id,
                discovery: clone(discovery),
                state
            };
        }

        state.pendingQuestCompletions.push({
            id: pendingId,
            kind: 'quest_event',
            event: 'found',
            questId: quest.id,
            questItemId: discovery.id
        });

        return {
            ok: true,
            created: true,
            deferred: true,
            action: 'quest_event',
            event: 'found',
            questId: quest.id,
            discovery: clone(discovery),
            state
        };
    }

    discovery.state = discovery.acquisitionPolicy === 'auto_on_reveal'
        ? 'acquired'
        : 'found';

    const progression = advanceQuestFromDiscovery(
        state,
        discovery,
        quest.id
    );

    if (Array.isArray(progression.state.pendingQuestCompletions)) {
        progression.state.pendingQuestCompletions =
            progression.state.pendingQuestCompletions.filter(
                entry => entry.id !== `found:${discovery.id}`
            );
    }

    const updatedQuest = findQuestById(
        progression.state,
        quest.id
    );

    const updatedDiscovery = updatedQuest?.discoveries?.find(
        item => item.id === discovery.id
    );

    assert(
        updatedQuest && updatedDiscovery,
        `Discovery progression lost quest ${quest.id} or item ${discovery.id}`
    );

    /*
     * Crew Knowledge records what was actually exposed, not hidden quest
     * preparation or a SEARCHED prerequisite. The discovery ID makes this
     * observation stable across duplicate notifications and reloads.
     */
    recordCrewKnowledge(progression.state, {
        id: `knowledge-quest-discovery-${updatedDiscovery.id}`,
        kind: 'quest_discovery',
        knowledgeType: 'observation',
        certainty: 'engine_established',
        summary:
            `Found ${updatedDiscovery.name}. ${updatedDiscovery.significance}`,
        source: {
            id: quest.id,
            type: 'quest'
        },
        learnedAtLocationId: updatedDiscovery.locationId,
        learnedAtZone:
            progression.state.places?.[updatedDiscovery.locationId]?.zone ??
            progression.state.zone
    });

    return {
        ok: true,
        created: true,
        action: 'quest_event',
        event: 'found',
        questId: quest.id,
        quest: clone(updatedQuest),
        discovery: clone(updatedDiscovery),
        questGate: progression.questGate,
        state: progression.state
    };
}

/*
 * QUEST DELIVERY MODEL
 *
 * Field objective completion and quest delivery are separate:
 *
 * 1. The extension detects that the field objective and cargo are secured.
 * 2. Returning to quest.turnIn.locationId sets deliveryReady, but does not
 *    pay rewards or mark the quest complete.
 * 3. The narrator stages the fictional handoff with the quest giver.
 * 4. The assistant may emit the validated protocol event:
 *
 *    <AETHERMOOR:DELIVERED quest_id=...>
 *
 * 5. The extension validates quest ID, location, acquired cargo, and
 *    deliveryReady, then completes the quest and applies rewards exactly once.
 *
 * The LLM never supplies XP, silver, reputation, loot, or quest identity.
 * It only confirms the fictional handoff after the extension has made it
 * mechanically eligible.
 *
 * Future HUD work:
 * Mechanical state should eventually render the HUD directly from saved
 * state. Until then, completion packets provide the next narrator reply
 * with authoritative post-delivery values.
 */


function resolveQuestAction(test) {
    assert(test.state && typeof test.state === 'object', 'quest action requires state');
    const state = clone(test.state);
    ensureQuestJournal(state);

    const quest = findQuestById(state, test.questId);
    assert(
        quest && typeof quest === 'object',
        test.questId != null ? `Unknown quest ID: ${test.questId}` : 'No selected quest'
    );
    assert(
        ['accept', 'decline', 'cancel', 'fail', 'clear_gate', 'resolve_objective', 'complete'].includes(test.action),
        `Unsupported quest action: ${test.action}`
    );

    state.inventory ||= {};
    state.inventory.bagReserves ||= [];
    state.inventory.activeTradeListings ||= [];

    const result = {
        ok: true,
        action: test.action,
        questId: quest.id,
        quest,
        rewards: { xp: 0, silver: 0, repSteps: 0, loot: [] },
        state
    };

    // Shared cleanup when a quest closes (declined, cancelled, failed, or completed).
    // MSQ chapters fail forward (advanceMsq = true) so a failed chapter never bricks the zone arc.
    function finalizeQuestClosure(advanceMsq) {
        if (quest.isMsq === true) {
            const msqZone = quest.msq?.zone ?? quest.seed?.zone ?? state.zone;
            const msq = state.world?.zones?.[msqZone]?.msq;
            if (msq) {
                msq.activeQuestId = null;
                 if (advanceMsq) {
                    msq.completedChapters = Math.max(Number(msq.completedChapters || 0), Number(quest.msq?.chapter || 0));
                    if (quest.msq?.isClimax || quest.msq?.phase === 'finale' || msq.completedChapters >= msq.totalChapters) {
                        msq.status = 'completed';
                        msq.pendingBeatDelay = 0;
                    } else {
                        const nextChapter = msq.completedChapters + 1;
                        const hotLead = nextChapter >= msq.totalChapters ||
                            (worldHash(`${state.world.seed}:msq-pace:${msqZone}:${nextChapter}`) % 2 === 0);
                        msq.pendingBeatDelay = hotLead
                            ? 1
                            : 2 + (worldHash(`${state.world.seed}:msq-delay:${msqZone}:${nextChapter}`) % 2);
                    }
                } else {
                    msq.status = 'declined';
                }
            }
        }
        for (const lead of Object.values(state.leads || {})) {
            if (lead.id === `quest-return-${quest.id}` || lead.id === `quest-lead-${quest.id}`) {
                lead.status = 'resolved';
            }
        }
        if (Array.isArray(state.pendingQuestCompletions)) {
            state.pendingQuestCompletions = state.pendingQuestCompletions.filter(
                entry => entry.questId !== quest.id
            );
        }
        if (state.activeQuest?.id === quest.id) state.activeQuest = null;
    }

    if (test.action === 'accept') {
        assert(quest.status === 'offered', `Quest cannot be accepted from status ${quest.status}`);
        const selectedQuestIsInProgress = state.activeQuest?.status === 'in_progress';

        registerQuestDestination(state, quest);
        quest.status = 'in_progress';
        if (!selectedQuestIsInProgress) state.activeQuest = quest;

        if (quest.structureV2?.version === 2) {
            prepareRetrievalQuestDiscovery(quest);
            prepareV2QuestDiscoveries(quest);

            for (const gate of quest.gatesData) {
                if (gate.trigger !== 'discovery') continue;
                const discovery = quest.discoveries?.find(item => item.id === gate.requiredDiscoveryId);
                assert(
                    discovery &&
                    gate.requiredDiscoveryState === 'acquired' &&
                    discovery.locationId === quest.destinationId &&
                    discovery.acquisitionPolicy === 'auto_on_reveal' &&
                    typeof discovery.hidingPlace === 'string' && discovery.hidingPlace.trim().length > 0 &&
                    typeof discovery.significance === 'string' && discovery.significance.trim().length > 0,
                    `Quest ${quest.id} has no complete authored discovery for gate ${gate.step}`
                );
            }
        }

        saveQuestToJournal(state, quest);
        return result;
    }

    if (test.action === 'decline') {
        assert(quest.status === 'offered', `Quest cannot be declined from status ${quest.status}`);
        quest.status = 'declined';
        saveQuestToJournal(state, quest);
        finalizeQuestClosure(false);
        return result;
    }

    assert(quest.status === 'in_progress', `Quest action requires an in-progress quest, got ${quest.status}`);

    if (test.action === 'cancel' || test.action === 'fail') {
        assert(
            !['active', 'spotted'].includes(state.encounter?.status),
            'Resolve, avoid, or flee the encounter before closing the quest'
        );

        const isCancel = test.action === 'cancel';
        quest.status = isCancel ? 'cancelled' : 'failed';
        quest.cancelledAtGate = isCancel ? quest.currentGate?.step || null : undefined;
        quest.failedAtGate = !isCancel ? quest.currentGate?.step || null : undefined;
        quest.cancelReason = isCancel ? test.reason || null : undefined;
        quest.failReason = !isCancel ? test.reason || null : undefined;

        // Stop travel undertaken solely for this quest while preserving route position.
        const journey = state.currentJourney;
        const anotherQuestUsesDestination = state.quests.accepted.some(entry =>
            entry.id !== quest.id &&
            entry.status === 'in_progress' &&
            !entry.objectiveResolution &&
            entry.destinationId === journey?.destinationId
        );

        if (
            journey &&
            (journey.questId === quest.id ||
                (!journey.questId && journey.destinationId === quest.destinationId && !anotherQuestUsesDestination))
        ) {
            state.currentPosition =
                positionAfterSegments(journeyLegs(journey), journey.completedSegments) ||
                state.currentPosition ||
                { nodeId: state.currentLocationId };
            state.currentJourney = null;
        }

        saveQuestToJournal(state, quest);
        finalizeQuestClosure(!isCancel);
        return result;
    }

    if (test.action === 'clear_gate') {
        assert(
            Array.isArray(quest.gatesData) && quest.gatesData.length === quest.gates,
            'This legacy quest has no engine-authored gate plan'
        );
        assert(quest.currentGate?.step < quest.gates, 'Last gate must use resolve_objective before complete');
        assert(test.objectiveCompleted === true, 'Gate clearance requires objectiveCompleted: true');
        assert(
            typeof test.completionEvidence === 'string' && test.completionEvidence.trim().length > 0,
            'Gate clearance requires completionEvidence'
        );
        assert(state.encounter?.status !== 'active', 'Resolve or flee the active encounter first');

        const completedGate = { ...quest.currentGate, completionEvidence: test.completionEvidence.trim() };
        quest.completedGates ||= [];
        quest.completedGates.push(completedGate);

        quest.currentGate = { ...quest.gatesData[completedGate.step] };
        result.completedGate = completedGate;
        result.nextGate = { ...quest.currentGate };

        if (
            quest.currentGate.trigger === 'linked_combat' &&
            ['defeat_elite', 'rescue_person'].includes(quest.structureV2?.family)
        ) {
            const spawned = spawnEncounter({
                state,
                questId: quest.id,
                encounterType: 'quest_terminal',
                encounterId: `quest-terminal-${quest.id}`
            });
            state.rngState = spawned.state.rngState;
            state.encounter = spawned.encounter;
            state.encounter.status = 'spotted';
            state.encounter.questTerminal.targetId = quest.targetId;

            quest.terminalThreat.revealed = true;
            quest.terminalThreat.resolved = false;
            quest.terminalThreat.encounterId = state.encounter.id;
            quest.terminalThreat.targetId = quest.targetId;

            const leadFoe = state.encounter.foes[0];
            result.linkedEncounter = {
                id: state.encounter.id,
                targetId: quest.targetId,
                status: 'spotted',
                role: leadFoe?.role,
                level: leadFoe?.level,
                hp: leadFoe?.hp,
                maxHp: leadFoe?.maxHp
            };
        }

        return result;
    }

    if (test.action === 'resolve_objective') {
        assert(quest.currentGate?.step === quest.gates, 'Reach the final quest gate before resolving its objective');
        assert(!quest.objectiveResolution, 'Quest objective has already been resolved');
        assert(test.objectiveCompleted === true, 'Objective resolution requires objectiveCompleted: true');
        assert(
            typeof test.completionEvidence === 'string' && test.completionEvidence.trim().length > 0,
            'Objective resolution requires completionEvidence'
        );
        assert(
            ['combat', 'heist', 'negotiation', 'other'].includes(test.objectiveRoute),
            'Objective resolution requires a supported objectiveRoute'
        );
        assert(state.encounter?.status !== 'active', 'Resolve or flee the active encounter first');
        if (test.objectiveRoute === 'combat') {
            assert(quest.terminalThreat?.resolved === true, 'Combat route requires the linked threat to be defeated');
        }

        quest.objectiveResolution = {
            route: test.objectiveRoute,
            evidence: test.completionEvidence.trim()
        };
        result.objectiveResolution = quest.objectiveResolution;

        const cargoDelivery = quest.structureV2?.family === 'retrieve_item' && quest.requiresDelivery !== false;
        if (cargoDelivery || quest.structureV2?.family === 'rescue_person') {
            state.leads ||= {};
            const returnLeadId = `quest-return-${quest.id}`;
            const cargoName = cargoDelivery
                ? quest.discoveries?.find(item => item.id === quest.turnIn?.discoveryId)?.name
                : null;
            if (cargoDelivery) assert(cargoName, 'Retrieval quest has no locked turn-in cargo');

            state.leads[returnLeadId] ||= {
                id: returnLeadId,
                kind: 'quest_return',
                label: cargoDelivery ? `Deliver ${cargoName}` : `Bring ${quest.facts.person} to safety`,
                claim: cargoDelivery
                    ? `Bring ${cargoName} to ${quest.turnIn.recipient}.`
                    : `${quest.facts.person} must reach the origin settlement safely.`,
                targetType: 'place',
                targetId: quest.turnIn.locationId,
                status: 'known'
            };

            if (cargoDelivery) quest.deliveryReady = false;
            saveQuestToJournal(state, quest);
            return result;
        }

        const completion = resolveQuestAction({
            state,
            questId: quest.id,
            action: 'complete',
            objectiveCompleted: true,
            completionEvidence: quest.objectiveResolution.evidence
        });
        return {
            ...result,
            state: completion.state,
            quest: completion.quest,
            questCompletion: {
                questId: quest.id,
                title: completion.quest.title,
                rank: completion.quest.rank,
                isMsq: completion.quest.isMsq === true,
                rewards: completion.rewards,
                levelUps: completion.levelUps || []
            }
        };

    }

    // action === 'complete'
    assert(test.objectiveCompleted === true, 'Quest completion requires objectiveCompleted: true');
    assert(
        typeof test.completionEvidence === 'string' && test.completionEvidence.trim().length > 0,
        'Quest completion requires completionEvidence'
    );
    assert(state.encounter?.status !== 'active', 'Cannot complete a quest during an active encounter');
    assert(
        quest.objectiveResolution && typeof quest.objectiveResolution.evidence === 'string',
        'Secure the quest objective before turning it in'
    );
    assert(quest.currentGate.step === quest.gates, 'Quest cannot complete before its final gate');

    if (quest.structureV2?.family === 'retrieve_item' && quest.requiresDelivery !== false) {
        assert(
            quest.deliveryReady === true && state.currentLocationId === quest.turnIn?.locationId && !state.currentJourney,
            'Return to the locked recipient with the quest cargo before completion'
        );
    }

    const { payout, salvage } = quest;
    assert(
        payout && Number.isInteger(payout.xp) && Number.isInteger(payout.silver) && Number.isInteger(payout.repSteps),
        'Quest payout is invalid'
    );
    assert(salvage && typeof salvage === 'object', 'Quest salvage is missing');

    if (quest.structureV2?.family === 'retrieve_item' && quest.requiresDelivery !== false) {
        const cargo = quest.discoveries?.find(item => item.id === quest.turnIn?.discoveryId);
        assert(cargo?.kind === 'quest_item' && cargo.state === 'acquired', 'The required quest cargo has not been recovered');
        cargo.state = 'delivered';
        quest.deliveryReady = false;
    }

    if (quest.structureV2?.family === 'rescue_person') {
        assert(
            state.currentLocationId === quest.originLocationId && !state.currentJourney,
            'Bring the missing person to the origin settlement safely'
        );
    }

    quest.status = 'complete';
    quest.completionEvidence = test.completionEvidence.trim();
    saveQuestToJournal(state, quest);
    finalizeQuestClosure(true);

    result.rewards.xp = payout.xp;
    result.rewards.silver = payout.silver;
    result.rewards.repSteps = payout.repSteps;

    const acquiredSalvage = {
        ...salvage,
        acquiredFrom: 'quest',
        acquiredAtQuest: quest.id,
        bound: false
    };
    state.inventory.bagReserves.push(acquiredSalvage);
    result.rewards.loot.push(acquiredSalvage);

    const town = test.town || quest.town;
    if (town) {
        state.reputation ||= {};
        state.reputation[town] ||= { tier: 'Unknown', steps: 0 };

        const tierOrder = ['Unknown', 'Slightly Known', 'Known', 'Well Respected', 'Renowned'];
        const rep = state.reputation[town];
        let rung = tierOrder.indexOf(rep.tier);
        assert(rung >= 0, `Unknown reputation tier: ${rep.tier}`);

        const stepsPerTier = QUEST_REPUTATION_STEPS_PER_TIER;
        int(rep.steps, `${town} reputation steps`);
        assert(
            rep.steps < stepsPerTier || rung === tierOrder.length - 1,
            `${town} reputation steps must be below ${stepsPerTier}`
        );

        let steps = rep.steps + payout.repSteps;
        while (steps >= stepsPerTier && rung < tierOrder.length - 1) {
            steps -= stepsPerTier;
            rung++;
        }
        rep.tier = tierOrder[rung];
        rep.steps = rung === tierOrder.length - 1 ? 0 : steps;
    }

    result.levelUps = applyXp(state.crew, payout.xp);
    state.crew.purse += payout.silver;
    return result;
}

function equipBagItem(stateInput, itemIndex) {
    assert(stateInput && typeof stateInput === 'object', 'gear equip requires state');
    const state = clone(stateInput);

    assert(
        state.crew && state.inventory && Array.isArray(state.inventory.bagReserves),
        'Gear equip requires crew and inventory.bagReserves'
    );
    int(itemIndex, 'itemIndex');
    assert(itemIndex < state.inventory.bagReserves.length, `No bag item at index ${itemIndex}`);

    const item = state.inventory.bagReserves[itemIndex];
    assert(item?.owner && ['tansy', 'qtik'].includes(item.owner), 'Item is not equippable by the crew');
    assert(!item.classRestricted, 'Class-restricted item cannot be equipped');
    assert(typeof item.slot === 'string', 'Gear item has no equipment slot');
    assert(Number.isInteger(item.rawStat) && item.rawStat > 0, 'Gear item needs a positive rawStat');

    const ownerSlots = item.owner === 'tansy' ? TANSY_SLOTS : QTIK_SLOTS;
    assert(ownerSlots.includes(item.slot), `Invalid ${item.owner} equipment slot: ${item.slot}`);

    if (item.owner === 'tansy' && MODULAR_TANSY.has(item.slot)) {
        assert(['vitality', 'luck'].includes(item.variant), `Tansy ${item.slot} requires vitality or luck variant`);
    }
    if (item.owner === 'qtik') {
        assert(['vitality', 'bulwark'].includes(item.variant), `Q'tik ${item.slot} requires vitality or bulwark variant`);
    }

    const oldDerived = derived(state.crew);
    const character = state.crew[item.owner];
    const oldItem = state.crew.gear[item.owner][item.slot] || null;
    const equippedItem = {
        ...item,
        stat: item.rawStat,
        bound: true,
        classRestricted: false,
        tradeStreamEligible: false
    };

    // Remove the selected reserve item before pushing any replaced gear.
    state.inventory.bagReserves.splice(itemIndex, 1);

    if (oldItem && Number(oldItem.stat) > 0) {
        state.inventory.bagReserves.push({
            ...oldItem,
            name: oldItem.name || 'Replaced gear',
            owner: item.owner,
            slot: item.slot,
            rawStat: oldItem.stat,
            bound: Boolean(oldItem.bound),
            classRestricted: false,
            tradeStreamEligible: oldItem.bound !== true,
            sellValue: oldItem.sellValue ?? 2 * oldItem.stat,
            bonus: lootBonus(item.owner, item.slot, oldItem.variant || null, oldItem.stat)
        });
    }

    state.crew.gear[item.owner][item.slot] = equippedItem;
    const newDerived = derived(state.crew);

    // Adjust current HP by the MaxHP delta and clamp to the new maximum.
    const maxKey = item.owner === 'qtik' ? 'qtikMaxHp' : 'tansyMaxHp';
    character.hp = Math.max(0, Math.min(newDerived[maxKey], character.hp + (newDerived[maxKey] - oldDerived[maxKey])));

    state.crew.qtik.maxHp = newDerived.qtikMaxHp;
    state.crew.qtik.def = newDerived.def;
    state.crew.qtik.regen = newDerived.regen;
    state.crew.tansy.maxHp = newDerived.tansyMaxHp;

    return {
        ok: true,
        equipped: equippedItem,
        replaced: oldItem,
        derivedBefore: oldDerived,
        derivedAfter: newDerived,
        state
    };
}

function resolveTradeAction(test) {
    assert(test.state && typeof test.state === 'object', 'trade action requires state');
    const state = clone(test.state);

    state.crew ||= {};
    state.crew.purse = Number(state.crew.purse || 0);
    state.inventory ||= {};
    state.inventory.bagReserves ||= [];
    state.inventory.activeTradeListings ||= [];
    state.inventory.tradeHistory ||= [];

    assert(Array.isArray(state.inventory.bagReserves), 'inventory.bagReserves must be an array');
    assert(Array.isArray(state.inventory.activeTradeListings), 'inventory.activeTradeListings must be an array');
    assert(
        ['list', 'withdraw', 'settle', 'settle_all'].includes(test.action),
        `Unsupported trade action: ${test.action}`
    );

    const result = { ok: true, action: test.action, silverGained: 0, item: null, state };

    if (test.action === 'list') {
        int(test.itemIndex, 'itemIndex', 0);
        assert(state.inventory.activeTradeListings.length < 3, 'Aether-Net already has three active listings');
        assert(test.itemIndex < state.inventory.bagReserves.length, `No bag item at index ${test.itemIndex}`);

        const item = state.inventory.bagReserves[test.itemIndex];
        assert(
            item && item.bound !== true && item.tradeStreamEligible !== false,
            'Only unbound Aether-Net-eligible gear may be listed'
        );

        const tradeStat = Number(item.tradeStat || item.rawStat);
        assert(Number.isInteger(tradeStat) && tradeStat > 0, 'Listed item needs a positive trade value');

        const tradeRoll = roll(state, 6);
        const rarity = String(item.rarity || 'Common').toLowerCase();
        const tierIdx = rarity === 'common' ? 0 : rarity === 'uncommon' ? 1 : 2;
        const rollTable = {
            2: ['standard_market', [5, 8, 15]],
            3: ['standard_market', [6, 9, 18]],
            4: ['guild_bulk_buyer', [7, 11, 20]],
            5: ['bidding_war', [9, 13, 25]],
            6: ['whale_collector_buyout', [12, 16, 35]]
        };

        const saleStatus = tradeRoll === 1 ? 'unsold' : 'sold';
        const marketResult = tradeRoll === 1 ? 'lowball_trolls' : rollTable[tradeRoll][0];
        const multiplier = tradeRoll === 1 ? 0 : rollTable[tradeRoll][1][tierIdx];
        const listingId = test.listingId || `listing-${Date.now()}-${state.inventory.activeTradeListings.length + 1}`;

        // Market outcome is locked at listing time; settlement reveals it later without rerolling.
        const lockedListing = {
            ...item,
            listingId,
            listedAt: test.listedAt || null,
            lockedSale: {
                status: saleStatus,
                result: marketResult,
                tradeRoll,
                tradeStat,
                multiplier,
                proceeds: saleStatus === 'sold' ? tradeStat * multiplier : 0,
                revealed: false
            }
        };

        state.inventory.bagReserves.splice(test.itemIndex, 1);
        state.inventory.activeTradeListings.push(lockedListing);
        result.item = { name: lockedListing.name, listingId, locked: true };
        result.status = 'listed';
        return result;
    }

    if (test.action === 'withdraw') {
        int(test.listingIndex, 'listingIndex', 0);
        assert(test.listingIndex < state.inventory.activeTradeListings.length, `No active listing at index ${test.listingIndex}`);

        const [listing] = state.inventory.activeTradeListings.splice(test.listingIndex, 1);
        delete listing.lockedSale;
        delete listing.listingId;
        delete listing.listedAt;
        state.inventory.bagReserves.push(listing);

        result.status = 'withdrawn';
        result.returnedToBag = true;
        result.item = listing;
        return result;
    }

    function settleListing(listing) {
        assert(listing && listing.bound !== true, 'Bound gear cannot be settled through Aether-Net');
        assert(
            listing.lockedSale && ['sold', 'unsold'].includes(listing.lockedSale.status),
            'Listing has no locked sale result'
        );

        const lockedSale = listing.lockedSale;
        assert(lockedSale.revealed !== true, 'Aether-Net listing has already been settled');
        lockedSale.revealed = true;

        if (lockedSale.status === 'unsold') {
            delete listing.lockedSale;
            delete listing.listingId;
            delete listing.listedAt;
            state.inventory.bagReserves.push(listing);
            return {
                status: 'unsold',
                marketResult: lockedSale.result,
                silverGained: 0,
                returnedToBag: true,
                item: clone(listing)
            };
        }

        const proceeds = Number(lockedSale.proceeds);
        assert(Number.isInteger(proceeds) && proceeds >= 0, 'Locked Aether-Net proceeds are invalid');

        state.crew.purse += proceeds;
        state.inventory.tradeHistory.push({
            name: listing.name || 'Unnamed item',
            rarity: listing.rarity || 'Common',
            rarityColor: listing.rarityColor || '#ffffff',
            rawStat: listing.rawStat ?? null,
            marketResult: lockedSale.result,
            proceeds,
            zone: state.zone
        });
        state.inventory.tradeHistory = state.inventory.tradeHistory.slice(-25);

        return {
            status: 'sold',
            marketResult: lockedSale.result,
            multiplier: lockedSale.multiplier,
            silverGained: proceeds,
            returnedToBag: false,
            item: clone(listing)
        };
    }

    if (test.action === 'settle_all') {
        assert(state.inventory.activeTradeListings.length > 0, 'No active Aether-Net listings to settle');
        const settlements = state.inventory.activeTradeListings.splice(0).map(settleListing);
        const soldCount = settlements.filter(entry => entry.status === 'sold').length;

        result.settlements = settlements;
        result.silverGained = settlements.reduce((sum, entry) => sum + entry.silverGained, 0);
        result.soldCount = soldCount;
        result.unsoldCount = settlements.length - soldCount;
        result.status = soldCount > 0 ? 'sold' : 'unsold';
        return result;
    }

    int(test.listingIndex, 'listingIndex', 0);
    assert(test.listingIndex < state.inventory.activeTradeListings.length, `No active listing at index ${test.listingIndex}`);

    const [listing] = state.inventory.activeTradeListings.splice(test.listingIndex, 1);
    const settled = settleListing(listing);

    return Object.assign(result, {
        item: settled.item,
        status: settled.status,
        silverGained: settled.silverGained,
        multiplier: settled.multiplier,
        marketResult: settled.marketResult,
        returnedToBag: settled.returnedToBag,
        settlements: [settled]
    });
}

/*
 * Validates and prices a vendor trade basket against current state.
 * Called internally by resolveVendorTradeCommit() before mutating gear or silver.
 */
function resolveVendorSelection(test) {
    assert(test.state && typeof test.state === 'object', 'Vendor selection requires saved state');
    const state = clone(test.state);
    const settlement = freeZoneSettlement(state);
    assert(settlement, 'Trade selection requires presence at the open shop');

    assert(
        settlement && !state.currentJourney && !['active', 'spotted'].includes(state.encounter?.status),
        'Trade selection requires presence at the open shop'
    );

    const basket = test.basket;
    assert(
        basket && Array.isArray(basket.buy) && Array.isArray(basket.sell) && basket.buy.length + basket.sell.length > 0,
        'Select at least one item to trade'
    );

    const stock = resolveVendorAction({ action: 'stock', zone: state.zone, state });
    const seenBuys = new Set();
    const seenSales = new Set();

    const buy = basket.buy.map(choice => {
        const entry = stock.catalog.find(item => item.number === choice.number);
        assert(entry, `Unknown shop row ${choice.number}`);
        assert(
            entry.variants.some(option => option.variant === choice.variant),
            `Invalid tuning for shop row ${choice.number}`
        );

        const key = `${entry.owner}:${entry.slot}`;
        assert(!seenBuys.has(key), `Select only one replacement for ${key}`);
        seenBuys.add(key);

        return {
            number: entry.number,
            owner: entry.owner,
            slot: entry.slot,
            variant: choice.variant,
            price: entry.price
        };
    });

    const sell = basket.sell.map(choice => {
        const key = choice.location === 'worn'
            ? `worn:${choice.owner}:${choice.slot}`
            : `bag:${choice.index}`;
        assert(!seenSales.has(key), `Duplicate sale: ${key}`);
        seenSales.add(key);

        const item = choice.location === 'worn'
            ? state.crew.gear?.[choice.owner]?.[choice.slot]
            : choice.location === 'bag'
                ? state.inventory?.bagReserves?.[choice.index]
                : null;
        const statVal = item?.rawStat ?? item?.stat;
        assert(item && Number.isInteger(statVal) && statVal > 0, `Selected item is unavailable: ${key}`);

        return {
            location: choice.location,
            ...(choice.location === 'worn' ? { owner: choice.owner, slot: choice.slot } : { index: choice.index }),
            item: clone(item),
            proceeds: 2 * statVal
        };
    });

    const cost = buy.reduce((total, item) => total + item.price, 0);
    const proceeds = sell.reduce((total, item) => total + item.proceeds, 0);
    const purseAfter = state.crew.purse + proceeds - cost;
    assert(purseAfter >= 0, `Trade would leave the crew ${-purseAfter}s short`);

    // Equal-or-worse purchases are forbidden unless the worn item in that slot is sold in the same exchange.
    for (const choice of buy) {
        const wornStat = Number(state.crew.gear?.[choice.owner]?.[choice.slot]?.stat || 0);
        const sellingWorn = sell.some(
            item => item.location === 'worn' && item.owner === choice.owner && item.slot === choice.slot
        );
        assert(sellingWorn || wornStat < stock.stat, `${choice.owner} ${choice.slot} already meets the vendor floor`);
    }

    return {
        ok: true,
        action: 'stage',
        basket: {
            settlementId: settlement.id,
            zone: state.zone,
            buy,
            sell,
            cost,
            proceeds,
            purseBefore: state.crew.purse,
            purseAfter
        },
        state
    };
}

/*
 * Direct-confirm vendor trade. Validates the submitted basket against
 * current state and applies all sales, purchases, and silver changes atomically.
 */
function resolveVendorTradeCommit(test) {
    assert(test.state && typeof test.state === 'object', 'Trade commit requires saved state');
    const state = clone(test.state);
    const settlement = freeZoneSettlement(state);
    assert(settlement, 'The crew must be free at a saved settlement to trade');

    const requested = test.basket;
    assert(
        requested && Array.isArray(requested.buy) && Array.isArray(requested.sell),
        'Select at least one item to trade'
    );

    const checked = resolveVendorSelection({
        state,
        action: 'stage',
        basket: {
            buy: requested.buy.map(({ number, variant }) => ({ number, variant })),
            sell: requested.sell.map(item =>
                item.location === 'worn'
                    ? { location: 'worn', owner: item.owner, slot: item.slot }
                    : { location: 'bag', index: item.index }
            )
        }
    });

    const pending = checked.basket;
    let working = checked.state;
    const beforeStats = derived(working.crew);
    const purseBefore = working.crew.purse;
    const sold = pending.sell.map(choice => ({
        name: choice.item.name || 'Unnamed gear',
        location: choice.location,
        owner: choice.owner || null,
        slot: choice.slot || null,
        proceeds: choice.proceeds
    }));

    for (const choice of pending.sell.filter(item => item.location === 'worn')) {
        delete working.crew.gear[choice.owner][choice.slot];
    }
    for (const choice of pending.sell.filter(item => item.location === 'bag').sort((a, b) => b.index - a.index)) {
        working.inventory.bagReserves.splice(choice.index, 1);
    }

    // Sale proceeds can fund purchases in the same exchange.
    working.crew.purse += pending.proceeds;
    const bought = [];

    for (const choice of pending.buy) {
        const purchase = resolveVendorAction({
            state: working,
            action: 'buy',
            zone: pending.zone,
            owner: choice.owner,
            slot: choice.slot,
            variant: choice.variant
        });
        working = purchase.state;
        bought.push(clone(purchase.item));
    }

    assert(working.crew.purse === pending.purseAfter, 'Trade purse does not match the validated quote');

    const afterStats = derived(working.crew);
    working.crew.qtik.hp = Math.max(
        0,
        Math.min(afterStats.qtikMaxHp, working.crew.qtik.hp + afterStats.qtikMaxHp - beforeStats.qtikMaxHp)
    );
    working.crew.tansy.hp = Math.max(
        0,
        Math.min(afterStats.tansyMaxHp, working.crew.tansy.hp + afterStats.tansyMaxHp - beforeStats.tansyMaxHp)
    );
    working.crew.qtik.maxHp = afterStats.qtikMaxHp;
    working.crew.qtik.def = afterStats.def;
    working.crew.qtik.regen = afterStats.regen;
    working.crew.tansy.maxHp = afterStats.tansyMaxHp;

    return {
        ok: true,
        created: true,
        action: 'commit',
        receipt: {
            settlementId: settlement.id,
            bought,
            sold,
            cost: pending.cost,
            proceeds: pending.proceeds,
            purseBefore,
            purseAfter: working.crew.purse,
            derivedBefore: beforeStats,
            derivedAfter: afterStats
        },
        state: working
    };
}

function resolveVendorAction(test) {
    assert(Number.isInteger(test.zone) && ZONES[test.zone], `Unknown zone: ${test.zone}`);

    const zone = test.zone;
    const zoneInfo = ZONES[zone];
    const stat = zoneInfo.base;
    const price = stat * 8;
    const pawnValue = stat * 2;

    const definitions = [
        { owner: 'tansy', slot: 'weapon', variants: [null] },
        { owner: 'tansy', slot: 'gloves', variants: [null] },
        { owner: 'tansy', slot: 'chest', variants: [null] },
        { owner: 'tansy', slot: 'trousers', variants: [null] },
        { owner: 'tansy', slot: 'headgear', variants: ['vitality', 'luck'] },
        { owner: 'tansy', slot: 'boots', variants: ['vitality', 'luck'] },
        { owner: 'tansy', slot: 'neck', variants: ['vitality', 'luck'] },
        { owner: 'tansy', slot: 'ring1', variants: ['vitality', 'luck'] },
        { owner: 'tansy', slot: 'ring2', variants: ['vitality', 'luck'] },
        { owner: 'qtik', slot: 'ring1', variants: ['bulwark', 'vitality'] },
        { owner: 'qtik', slot: 'ring2', variants: ['bulwark', 'vitality'] },
        { owner: 'qtik', slot: 'amulet', variants: ['bulwark', 'vitality'] },
        { owner: 'qtik', slot: 'wristCuffs', variants: ['bulwark', 'vitality'] }
    ];

    const slotNames = {
        weapon: 'Focus', gloves: 'Bracers', chest: 'Chest', trousers: 'Trousers',
        headgear: 'Headgear', boots: 'Boots', neck: 'Necklace',
        ring1: 'Ring 1', ring2: 'Ring 2', amulet: 'Amulet', wristCuffs: 'Wrist Cuffs'
    };
    const variantTitle = variant => (variant ? variant[0].toUpperCase() + variant.slice(1) : null);

    if (test.action === 'stock') {
        const state = test.state || {};
        const gear = state.crew?.gear || {};

        const catalog = definitions.map((definition, index) => {
            const equippedStat = Number(gear[definition.owner]?.[definition.slot]?.stat || 0);
            const upgradeable = equippedStat < stat;

            return {
                number: index + 1,
                owner: definition.owner,
                slot: definition.slot,
                slotName: slotNames[definition.slot],
                equippedStat,
                stat,
                price,
                pawnValue,
                upgradeable,
                skip: !upgradeable,
                variants: definition.variants.map(variant => {
                    const fallback = [
                        definition.owner === 'qtik' ? "Q'tik" : 'Tansy',
                        ZONE_LOOT_MATERIALS[zone],
                        variantTitle(variant),
                        slotNames[definition.slot]
                    ].filter(Boolean).join(' ');

                    return {
                        variant,
                        label: variantTitle(variant),
                        displayName: cosmeticStockName(
                            state,
                            gearCosmeticStockKey(definition.owner, definition.slot, variant),
                            fallback
                        ),
                        bonus: lootBonus(definition.owner, definition.slot, variant, stat)
                    };
                })
            };
        });

        return {
            ok: true,
            action: 'stock',
            zone,
            zoneName: zoneInfo.name,
            stat,
            price,
            pawnValue,
            upgradeableSlots: catalog.filter(entry => entry.upgradeable).map(entry => entry.number),
            skipSlots: catalog
                .filter(entry => entry.skip)
                .map(({ number, owner, slot, equippedStat }) => ({ number, owner, slot, equippedStat })),
            catalog
        };
    }

    assert(test.action === 'buy', `Unsupported vendor action: ${test.action}`);
    assert(test.state && typeof test.state === 'object', 'Vendor purchase requires state');

    const state = clone(test.state);
    assert(state.crew?.gear && state.inventory, 'Vendor purchase requires crew and inventory state');
    state.inventory.bagReserves ||= [];
    assert(Array.isArray(state.inventory.bagReserves), 'inventory.bagReserves must be an array');
    assert(Number.isInteger(state.crew.purse) && state.crew.purse >= price, `Insufficient silver: purchase costs ${price}s`);
    assert(['tansy', 'qtik'].includes(test.owner), 'Purchase owner must be tansy or qtik');

    const definition = definitions.find(entry => entry.owner === test.owner && entry.slot === test.slot);
    assert(definition, `Invalid ${test.owner} vendor slot: ${test.slot}`);

    const equippedStat = Number(state.crew.gear[test.owner]?.[test.slot]?.stat || 0);
    assert(
        equippedStat < stat,
        `${test.owner} ${test.slot} already meets the Zone ${zone} vendor floor of Stat ${stat}`
    );

    const variant = test.variant === undefined || test.variant === null || test.variant === '' ? null : test.variant;
    assert(
        definition.variants.includes(variant),
        `${test.owner} ${test.slot} requires one of: ${definition.variants.map(v => v || 'no variant').join(', ')}`
    );

    const fallbackName = [ZONE_LOOT_MATERIALS[zone], variantTitle(variant), slotNames[test.slot]]
        .filter(Boolean)
        .join(' ');

    const item = {
        name: cosmeticStockName(state, gearCosmeticStockKey(test.owner, test.slot, variant), fallbackName),
        owner: test.owner,
        slot: test.slot,
        variant,
        rarity: 'Common',
        rarityColor: LOOT_RARITY_INFO.common.color,
        rawStat: stat,
        cost: price,
        sellValue: pawnValue,
        bound: false,
        classRestricted: false,
        tradeStreamEligible: true,
        bonus: lootBonus(test.owner, test.slot, variant, stat),
        acquiredFrom: 'armory'
    };

    const purseBefore = state.crew.purse;
    state.crew.purse -= price;
    state.inventory.bagReserves.push(item);

    return { ok: true, action: 'buy', item, purseBefore, purseAfter: state.crew.purse, state };
}

function resolveCurrencyAction(test) {
    assert(test.state && typeof test.state === 'object', 'currency action requires state');
    const state = clone(test.state);
    state.crew ||= {};
    state.crew.purse = Number(state.crew.purse || 0);

    assert(Number.isInteger(state.crew.purse) && state.crew.purse >= 0, 'Crew purse must be a non-negative integer');
    assert(['spend', 'earn'].includes(test.action), `Unsupported currency action: ${test.action}`);
    assert(Number.isInteger(test.amount) && test.amount > 0, 'Currency amount must be a positive integer');

    const before = state.crew.purse;
    if (test.action === 'spend') {
        assert(before >= test.amount, `Insufficient silver: need ${test.amount}s, have ${before}s`);
        state.crew.purse -= test.amount;
    } else {
        state.crew.purse += test.amount;
    }

    return {
        ok: true,
        action: test.action,
        amount: test.amount,
        reason: test.reason || null,
        purseBefore: before,
        purseAfter: state.crew.purse,
        state
    };
}

/*
 * A healing bottle's ID includes its PURCHASE zone. Its healing and price
 * are fixed from that ID, never recalculated from the crew's current zone
 * or maximum HP. The GM may give it a local cosmetic name, but cannot
 * change its mechanical grade or effect.
 *
 * Ungraded IDs remain readable as Zone 1 bottles for the current chat.
 * Cleansing Tonic retains its existing fixed utility effect and price.
 */
const CONSUMABLE_CATALOG = {
    basic_health_potion: {
        name: 'Basic Health Potion',
        type: 'potion',
        heal: 50,
        buyPrice: 10,
        sellPrice: 2
    },
    mid_health_potion: {
        name: 'Mid-Tier Health Potion',
        type: 'potion',
        heal: 120,
        buyPrice: 20,
        sellPrice: 5
    },
    cleansing_tonic: {
        name: 'Cleansing Tonic',
        type: 'tonic',
        heal: 0,
        buyPrice: 14,
        sellPrice: 3
    }
};

function consumableDefinition(id) {
    if (CONSUMABLE_CATALOG[id]) {
        return CONSUMABLE_CATALOG[id];
    }

    const match = typeof id === 'string'
        ? /^(basic|mid)_health_potion_z([1-9]\d*)$/.exec(id)
        : null;

    if (!match) return null;

    const zone = Number(match[2]);

    if (!Number.isSafeInteger(zone) || !ZONES[zone]) {
        return null;
    }

    const basic = match[1] === 'basic';

    return {
        name:
            `${basic ? 'Basic' : 'Mid-Tier'} Health Potion ` +
            `(${basic ? 50 * zone : 120 * zone} HP)`,
        type: 'potion',
        heal: (basic ? 50 : 120) * zone,
        buyPrice: (basic ? 10 : 20) * zone,
        sellPrice: (basic ? 2 : 5) * zone,
        purchaseZone: zone
    };
}

function herbalistStock(zone) {
    int(zone, 'herbalist zone', 1);

    const ids = [
        `basic_health_potion_z${zone}`,
        `mid_health_potion_z${zone}`,
        'cleansing_tonic'
    ];

    return ids.map(id => ({
        id,
        ...consumableDefinition(id)
    }));
}

function consumableDisplayName(entry) {
    const definition = consumableDefinition(entry.id);
    const base = entry.name || definition?.name || entry.id;

    if (
        definition?.type === 'potion' &&
        definition.heal > 0 &&
        !/\(\d+\s*HP\)/i.test(base)
    ) {
        return `${base} (${definition.heal} HP)`;
    }

    return base;
}

function normalizeConsumableInventory(inventory) {
    inventory.consumables ||= [];

    assert(
        Array.isArray(inventory.consumables),
        'inventory.consumables must be an array'
    );

    for (const entry of inventory.consumables) {
        assert(
            entry &&
            typeof entry.id === 'string' &&
            consumableDefinition(entry.id),
            'Consumable inventory entry has an unknown item ID'
        );

        int(
            entry.quantity,
            `${entry.id}.quantity`,
            1
        );
    }
}

/*
 * Direct-confirm herbalist exchange. Validates quantities, ownership,
 * and funds on one clone, then commits sales, purchases, and silver
 * atomically. No potion is equipped or used here.
 */
function resolveHerbalistAction(test) {
    assert(test.state && typeof test.state === 'object', 'Herbalist interaction requires saved state');
    const state = clone(test.state);
    const settlement = freeZoneSettlement(state);
    assert(settlement, 'Herbalist trade requires presence at a free settlement');

    assert(
        test.action === 'commit',
        `Unsupported herbalist action: ${test.action}`
    );

    const selection = test.basket?.choices;

    assert(
        Array.isArray(selection) && selection.length > 0,
        'Select at least one potion'
    );

    normalizeConsumableInventory(state.inventory);

    const seen = new Set();
    const choices = selection.map(choice => {
        assert(
            choice && ['buy', 'sell'].includes(choice.side) &&
            typeof choice.id === 'string',
            'Invalid herbalist choice'
        );

        const quantity = int(
            choice.quantity,
            'Herbalist quantity',
            1
        );

        const key = `${choice.side}:${choice.id}`;
        assert(!seen.has(key), `Duplicate herbalist choice: ${key}`);
        seen.add(key);

        const definition = consumableDefinition(choice.id);
        assert(definition, `Unknown consumable: ${choice.id}`);

        let owned = null;

        if (choice.side === 'buy') {
            assert(
                herbalistStock(state.zone).some(item =>
                    item.id === choice.id
                ),
                `The herbalist does not sell ${choice.id} here`
            );
        } else {
            owned = state.inventory.consumables.find(item =>
                item.id === choice.id
            );

            assert(
                owned && owned.quantity >= quantity,
                `Not enough ${choice.id} to sell`
            );
        }

        const displayName =
            (choice.side === 'sell' && owned?.name) ||
            cosmeticStockName(
                state,
                potionCosmeticStockKey(choice.id),
                definition.name
            );

        return {
            side: choice.side,
            id: choice.id,
            quantity,
            name: displayName,
            unitPrice: choice.side === 'buy'
                ? definition.buyPrice
                : definition.sellPrice
        };
    });

    assert(choices.length > 0, 'Select at least one potion');

    const cost = choices
        .filter(choice => choice.side === 'buy')
        .reduce((total, choice) =>
            total + choice.unitPrice * choice.quantity, 0
        );

    const proceeds = choices
        .filter(choice => choice.side === 'sell')
        .reduce((total, choice) =>
            total + choice.unitPrice * choice.quantity, 0
        );

    const purseBefore = int(state.crew.purse, 'crew purse');
    const purseAfter = purseBefore + proceeds - cost;

    assert(
        purseAfter >= 0,
        `Herbalist trade would leave the crew ${-purseAfter}s short`
    );

    const quote = {
        settlementId: settlement.id,
        zone: state.zone,
        choices,
        cost,
        proceeds,
        purseBefore,
        purseAfter
    };

    /*
     * This is one cloned state. If any check fails, runStoredMechanic()
     * saves none of the sales, purchases, or silver changes.
     */

    for (const choice of choices.filter(item =>
        item.side === 'sell'
    )) {
        const entry = state.inventory.consumables.find(item =>
            item.id === choice.id
        );

        entry.quantity -= choice.quantity;

        if (entry.quantity === 0) {
            state.inventory.consumables =
                state.inventory.consumables.filter(item =>
                    item.id !== choice.id
                );
        }
    }

    for (const choice of choices.filter(item =>
        item.side === 'buy'
    )) {
        let entry = state.inventory.consumables.find(item =>
            item.id === choice.id
        );

        if (!entry) {
            const definition = consumableDefinition(choice.id);
            entry = {
                id: choice.id,
                name: choice.name,
                type: definition.type,
                quantity: 0,
                recipient: null
            };
            state.inventory.consumables.push(entry);
        }

        entry.quantity += choice.quantity;
    }

    state.crew.purse = purseAfter;

    return {
        ok: true,
        created: true,
        action: 'commit',
        receipt: quote,
        state
    };
}

/*
 * Ordinary inn prices establish the civilian economy and do not scale
 * with zone. Meals and hot water are expenses only (not food buffs or
 * elapsed-time mechanics). Renting a room restores both protagonists to
 * full HP (diegetically requiring at least a 2-hour nap or overnight rest).
 * The GM dresses the purchased service locally; its saved ID and price
 * remain engine-owned.
 */

const INN_SERVICES = [
    { id: 'standard_meal', label: 'Standard filling fare', price: 1 },
    { id: 'better_meal', label: 'Better meal', price: 3 },
    { id: 'special_meal', label: 'Special meal', price: 5 },
    { id: 'common_room', label: 'Common-room bed', price: 1 },
    { id: 'private_room', label: 'Private room', price: 2 },
    { id: 'luxurious_room', label: 'Luxurious room', price: 5 },
    { id: 'hot_water', label: 'Hot water', price: 2 }
];

function resolveInnAction(test) {
    assert(test.state && typeof test.state === 'object', 'Inn interaction requires saved state');
    const state = clone(test.state);
    const settlement = freeZoneSettlement(state);
    assert(settlement, 'Inn services require presence at a free settlement');

    assert(
        test.action === 'commit',
        `Unsupported inn action: ${test.action}`
    );

    const requested = test.basket?.choices;

    assert(
        Array.isArray(requested) && requested.length > 0,
        'Choose at least one inn service'
    );

    const seen = new Set();
    const choices = requested.map(choice => {
        assert(
            choice && typeof choice.id === 'string',
            'Invalid inn service selection'
        );

        const service = INN_SERVICES.find(
            entry => entry.id === choice.id
        );

        assert(service, `Unknown inn service: ${choice.id}`);
        assert(!seen.has(service.id),
            `Duplicate inn service: ${service.id}`);
        seen.add(service.id);

        const quantity = int(
            choice.quantity,
            `${service.id} quantity`,
            1
        );

        const isRoom = [
            'common_room',
            'private_room',
            'luxurious_room'
        ].includes(service.id);

        assert(
            quantity <= (isRoom || service.id === 'hot_water' ? 1 : 20),
            `${service.label} exceeds its allowed quantity`
        );

        return {
            id: service.id,
            label: cosmeticStockName(
                state,
                `inn:${service.id}`,
                service.label
            ),
            quantity,
            unitPrice: service.price
        };
    });

    assert(
        choices.filter(choice =>
            ['common_room', 'private_room', 'luxurious_room']
                .includes(choice.id)
        ).length <= 1,
        'Choose at most one room type per inn exchange'
    );

    const cost = choices.reduce(

        (sum, choice) =>
            sum + choice.unitPrice * choice.quantity,
        0
    );

    const purseBefore = int(state.crew.purse, 'crew purse');
    const purseAfter = purseBefore - cost;

    assert(
        purseAfter >= 0,
        `Inn services would leave the crew ${-purseAfter}s short`
    );

    const quote = {
        settlementId: settlement.id,
        choices,
        cost,
        purseBefore,
        purseAfter
    };

    state.crew.purse = purseAfter;

    const rentedRoom = choices.find(choice =>
        ['common_room', 'private_room', 'luxurious_room'].includes(choice.id)
    );

    let restRecovery = null;

    if (rentedRoom) {
        const stats = derived(state.crew);
        const qtikBefore = state.crew.qtik.hp;
        const tansyBefore = state.crew.tansy.hp;

        state.crew.qtik.hp = stats.qtikMaxHp;
        state.crew.tansy.hp = stats.tansyMaxHp;
        state.crew.qtik.maxHp = stats.qtikMaxHp;
        state.crew.tansy.maxHp = stats.tansyMaxHp;

        restRecovery = {
            roomId: rentedRoom.id,
            roomLabel: rentedRoom.label,
            qtikHealed: stats.qtikMaxHp - qtikBefore,
            tansyHealed: stats.tansyMaxHp - tansyBefore,
            qtikHp: stats.qtikMaxHp,
            qtikMaxHp: stats.qtikMaxHp,
            tansyHp: stats.tansyMaxHp,
            tansyMaxHp: stats.tansyMaxHp
        };
    }

    return {
        ok: true,
        created: true,
        action: 'commit',
        receipt: quote,
        restRecovery,
        state
    };
}

/*
 * One cosmetic naming batch per zone, shared by its settlements.
 * Keys come from engine stock, never from the narrator. Names cannot
 * change item identity, stats, healing, price, rarity, or ownership.
 * This is also offered to an existing chat at its current settlement.
 */
const ZONE_ARC_SHAPES = [
    {
        id: 'slow_burn',
        label: 'The Slow Burn',
        guidance:
            'Start with small, seemingly mundane local friction that gradually ' +
            'connects into a larger hidden conflict before the climax.'
    },
    {
        id: 'open_turf_war',
        label: 'Open Turf War',
        guidance:
            'Two local forces are already clashing openly; pragmatic jobs ' +
            'pull the crew into retaliation, leverage, and breaking the deadlock.'
    },
    {
        id: 'encroaching_pressure',
        label: 'Encroaching Pressure',
        guidance:
            'An external or environmental threat (failing Imperial hardware, ' +
            'rising menace, or resource squeeze) steadily escalates until containment breaks.'
    },
    {
        id: 'expedition_heist',
        label: 'The Expedition / Contest',
        guidance:
            'Locals and rivals are racing for access to a sealed or contested ' +
            'regional prize; early chapters gather leverage/access before the final breach.'
    },
    {
        id: 'rotten_core',
        label: 'The Rotten Core',
        guidance:
            'A respected local authority or syndicate is leaning on residents; ' +
            'ordinary work exposes cracks leading to open confrontation.'
    }
];

function prewarmTargetZone(state) {
    if (!state?.currentJourney) return null;

    const nextZone = state.world?.zones?.[state.zone + 1];
    if (!nextZone || nextZone.visited === true) return null;

    const nextSettlement =
        state.world?.settlements?.[nextZone.primarySettlementId];

    if (
        nextSettlement &&
        state.currentJourney.destinationId === nextSettlement.locationId
    ) {
        return nextZone.number;
    }

    return null;
}

function resolveZoneSpine(test) {
    assert(
        test.state && typeof test.state === 'object',
        'Zone spine requires saved state'
    );

    const state = clone(test.state);
    const targetZone = test.zone;

    assert(
        Number.isInteger(targetZone) && state.world?.zones?.[targetZone],
        `Unknown zone spine target: ${targetZone}`
    );

    const atCurrentSettlement =
        targetZone === state.zone &&
        !state.currentJourney &&
        Object.values(state.world?.settlements || {}).some(entry =>
            entry.locationId === state.currentLocationId &&
            entry.zone === state.zone
        );

    const prewarmingOnward = prewarmTargetZone(state) === targetZone;

    assert(
        atCurrentSettlement || prewarmingOnward,
        'Zone spine requires presence at its settlement or an active journey toward it'
    );

    const zoneRecord = state.world.zones[targetZone];

    if (zoneRecord.spine?.established === true) {
        return {
            ok: true,
            created: false,
            action: 'apply',
            zone: targetZone,
            spine: clone(zoneRecord.spine),
            state
        };
    }

    const input = test.spine;
    assert(
        input && typeof input === 'object' && !Array.isArray(input),
        'Zone spine requires a JSON object'
    );

    const textLimits = {
        publicTension: [10, 280],
        hiddenTruth: [10, 280],
        bossConcept: [5, 180]
    };

    for (const [key, [minLen, maxLen]] of Object.entries(textLimits)) {
        assert(
            typeof input[key] === 'string' &&
            input[key].trim().length >= minLen &&
            input[key].trim().length <= maxLen &&
            !/[<>\r\n]/.test(input[key]),
            `Invalid zone spine field: ${key}`
        );
    }

    const rawFactions = Array.isArray(input.keyFactions)
        ? input.keyFactions
        : typeof input.keyFactions === 'string'
            ? input.keyFactions.split(/[,;]+/)
            : [];

    const keyFactions = rawFactions
        .map(entry => (typeof entry === 'string' ? entry.trim() : ''))
        .filter(entry => entry.length >= 2 && entry.length <= 80 && !/[<>\r\n]/.test(entry))
        .slice(0, 4);

    assert(
        keyFactions.length >= 2,
        'Zone spine requires at least 2 clean keyFactions'
    );

    const arcShape = worldChoice(
        state.world,
        `arc-shape:${targetZone}`,
        ZONE_ARC_SHAPES
    );
    const chapterCount = 4 + (
        worldHash(`${state.world.seed}:arc-length:${targetZone}`) % 4
    );

    zoneRecord.spine = {
        established: true,
        publicTension: input.publicTension.trim(),
        hiddenTruth: input.hiddenTruth.trim(),
        keyFactions,
        bossConcept: input.bossConcept.trim(),
        arcShape: arcShape.id,
        chapterCount
    };

    return {
        ok: true,
        created: true,
        action: 'apply',
        zone: targetZone,
        spine: clone(zoneRecord.spine),
        state
    };
}

function ensureZoneMsqRecord(state, zone = state.zone) {
    const zoneRecord = state.world?.zones?.[zone];
    const spine = zoneRecord?.spine;

    if (!zoneRecord || spine?.established !== true) {
        return null;
    }

    if (!zoneRecord.msq) {
        zoneRecord.msq = {
            status: 'active',
            chapter: 0,
            completedChapters: 0,
            totalChapters: Number(spine.chapterCount) || 5,
            activeQuestId: null,
            lastArchetypeId: null,
            pendingBeatDelay: 0
        };
    }

    return zoneRecord.msq;
}

function buildMsqChapterQuest(state, zone) {
    const zoneRecord = savedZoneRecord(state, zone);
    const spine = zoneRecord.spine;
    const msq = ensureZoneMsqRecord(state, zone);

    assert(
        spine?.established === true && msq?.status === 'active',
        `Zone ${zone} has no active MSQ spine`
    );

    const issuerSettlement = savedPrimarySettlement(state, zone);
    const repRecord = state.reputation?.[issuerSettlement.reputationKey] || {
        tier: 'Unknown',
        steps: 0
    };

    const nextChapter = Number(msq.chapter || 0) + 1;
    const total = Number(msq.totalChapters || spine.chapterCount || 5);
    const isClimax = nextChapter >= total;
    const revealChapter = Math.ceil(total / 2) + 1;
    const phase = isClimax
        ? 'finale'
        : nextChapter >= revealChapter
            ? 'escalation'
            : 'opening';

    const rank = isClimax
        ? 'B'
        : nextChapter === 1
            ? (total >= 5 ? 'F' : 'E')
            : phase === 'opening'
                ? 'E'
                : nextChapter === total - 1
                    ? 'C'
                    : 'D';

    const row = QUEST_REWARD_TABLES[zone][rank];
    const progression = QUEST_PROGRESSION[rank];

    let archetype;
    let gates;
    let terminalThreat;

    if (isClimax) {
        archetype = QUEST_ARCHETYPES.find(entry => entry.id === 'local_bounty');
        gates = 2;
        terminalThreat = { kind: 'boss', zone, roll: null };
    } else {
        const poolIds = ['local_bounty', 'field_job', 'courier_recovery', 'missing_person'];
        const candidates = poolIds
            .map(id => QUEST_ARCHETYPES.find(entry => entry.id === id))
            .filter(Boolean);
        const nonRepeating = candidates.filter(
            entry => entry.id !== msq.lastArchetypeId
        );
        const pickPool = nonRepeating.length > 0 ? nonRepeating : candidates;
        archetype = pickPool[roll(state, pickPool.length) - 1];

        gates = rank === 'F'
            ? roll(state, 2)
            : rank === 'C'
                ? 3
                : 2;

        terminalThreat = rollQuestTerminalThreat(state, rank, zone);
    }

    const scenarios = eligibleQuestScenarios(
        state,
        archetype,
        zone,
        rank,
        'social'
    );
    const authored = buildQuestFacts(
        state,
        archetype,
        zone,
        scenarios,
        rank
    );
    if (archetype.id === 'local_bounty') {
        authored.facts.threat = isClimax
            ? spine.bossConcept
            : terminalThreat.kind === 'normal_pack'
                ? 'the hostile group'
                : 'the dangerous foe';
        if (isClimax) {
            authored.pitch =
                `The regional conflict reaches its breaking point against ${spine.bossConcept}.`;
        }
    }

    const structureV2 = buildQuestV2PlanForOffer(
        state,
        archetype,
        gates,
        authored.facts,
        authored.variantId
    );

    assert(
        structureV2?.version === 2 &&
        Array.isArray(structureV2.gates) &&
        structureV2.gates.length === gates,
        `MSQ chapter ${nextChapter} lacks a complete V2 plan`
    );

    const hasLinkedCombat = structureV2.gates.some(
        gate => gate.trigger === 'linked_combat'
    );
    const referencePackXp = canonicalMixedPackXp(zone, state.crew.level);
    const basePackMult =
        progression.packMultiplier +
        Math.max(0, gates - 1) * EXTRA_QUEST_GATE_PACK_MULTIPLIER;
    const finalPackMultiplier = basePackMult + (hasLinkedCombat ? 0 : 0.5);
    const finalQuestXp = Math.round(referencePackXp * finalPackMultiplier);

    const salvageSlotRoll = roll(state, QUEST_SALVAGE_SLOTS.length);
    const salvage = makeQuestSalvage(state, zone, salvageSlotRoll, row);

    const questGatesData = clone(structureV2.gates);
    const quest = {
        id: `msq-z${zone}-ch${nextChapter}-${archetype.id}`,
        title: isClimax
            ? 'Main Story Climax · Regional Showdown'
            : `Main Story Ch. ${nextChapter} · ${archetype.label}`,
        rank,
        isMsq: true,
        msq: {
            zone,
            chapter: nextChapter,
            isClimax,
            phase
        },
        archetype: {
            id: archetype.id,
            label: archetype.label
        },
        variant: authored.variantId ? { id: authored.variantId } : null,
        gates,
        gatesData: questGatesData,
        structureV2,
        status: 'offered',
        seed: {
            zone,
            repTier: repRecord.tier,
            source: 'msq',
            channel: 'msq',
            archetypeId: archetype.id,
            variantId: authored.variantId,
            terminalThreat: {
                kind: terminalThreat.kind,
                zone: terminalThreat.zone,
                roll: terminalThreat.roll
            }
        },
        pitch: authored.pitch,
        facts: authored.facts,
        coreTruth: authored.truth,
        currentGate: { ...questGatesData[0] },
        objectiveResolution: null,
        payout: {
            xp: finalQuestXp,
            silver: row.silver,
            repSteps: row.repSteps,
            xpBasis: referencePackXp,
            xpBasisType: 'canonical_mid_mixed_pack',
            packMultiplier: finalPackMultiplier
        },
        salvage,
        terminalThreat: {
            kind: terminalThreat.kind,
            zone: terminalThreat.zone,
            revealed: false,
            resolved: false
        },
        town: issuerSettlement.reputationKey,
        originSettlementId: issuerSettlement.id,
        originLocationId: issuerSettlement.locationId,
        repTierAtOffer: repRecord.tier,
        requiresDelivery: !['sealed_cache', 'field_job'].includes(archetype.id)
    };

    quest.targetId = `quest-target-${quest.id}`;

    for (const gate of quest.gatesData) {
        if (gate.trigger === 'linked_combat') {
            gate.linkedTargetId = quest.targetId;
        }
    }
    if (quest.currentGate?.trigger === 'linked_combat') {
        quest.currentGate.linkedTargetId = quest.targetId;
    }

    registerQuestDestination(state, quest);
    saveQuestToJournal(state, quest);

    prepareRetrievalQuestDiscovery(quest);
    prepareV2QuestDiscoveries(quest);
    validateRetrievalQuestDiscoveries(quest);

    msq.chapter = nextChapter;
    msq.activeQuestId = quest.id;
    msq.lastArchetypeId = archetype.id;
    msq.pendingBeatDelay = 0;

    return quest;
}

function resolveMsqAction(test) {
    assert(
        test.state && typeof test.state === 'object',
        'MSQ check requires saved state'
    );

    const state = clone(test.state);
    const zone = state.zone;
    const msq = ensureZoneMsqRecord(state, zone);

    if (
        !msq ||
        msq.status !== 'active' ||
        state.currentJourney ||
        state.activeInstanceId ||
        ['active', 'spotted'].includes(state.encounter?.status)
    ) {
        return {
            ok: true,
            created: false,
            action: 'check',
            quest: null,
            state
        };
    }

    const journal = ensureQuestJournal(state);
    const hasOpenMsq = [...journal.offered, ...journal.accepted].some(
        quest =>
            quest?.isMsq === true &&
            (quest.msq?.zone ?? quest.seed?.zone) === zone &&
            ['offered', 'in_progress'].includes(quest.status)
    );

    if (hasOpenMsq) {
        return {
            ok: true,
            created: false,
            action: 'check',
            quest: null,
            state
        };
    }

    // MSQ chapters surface in the settlement so NPCs and local factions
    // can deliver the hook naturally instead of firing on an empty site.
    const atSettlement = Object.values(state.world?.settlements || {}).some(
        entry =>
            entry.locationId === state.currentLocationId &&
            entry.zone === zone
    );

    if (!atSettlement) {
        return {
            ok: true,
            created: false,
            action: 'check',
            quest: null,
            state
        };
    }

    if (Number(msq.pendingBeatDelay || 0) > 0) {
        msq.pendingBeatDelay -= 1;
        return {
            ok: true,
            created: true,
            action: 'check',
            cooledDown: true,
            quest: null,
            state
        };
    }

    const quest = buildMsqChapterQuest(state, zone);

    return {
        ok: true,
        created: true,
        action: 'check',
        quest,
        state
    };
}

function stockNamingEntries(state, targetZone = state.zone) {
    const worldEntries = [];
    const zoneRecord = state.world?.zones?.[targetZone];
    const settlement = zoneRecord
        ? state.world?.settlements?.[zoneRecord.primarySettlementId]
        : null;

    if (zoneRecord && zoneRecord.nameSource !== 'established') {
        worldEntries.push({
            key: 'world:region_name',
            description:
                `evocative region name for this ${zoneRecord.geography?.description || 'region'} ` +
                `(${zoneRecord.flavor?.label || 'Post-Calamity Frontier'})`
        });
    }

    if (settlement && settlement.nameEstablished !== true) {
        worldEntries.push({
            key: 'world:settlement_name',
            description:
                `evocative main settlement name fitting this ${zoneRecord?.geography?.description || 'region'} ` +
                `(${zoneRecord?.flavor?.label || 'Post-Calamity Frontier'})`
        });
    }

    const knownInstance = state.instances?.[`instance-z${targetZone}-known`];
    if (knownInstance?.presentation?.established !== true) {
        worldEntries.push({
            key: 'world:known_instance_name',
            description:
                `evocative name for the region's main known dungeon or delve site fitting this ${zoneRecord?.geography?.description || 'region'} ` +
                `(${zoneRecord?.flavor?.label || 'Post-Calamity Frontier'})`
        });
    }

    const gear = resolveVendorAction({
        action: 'stock',
        zone: targetZone,
        state
    }).catalog.flatMap(entry =>
        entry.variants.map(option => ({
            key:
                `gear:${entry.owner}:${entry.slot}:` +
                `${option.variant || 'standard'}`,
            description:
                `${entry.owner === 'qtik' ? "Q'tik" : 'Tansy'} ` +
                `${entry.slotName}, ${option.label || 'standard'}`
        }))
    );

    const potions = herbalistStock(targetZone)
        .filter(item => item.type === 'potion')
        .map(item => ({
            key: `potion:${item.id}`,
            description:
                `${item.id.startsWith('basic_')
                    ? 'basic'
                    : 'mid-tier'} healing potion`
        }));

    const innServices = INN_SERVICES.map(service => ({
        key: `inn:${service.id}`,
        description: service.label
    }));

    const curios = [
        { key: 'curio:common:1', description: 'ordinary local curio or trinket' },
        { key: 'curio:common:2', description: 'ordinary local curio or craft oddity' },
        { key: 'curio:common:3', description: 'ordinary local curio or old keepsake' },
        { key: 'curio:common:4', description: 'ordinary local curio or minor relic' },
        { key: 'curio:rare:1', description: 'rare local curio or Pre-Calamity relic' },
        { key: 'curio:rare:2', description: 'rare local curio or collector piece' },
        { key: 'curio:rare:3', description: 'rare local curio or fine antique' }
    ];

    return [...worldEntries, ...gear, ...potions, ...innServices, ...curios];
}

function resolveStockNames(test) {
    assert(
        test.state && typeof test.state === 'object',
        'Stock naming requires saved state'
    );

    const state = clone(test.state);
    const targetZone = test.zone;

    assert(
        Number.isInteger(targetZone) && ZONES[targetZone],
        `Unknown stock naming zone: ${targetZone}`
    );

    const atCurrentSettlement =
        targetZone === state.zone &&
        !state.currentJourney &&
        Object.values(state.world?.settlements || {}).some(entry =>
            entry.locationId === state.currentLocationId &&
            entry.zone === state.zone
        );

    const prewarmingOnward = prewarmTargetZone(state) === targetZone;

    assert(
        atCurrentSettlement || prewarmingOnward,
        'Stock naming requires arrival at a settlement or an active journey toward it'
    );

    state.cosmeticStockNames ||= {};

    const entries = stockNamingEntries(state, targetZone);
    const saved =
        state.cosmeticStockNames[targetZone] || {};
    const missingEntries = entries.filter(
        entry => typeof saved[entry.key] !== 'string'
    );
    const expected = new Set(
        missingEntries.map(entry => entry.key)
    );
    const names = test.names;

    if (missingEntries.length === 0) {
        return {
            ok: true,
            created: false,
            action: 'apply',
            zone: targetZone,
            state
        };
    }

    assert(
        names && typeof names === 'object' &&
        !Array.isArray(names) &&
        Object.keys(names).length === expected.size &&
        Object.keys(names).every(key => expected.has(key)),
        'Naming reply must contain exactly the missing stock keys'
    );
    for (const [key, value] of Object.entries(names)) {
        assert(
            typeof value === 'string' &&
            value.trim().length >= 3 &&
            value.trim().length <= 60 &&
            !/[<>\r\n]/.test(value) &&
            !/\b(?:hp|stat|tier|price)\b/i.test(value) &&
            !/\d/.test(value),
            `Invalid cosmetic stock name for ${key}`
        );
    }

    state.cosmeticStockNames[targetZone] = {
        ...saved,
        ...Object.fromEntries(
            Object.entries(names).map(([key, value]) => [
                key,
                value.trim()
            ])
        )
    };

    const zoneRecord = state.world?.zones?.[targetZone];
    const settlement = zoneRecord
        ? state.world?.settlements?.[zoneRecord.primarySettlementId]
        : null;

    if (zoneRecord && typeof names['world:region_name'] === 'string') {
        zoneRecord.name = names['world:region_name'].trim();
        zoneRecord.nameSource = 'established';

        const flavorId = zoneRecord.flavor?.id;
        if (flavorId && state.world?.flavorHistory?.[flavorId]) {
            state.world.flavorHistory[flavorId].lastRegionName =
                zoneRecord.name;
        }
    }

    if (settlement && typeof names['world:settlement_name'] === 'string') {
        settlement.label = names['world:settlement_name'].trim();
        settlement.nameEstablished = true;

        if (state.places?.[settlement.locationId]) {
            state.places[settlement.locationId].label = settlement.label;
        }
        if (state.currentJourney?.destinationId === settlement.locationId) {
            state.currentJourney.destinationLabel = settlement.label;
        }
    }

    if (typeof names['world:known_instance_name'] === 'string') {
        const instanceName = names['world:known_instance_name'].trim();
        const knownInstance = state.instances?.[`instance-z${targetZone}-known`];

        if (knownInstance && knownInstance.presentation?.established !== true) {
            knownInstance.label = instanceName;
            if (state.places?.[knownInstance.entranceId]) {
                state.places[knownInstance.entranceId].label = instanceName;
            }
            if (state.currentJourney?.destinationId === knownInstance.entranceId) {
                state.currentJourney.destinationLabel = instanceName;
            }
        }
    }

    return {
        ok: true,
        created: true,
        action: 'apply',
        zone: targetZone,
        state
    };
}

function cosmeticStockName(state, key, fallback, zone = state?.zone) {
    const name =
        state?.cosmeticStockNames?.[zone]?.[key];

    return typeof name === 'string' && name.trim().length > 0
        ? name
        : fallback;
}

function gearCosmeticStockKey(owner, slot, variant) {
    return (
        `gear:${owner}:${slot}:` +
        `${variant || 'standard'}`
    );
}

function potionCosmeticStockKey(id) {
    return `potion:${id}`;
}

function resolveConsumableAction(test) {
    assert(test.action === 'use', `Unsupported consumable action: ${test.action}`);
    assert(test.state && typeof test.state === 'object', 'Consumable action requires state');

    const state = clone(test.state);
    state.crew ||= {};
    state.inventory ||= {};
    state.inventory.bagReserves ||= [];
    state.inventory.activeTradeListings ||= [];
    normalizeConsumableInventory(state.inventory);

    const definition = consumableDefinition(test.item);
    assert(definition, `Unknown consumable item: ${test.item}`);
    assert(
        state.encounter?.status !== 'active',
        'Outside-combat use is unavailable during an active fight; use a combat drink action'
    );

    const quantity = test.quantity === undefined ? 1 : int(test.quantity, 'quantity', 1);
    const entry = state.inventory.consumables.find(e => e.id === test.item);
    assert(entry && entry.quantity >= quantity, `Not enough ${test.item} in shared stock`);

    const itemName = entry.name || definition.name;
    const recipient = test.recipient || null;
    assert(
        recipient === null || recipient === 'qtik' || recipient === 'tansy',
        'Recipient must be qtik, tansy, or omitted for someone outside the crew'
    );

    let healing = 0;
    if (recipient) {
        assert(state.crew[recipient] && Number.isInteger(state.crew[recipient].hp), `Missing ${recipient} HP`);
        if (definition.heal) {
            const stats = derived(state.crew);
            const maxHp = recipient === 'qtik' ? stats.qtikMaxHp : stats.tansyMaxHp;
            const beforeHp = state.crew[recipient].hp;
            assert(beforeHp < maxHp, `${recipient === 'qtik' ? "Q'tik" : 'Tansy'} is already at full HP`);
            state.crew[recipient].hp = Math.min(maxHp, beforeHp + definition.heal * quantity);
            healing = state.crew[recipient].hp - beforeHp;
        }
    }

    entry.quantity -= quantity;
    if (entry.quantity === 0) {
        state.inventory.consumables = state.inventory.consumables.filter(other => other.id !== test.item);
    }

    return {
        ok: true,
        action: 'use',
        item: test.item,
        quantity,
        silverChanged: 0,
        itemName,
        recipient,
        healing,
        reason: test.reason || null,
        stockAfter: state.inventory.consumables.find(other => other.id === test.item)?.quantity || 0,
        state
    };
}

function resolveShadowDeckAction(test) {
    assert(
        test.state && typeof test.state === 'object',
        'Shadow deck action requires state'
    );

    const state = clone(test.state);

    state.crew ||= {};
    state.crew.weasels ||= {
        active: 0,
        max: 3 + Math.floor((state.crew.level || 1) / 2)
    };
    state.crew.shadows ||= {
        deck: [],
        active: []
    };

    state.crew.shadows.deck ||= [];
    state.crew.shadows.active ||= [];

    assert(
        Array.isArray(state.crew.shadows.deck),
        'Shadow deck must be an array'
    );

    assert(
        Array.isArray(state.crew.shadows.active),
        'Active shadows must be an array'
    );

    assert(
        [
            'record',
            'replace',
            'remove',
            'activate',
            'deactivate',
            'bind_imprints',
            'dismiss_imprints'
        ].includes(test.action),
        `Unsupported shadow deck action: ${test.action}`
    );

    const allowedTypes = [
        'archer',
        'mender',
        'hexer',
        'warder'
    ];

    const deck = state.crew.shadows.deck;
    const active = state.crew.shadows.active;
    const totalSlots = 3 + Math.floor((state.crew.level || 1) / 2);

    function validateShadow(shadow) {
        assert(
            shadow &&
            typeof shadow.id === 'string' &&
            shadow.id.length > 0,
            'Shadow requires a non-empty ID'
        );

        assert(
            allowedTypes.includes(shadow.type),
            `Unsupported shadow type: ${shadow.type}`
        );

        int(
            shadow.sourceMobLevel,
            'shadow.sourceMobLevel',
            1
        );

        return {
            ...shadow,
            shadowTier: shadowTierFromLevel(shadow.sourceMobLevel)
        };
    }

    function activeSlotCount() {
        return active.reduce(
            (total, shadow) => total + 3 * shadow.count,
            0
        );
    }

    if (test.action === 'dismiss_imprints') {
        state.pendingShadowImprints = null;
        return {
            ok: true,
            action: 'dismiss_imprints',
            state
        };
    }

    if (test.action === 'bind_imprints') {
        const pending = state.pendingShadowImprints;
        assert(
            pending && Array.isArray(pending.imprints) && pending.imprints.length > 0,
            'No pending shadow imprints available to bind'
        );
        assert(
            Array.isArray(test.shadowTypes) && test.shadowTypes.length > 0,
            'Select at least one shadow imprint to bind'
        );

        const bound = [];
        for (const type of [...new Set(test.shadowTypes)]) {
            const imprint = pending.imprints.find(entry => entry.type === type);
            assert(imprint, `Imprint ${type} is not available`);

            const existingIndex = deck.findIndex(entry => entry.type === type);
            const updated = validateShadow({
                id: existingIndex >= 0 ? deck[existingIndex].id : imprint.shadowId,
                type: imprint.type,
                sourceMobLevel: imprint.sourceMobLevel,
                capturedFrom: null
            });

            if (existingIndex >= 0) {
                deck[existingIndex] = updated;
                const activeEntry = active.find(entry => entry.id === updated.id);
                if (activeEntry) {
                    activeEntry.sourceMobLevel = updated.sourceMobLevel;
                    activeEntry.shadowTier = updated.shadowTier;
                    activeEntry.capturedFrom = updated.capturedFrom;
                }
            } else {
                deck.push(updated);
            }

            bound.push({
                ...imprint,
                shadowId: updated.id,
                shadowTier: updated.shadowTier
            });
        }

        state.pendingShadowImprints = null;

        return {
            ok: true,
            action: 'bind_imprints',
            zone: pending.zone,
            bound,
            state
        };
    }

    if (test.action === 'record') {
        assert(
            typeof test.shadowId === 'string' &&
            test.shadowId.length > 0,
            'Recording a shadow requires shadowId'
        );

        assert(
            allowedTypes.includes(test.shadowType),
            `Unsupported shadow type: ${test.shadowType}`
        );

        int(
            test.sourceMobLevel,
            'sourceMobLevel',
            1
        );

        assert(
            !deck.some(shadow => shadow.id === test.shadowId || shadow.type === test.shadowType),
            `Shadow ${test.shadowType} is already in the deck`
        );

        const shadow = validateShadow({
            id: test.shadowId,
            type: test.shadowType,
            sourceMobLevel: test.sourceMobLevel,
            capturedFrom: test.sourceMobName || null
        });

        deck.push(shadow);

        return {
            ok: true,
            action: 'record',
            shadow,
            state
        };
    }

    assert(
        typeof test.shadowId === 'string' &&
        test.shadowId.length > 0,
        `${test.action} requires shadowId`
    );

    const shadowIndex =
        deck.findIndex(shadow => shadow.id === test.shadowId);

    assert(
        shadowIndex >= 0,
        `Shadow ${test.shadowId} is not in the deck`
    );

    const shadow =
        validateShadow(deck[shadowIndex]);

    if (test.action === 'replace') {
        assert(
            allowedTypes.includes(test.shadowType),
            `Unsupported replacement type: ${test.shadowType}`
        );

        int(test.sourceMobLevel, 'sourceMobLevel', 1);

        const previous = deck[shadowIndex];

        const replacement = validateShadow({
            id: test.shadowId,
            type: test.shadowType,
            sourceMobLevel: test.sourceMobLevel,
            capturedFrom: test.sourceMobName || null
        });

        deck[shadowIndex] = replacement;

        const activeEntry = active.find(entry => entry.id === test.shadowId);
        if (activeEntry) {
            assert(
                activeEntry.type === replacement.type,
                'Cannot change an active shadow’s role in place; unfuse it first'
            );
            activeEntry.sourceMobLevel = replacement.sourceMobLevel;
            activeEntry.shadowTier = replacement.shadowTier;
            activeEntry.capturedFrom = replacement.capturedFrom;
        }

        return {
            ok: true,
            action: 'replace',
            previous,
            shadow: replacement,
            state
        };
    }

    if (test.action === 'remove') {
        assert(
            !active.some(entry => entry.id === test.shadowId),
            'Cannot remove an active shadow from the deck'
        );

        const [removed] = deck.splice(shadowIndex, 1);

        return {
            ok: true,
            action: 'remove',
            shadow: removed,
            state
        };
    }

    if (test.action === 'deactivate') {
        const activeIndex =
            active.findIndex(entry => entry.id === test.shadowId);

        assert(
            activeIndex >= 0,
            `Shadow ${test.shadowId} is not active`
        );

        const activeEntry = active[activeIndex];
        const removeCount = test.count === undefined
            ? (activeEntry.type === 'archer' ? 1 : activeEntry.count)
            : int(test.count, 'count', 1);

        assert(
            removeCount <= activeEntry.count,
            `Cannot unfuse ${removeCount} copies; only ${activeEntry.count} active`
        );

        const deactivated = clone(activeEntry);
        if (removeCount < activeEntry.count) {
            activeEntry.count -= removeCount;
        } else {
            active.splice(activeIndex, 1);
        }

        const slotsReleased = 3 * removeCount;
        const looseCapacity = Math.max(0, totalSlots - activeSlotCount());
        const beforeWeasels = Number(state.crew.weasels.active || 0);
        state.crew.weasels.active = Math.min(looseCapacity, beforeWeasels + slotsReleased);
        state.crew.weasels.max = totalSlots;

        return {
            ok: true,
            action: 'deactivate',
            shadow: deactivated,
            removedCount: removeCount,
            shadowSlotsReleased: slotsReleased,
            weaselsRefunded: state.crew.weasels.active - beforeWeasels,
            state
        };
    }

    const requestedCount =
        test.count === undefined
            ? 1
            : int(test.count, 'count', 1);

    if (shadow.type !== 'archer') {
        assert(
            requestedCount === 1,
            'Only Shadow-Ranged may have multiple active copies'
        );

        assert(
            !active.some(entry => entry.type === shadow.type),
            `Only one active ${SHADOW_TYPE_LABELS[shadow.type] || shadow.type} is allowed`
        );
    }

    const currentCount =
        active
            .filter(entry => entry.id === shadow.id)
            .reduce((total, entry) => total + entry.count, 0);

    const additionalCount =
        requestedCount - currentCount;

    assert(
        additionalCount > 0,
        `Shadow ${shadow.id} is already active at that count`
    );

    const occupiedBefore =
        Number(state.crew.weasels.active) +
        activeSlotCount();

    assert(
        occupiedBefore <= totalSlots,
        'Active summons exceed total summon slots'
    );

    const slotsNeeded = additionalCount * 3;
    const freeSlots = totalSlots - occupiedBefore;
    const weaselsToFuse = Math.max(0, slotsNeeded - freeSlots);

    assert(
        state.crew.weasels.active >= weaselsToFuse,
        `Not enough summon slots: need ${slotsNeeded}, ` +
        `have ${freeSlots} free and ` +
        `${state.crew.weasels.active} weasels available to fuse`
    );

    state.crew.weasels.active -= weaselsToFuse;
    state.crew.weasels.max = totalSlots;

    const activeEntry =
        active.find(entry => entry.id === shadow.id);

    if (activeEntry) {
        activeEntry.count += additionalCount;
    } else {
        active.push({
            ...shadow,
            count: requestedCount
        });
    }

    return {
        ok: true,
        action: 'activate',
        shadow,
        count: requestedCount,
        shadowSlotsUsed: slotsNeeded,
        weaselsFused: weaselsToFuse,
        activeShadowSlots: activeSlotCount(),
        looseWeaselCapacity: totalSlots - activeSlotCount(),
        state
    };
}

/*
 * The narrator reports disclosure only after describing the request to
 * the players. This publishes the already-locked quest; it does not roll
 * another opportunity or accept the offer.
 */
function resolveSocialWorkReveal(test) {
    assert(
        test.state && typeof test.state === 'object',
        'Social work reveal requires saved state'
    );

    const state = clone(test.state);
    const settlement = Object.values(
        state.world?.settlements || {}
    ).find(entry =>
        entry.locationId === state.currentLocationId &&
        entry.zone === state.zone
    );

    assert(
        settlement,
        'Work disclosure requires presence at a settlement'
    );

    const contact = state.socialOpportunities?.contacts?.[
        `${settlement.id}:${test.socialId}`
    ];

    assert(
        contact?.result === 'offer' && contact.questId,
        'This contact has no locked work offer to reveal here'
    );

    if (!contact.pendingQuest) {
        const existing = findQuestById(state, contact.questId);

        assert(
            existing,
            'Revealed social offer is missing from the journal'
        );

        return {
            ok: true,
            created: false,
            action: 'reveal_work',
            socialId: contact.id,
            questId: contact.questId,
            state
        };
    }

    const quest = contact.pendingQuest;

    assert(
        quest.id === contact.questId &&
        quest.status === 'offered' &&
        !findQuestById(state, quest.id),
        'Pending social offer does not match its contact'
    );

    saveQuestToJournal(state, quest);
    delete contact.pendingQuest;

    const counter =
        state.socialOpportunities.settlements?.[settlement.id];

    if (counter?.pendingSocialId === contact.id) {
        counter.pendingSocialId = null;
    }

    return {

        ok: true,
        created: true,
        action: 'reveal_work',
        socialId: contact.id,
        questId: quest.id,
        state
    };
}

/*
 * A contact is established by the conversation, not generated as an NPC
 * roster on settlement arrival. The assistant reports an inquiry after
 * narrating the first conversational beat. Its stable socialId must be
 * reused for that same contact; repeats never roll again.
 *
 * This operation only works at a saved settlement. The two-offer limit
 * applies to this social channel, not to rumors or combat breadcrumbs.
 */
function resolveSocialWorkOpportunity(test) {
    assert(
        test.state && typeof test.state === 'object',
        'Social opportunity requires saved state'
    );

    const state = clone(test.state);

    assert(
        typeof test.socialId === 'string' &&
        /^[A-Za-z0-9._:-]{1,80}$/.test(test.socialId),
        'Social opportunity needs a stable contact ID'
    );

    assert(
        !['active', 'spotted'].includes(state.encounter?.status) &&
        !state.currentJourney,
        'Finish travel or resolve the encounter before asking locally'
    );

    const settlement = Object.values(
        state.world?.settlements || {}
    ).find(entry => entry.locationId === state.currentLocationId);

    assert(
        settlement && settlement.zone === state.zone,
        'Social work inquiry requires presence at its settlement'
    );

    state.socialOpportunities ||= {
        contacts: {},
        settlements: {}
    };
    const contacts = state.socialOpportunities.contacts;
    const counters = state.socialOpportunities.settlements;

    // A name such as "innkeeper" may recur in another settlement.
    // Scope its saved identity without changing the GM's local ID.
    const contactKey = `${settlement.id}:${test.socialId}`;
    const existingContact = contacts[contactKey];

    if (existingContact) {
        return {
            ok: true,
            created: false,
            action: 'check_work',
            socialId: test.socialId,
            outcome: existingContact.result,
            questId: existingContact.questId || null,
            state
        };
    }

    const counter = counters[settlement.id] ||= {
        checks: 0,
        offers: 0
    };

    /*
     * A saved offer waits for disclosure. Do not roll another merely
     * because the conversation takes another reply.
     */
    assert(
        !counter.pendingSocialId ||
            !contacts[
                `${settlement.id}:${counter.pendingSocialId}`
            ]?.pendingQuest,
        'This settlement already has an unpublished opportunity'
    );

    /*
     * One settlement opportunity check per saved user reply. The
     * interceptor supplies that reply's stable ID; this is not a roll
     * for a particular NPC. An unpublished success remains pending,
     * so subsequent replies cannot pile up hidden offers.
     */
    // When a zone has an active Spine/MSQ, the MSQ handles the arrival hook
    // and town sidequests stay at a steady rare rate (1-in-12).
    const hasZoneSpine =
        state.world?.zones?.[state.zone]?.spine?.established === true;
    const chance = hasZoneSpine
        ? 12
        : counter.offers < 2 ? 2 : 20;
    const value = roll(state, chance);
    const hasWork = value === 1;
    const contact = {
        id: test.socialId,
        settlementId: settlement.id,
        locationId: settlement.locationId,
        zone: state.zone,
        roll: value,
        sides: chance,
        result: hasWork ? 'offer' : 'no_work',
        questSeed: hasWork
            ? {
                source: 'social',
                roll: value,
                result: 'genuine_unclaimed_quest_or_dungeon_hook'
            }
            : null,
        questSeedConsumed: false,
        questId: null
    };

    contacts[contactKey] = contact;
    counter.checks++;

    if (!hasWork) {
        return {
            ok: true,
            created: true,
            action: 'check_work',
            socialId: contact.id,
            outcome: contact.result,
            questId: null,
            state
        };
    }

    const offered = resolveQuestSeed({
        state,
        socialId: contact.id,
        zone: contact.zone,
        settlementId: settlement.id
    });

    assert(
        offered.created && offered.quest,
        'Social trigger did not produce its locked offer'
    );
    const savedContact =
        offered.state.socialOpportunities.contacts[contactKey];

    assert(
        savedContact,
        'Generated social offer lost its settlement-scoped contact'
    );

    /*
     * The quest is locked, but the contact has not disclosed it yet.
     * Do not expose it in the journal before the next conversational
     * beat. Preserve the previous selected quest, if any.
     */
    if (offered.state.activeQuest?.id === offered.quest.id) {
        offered.state.activeQuest = null;
    }

    removeQuestFromJournal(offered.state, offered.quest.id);
    savedContact.questId = offered.quest.id;
    savedContact.pendingQuest = offered.quest;

    const savedCounter =
        offered.state.socialOpportunities.settlements[settlement.id];

    savedCounter.offers++;
    savedCounter.pendingSocialId = contact.id;

    return {

        ok: true,
        created: true,
        action: 'check_work',
        socialId: contact.id,
        outcome: 'offer',
        questId: offered.quest.id,
        quest: offered.quest,
        state: offered.state
    };
}

/*
 * Surface manner and private inclination are independent. This seeds
 * characterization, not an NPC's actions, a quest, or a guaranteed
 * betrayal. Older traveler seeds retain their original locked results.
 */
function resolveSocialSeed(test) {
    assert(
        test.state && typeof test.state === 'object',
        'social seed requires state'
    );
    assert(
        typeof test.socialId === 'string' &&
        test.socialId.trim().length > 0,
        'social seed requires socialId'
    );

    const state = clone(test.state);
    state.socialSeeds ||= {};

    assert(
        state.socialSeeds &&
        typeof state.socialSeeds === 'object' &&
        !Array.isArray(state.socialSeeds),
        'state.socialSeeds must be an object'
    );

    const id = test.socialId.trim();
    const existing = state.socialSeeds[id];

    if (existing) {
        assert(
            Number.isInteger(existing.surfaceRoll) &&
            existing.surfaceRoll >= 1 && existing.surfaceRoll <= 10 &&
            Number.isInteger(existing.inclinationRoll) &&
            existing.inclinationRoll >= 1 && existing.inclinationRoll <= 100 &&
            typeof existing.demeanor === 'string' &&
            typeof existing.inclination === 'string',
            `Invalid locked social seed: ${id}`
        );

        return {
            ok: true,
            created: false,
            socialId: id,
            seed: clone(existing),
            state
        };
    }

    const surfaces = [
        'curt',
        'nosy',
        'distracted',
        'boastful',
        'nervous',
        'weary',
        'theatrical',
        'competitive',
        'dry-witted',
        'pompous'
    ];

    const surfaceRoll = roll(state, surfaces.length);
    const inclinationRoll = roll(state, 100);

    const inclination =
        inclinationRoll <= 55
            ? 'no_hidden_complication'
            : inclinationRoll <= 72
                ? 'self_interested'
                : inclinationRoll <= 84
                    ? 'mistaken_about_something_consequential'
                    : inclinationRoll <= 93
                        ? 'under_pressure_or_divided_loyalty'
                        : inclinationRoll <= 98
                            ? 'limited_deliberate_deception'
                            : 'concealing_serious_harmful_agenda';

    const seed = {
        socialId: id,
        surfaceRoll,
        demeanor: surfaces[surfaceRoll - 1],
        inclinationRoll,
        inclination
    };

    state.socialSeeds[id] = seed;

    return {
        ok: true,
        created: true,
        socialId: id,
        seed: clone(seed),
        state
    };
}

/*
 * Reserve personality seeds before narration. Reporting an introduction
 * consumes the first reserved seed; replaying the same assistant message
 * returns its original claim. Names and fictional continuity belong in
 * the GM's <template>, while these rolls remain saved mechanics state.
 */
function resolvePreparedNpcSeeds(test) {
    assert(
        test.state && typeof test.state === 'object',
        'NPC seed buffer requires saved state'
    );

    let state = clone(test.state);
    state.pendingNpcSeeds ||= [];
    state.npcSeedClaims ||= {};
    state.nextNpcSeedNumber ||= 1;

    assert(
        Array.isArray(state.pendingNpcSeeds),
        'NPC seed buffer must be an array'
    );

    if (test.action === 'prepare_npc_seeds') {
        let created = false;

        while (state.pendingNpcSeeds.length < 4) {
            const id = `prepared-npc-${state.nextNpcSeedNumber++}`;
            const rolled = resolveSocialSeed({
                state,
                socialId: id
            });

            state = rolled.state;
            state.pendingNpcSeeds.push({
                id,
                seed: rolled.seed
            });
            created = true;
        }

        return {
            ok: true,
            created,
            action: test.action,
            state
        };
    }

    assert(
        test.action === 'claim_npc_seed',
        `Unsupported NPC buffer action: ${test.action}`
    );
    assert(
        typeof test.socialId === 'string' &&
        test.socialId.length > 0,
        'NPC seed claim requires an assistant-message ID'
    );

    const previous = state.npcSeedClaims[test.socialId];

    if (previous) {
        return {
            ok: true,
            created: false,
            action: test.action,
            socialId: test.socialId,
            seed: clone(previous.seed),
            state
        };
    }

    const reserved = state.pendingNpcSeeds.shift();

    assert(reserved, 'No pre-rolled NPC seed remains');

    state.npcSeedClaims[test.socialId] = clone(reserved);

    return {
        ok: true,
        created: true,
        action: test.action,
        socialId: test.socialId,
        seed: clone(reserved.seed),
        state
    };
}

/*
 * The narrator may request a fight when a fictional complication needs
 * real opponents. This is deliberately narrower than unrestricted spawn:
 *
 * - The narrator chooses only normal_pack or elite.
 * - The engine chooses roster, level, passive, rewards, and RNG.
 * - The request is valid only in a free overland or settlement scene.
 * - Instances are excluded until their room-content contract supports
 *   narrator-created complications.
 * - One assistant message can create at most one saved encounter.
 *
 * The request itself does not create a quest, loot objective, reward, or
 * narrative premise. It only creates a spotted encounter for the player
 * to engage or avoid.
 */
function resolveNarrativeEncounterRequest(test) {
    assert(
        test.state && typeof test.state === 'object',
        'Narrative encounter request requires saved state'
    );

    assert(
        typeof test.socialId === 'string' &&
        /^work-[0-9]+-[a-z0-9]+$/.test(test.socialId),
        'Narrative encounter request requires an engine-issued message reference'
    );

    assert(
        ['normal_pack', 'elite'].includes(test.encounterType),
        'Narrative encounter request supports only normal_pack or elite'
    );

    const state = clone(test.state);

    state.narrativeEncounterRequests ||= {};

    const previous =
        state.narrativeEncounterRequests[test.socialId];

    if (previous) {
        assert(
            previous.encounterType === test.encounterType,
            'Narrative request ID was reused for another encounter type'
        );

        return {
            ok: true,
            created: false,
            action: 'request_encounter',
            request: clone(previous),
            state
        };
    }

    assert(
        !state.currentJourney,
        'Narrative encounter requests are unavailable during travel'
    );

    assert(
        !state.activeInstanceId,
        'Narrative encounter requests are unavailable inside instances'
    );

    assert(
        !['active', 'spotted'].includes(state.encounter?.status),
        'Resolve or avoid the current encounter first'
    );

    assert(
        state.currentLocationId &&
        state.currentPosition,
        'Narrative encounter request requires a saved current location'
    );

    const encounterId =
        `narrative-${test.socialId}`;

    const spawned = spawnEncounter({
        state,
        zone: state.zone,
        encounterType: test.encounterType,
        encounterId
    });

    const nextState = spawned.state;
    const encounter = nextState.encounter;

    assert(
        encounter.id === encounterId &&
        encounter.status === 'spotted',
        'Narrative encounter did not enter the spotted state'
    );

    encounter.narrativeRequestId = test.socialId;
    encounter.narrativeRequestType = test.encounterType;

    const request = {
        id: test.socialId,
        encounterId: encounter.id,
        encounterType: encounter.type,
        zone: state.zone,
        locationId: state.currentLocationId,
        position: clone(
            state.currentPosition ||
            { nodeId: state.currentLocationId }
        )
    };

    nextState.narrativeEncounterRequests[test.socialId] =
        clone(request);

    return {
        ok: true,
        created: true,
        action: 'request_encounter',
        request,
        encounter: clone(encounter),
        state: nextState
    };
}

function resolveBatch(args) {
    assert(
        Array.isArray(args.cases) &&
        args.cases.length > 0,
        'Batch mode requires a non-empty cases array'
    );

    const results = [];
    for (let index = 0; index < args.cases.length; index++) {
        const test = args.cases[index];
        const name = test.name || `case_${index + 1}`;

        try {
            assert(
                test && typeof test === 'object',
                `${name}: case must be an object`
            );

            let result;

            switch (test.kind) {
                case 'gear':
                    assert(
                        test.action === 'equip',
                        `${name}: unsupported gear action '${test.action}'`
                    );
                    result = equipBagItem(test.state, test.itemIndex);
                    break;
                case 'currency':
                    result = resolveCurrencyAction(test);
                    break;
                case 'consumable':
                    result = resolveConsumableAction(test);
                    break;
                case 'curio':
                    result = resolveCurioAction(test);
                    break;
                case 'herbalist':
                    result = resolveHerbalistAction(test);
                    break;
                case 'inn':
                    result = resolveInnAction(test);
                    break;
                case 'stock_names':
                    result = resolveStockNames(test);
                    break;
                case 'zone_spine':
                    result = resolveZoneSpine(test);
                    break;
                case 'msq':
                    result = resolveMsqAction(test);
                    break;
                case 'world':
                    result = resolveWorldAction(test);
                    break;
                case 'vendor':
                    result = test.action === 'commit'
                        ? resolveVendorTradeCommit(test)
                        : resolveVendorAction(test);
                    break;
                case 'shadows':
                    result = resolveShadowDeckAction(test);
                    break;
                case 'trade':
                    result = resolveTradeAction(test);
                    break;
                case 'spawn':
                    result = spawnEncounter(test);
                    break;
                case 'encounter_request':
                    result = resolveNarrativeEncounterRequest(test);
                    break;
                case 'travel':
                    result = resolveTravelStep(test);
                    break;
                case 'investigate_sign':
                    result = resolveTrailSignInvestigation(test);
                    break;
                case 'instance':
                    result = test.action === 'theme'
                        ? resolveInstanceTheme(test)
                        : test.action === 'open_chest'
                            ? resolveInstanceChestOpen(test)
                            : resolveInstanceAction(test);
                    break;
                case 'quest_event':
                    result = resolveQuestEvent(test);
                    break;
                case 'quest_reveal_terminal': {
                    const state = clone(test.state);
                    assert(
                        typeof test.questId === 'string' && test.questId.length > 0,
                        'Quest threat reveal requires a questId'
                    );
                    const quest = findQuestById(state, test.questId);
                    assert(quest?.status === 'in_progress', 'Quest threat requires an in-progress quest');
                    assert(
                        quest.currentGate?.mode === 'combat_twist_showdown',
                        'The current quest gate does not require a combat showdown'
                    );
                    assert(
                        quest.terminalThreat && quest.terminalThreat.resolved !== true,
                        'Quest terminal threat is already resolved'
                    );
                    assert(
                        state.currentLocationId === quest.destinationId,
                        'The crew must reach the quest destination first'
                    );
                    assert(
                        !state.encounter ||
                        ['cleared', 'fled', 'dead'].includes(state.encounter.status),
                        'Resolve the current encounter before revealing the quest threat'
                    );

                    result = spawnEncounter({
                        state,
                        questId: quest.id,
                        encounterType: 'quest_terminal',
                        encounterId: `quest-terminal-${quest.id}`
                    });
                    result.state.encounter.status = 'spotted';
                    result.state.encounter.questTerminal.targetId = quest.targetId;
                    result.action = 'quest_reveal_terminal';
                    result.questId = quest.id;
                    break;
                }
                case 'debug_create_rumor': {
                    const state = clone(test.state);
                    assert(state && typeof state === 'object', 'Debug rumor requires saved state');
                    assert(
                        !['active', 'spotted'].includes(state.encounter?.status),
                        'Resolve or avoid the current encounter before creating a test rumor'
                    );

                    const rumorId = test.inquiryId || `debug-rumor-${Date.now()}`;
                    const placeId = `debug-place-${rumorId}`;
                    const leadId = `debug-lead-${rumorId}`;

                    state.places ||= {};
                    state.leads ||= {};
                    state.routeEdges ||= [];

                    assert(!state.places[placeId] && !state.leads[leadId], `Debug rumor already exists: ${rumorId}`);

                    state.places[placeId] = {
                        id: placeId,
                        label: test.reason || 'Test Rumor Site',
                        zone: state.zone,
                        kind: 'test_rumor_site',
                        knownFrom: 'debug_test',
                        visited: false,
                        testOnly: true
                    };
                    state.leads[leadId] = {
                        id: leadId,
                        kind: 'rumor',
                        label: `Debug rumor: ${state.places[placeId].label}`,
                        claim: test.completionEvidence || 'A test rumor points to this destination.',
                        sourceId: 'debug_test',
                        targetType: 'place',
                        targetId: placeId,
                        status: 'known',
                        testOnly: true,
                        arrivalTest: true
                    };

                    recordCrewKnowledge(state, {
                        id: `knowledge-testimony-${leadId}`,
                        kind: 'testimony',
                        knowledgeType: 'testimony',
                        certainty: 'unverified_claim',
                        summary: state.leads[leadId].claim,
                        source: { id: leadId, type: 'debug_rumor_fixture' },
                        learnedAtLocationId: state.currentLocationId,
                        learnedAtZone: state.zone
                    });

                    const anchorId = savedPrimarySettlement(state, state.zone).locationId;
                    for (const testPlace of Object.values(state.places).filter(
                        place => place?.testOnly === true && Number(place.zone) === state.zone && place.id !== anchorId
                    )) {
                        if (!state.routeEdges.some(e =>
                            (e.fromId === anchorId && e.toId === testPlace.id) ||
                            (e.fromId === testPlace.id && e.toId === anchorId)
                        )) {
                            state.routeEdges.push({
                                fromId: anchorId,
                                toId: testPlace.id,
                                length: 1,
                                kind: 'debug_rumor_anchor_access',
                                testOnly: true
                            });
                        }
                    }

                    result = {
                        ok: true,
                        action: 'debug_create_rumor',
                        created: true,
                        leadId,
                        placeId,
                        label: state.places[placeId].label,
                        state
                    };
                    break;
                }
                case 'journey':
                    result = resolveJourneyAction(test);
                    break;
                case 'engage': {
                    const state = clone(test.state);
                    assert(state.encounter?.status === 'spotted', 'There is no spotted encounter to engage');
                    state.encounter.status = 'active';
                    result = { ok: true, action: 'engage', encounterId: state.encounter.id, state };
                    break;
                }
                case 'avoid': {
                    const state = clone(test.state);
                    assert(state.encounter?.status === 'spotted', 'There is no spotted encounter to avoid');
                    state.encounter.status = 'fled';
                    state.encounter.spottedDisposition = 'avoided';
                    result = { ok: true, action: 'avoid', created: true, encounterId: state.encounter.id, state };
                    break;
                }
                case 'turn':
                    result = resolveTurn({ state: test.state, actions: test.actions, rolls: test.rolls });
                    break;
                case 'social':
                    result = ['prepare_npc_seeds', 'claim_npc_seed'].includes(test.action)
                        ? resolvePreparedNpcSeeds(test)
                        : test.action === 'check_work'
                            ? resolveSocialWorkOpportunity(test)
                            : test.action === 'reveal_work'
                                ? resolveSocialWorkReveal(test)
                                : resolveSocialSeed(test);
                    break;
                case 'follow_breadcrumb': {
                    const state = test.state;
                    const breadcrumb = state?.breadcrumbs?.[test.breadcrumbId];
                    assert(
                        breadcrumb?.questSeed?.source === 'pack_drop' &&
                        breadcrumb.questSeed.result === 'diegetic_quest_breadcrumb',
                        'Unknown saved pack breadcrumb'
                    );
                    if (breadcrumb.questSeedConsumed) {
                        const existing = findQuestById(state, breadcrumb.questId);
                        assert(existing, 'Consumed breadcrumb lost its quest offer');
                        result = {
                            ok: true,
                            created: false,
                            action: 'follow_breadcrumb',
                            breadcrumbId: breadcrumb.id,
                            questId: existing.id,
                            state
                        };
                        break;
                    }
                    assert(
                        !['active', 'spotted'].includes(state.encounter?.status),
                        'Resolve or avoid the encounter before following the clue'
                    );
                    assert(
                        breadcrumb.locationId === state.currentLocationId &&
                        JSON.stringify(breadcrumb.position) ===
                            JSON.stringify(state.currentPosition || { nodeId: state.currentLocationId }),
                        'Return to where this breadcrumb was found'
                    );
                    const issuer = state.world?.settlements?.[breadcrumb.settlementId];
                    assert(issuer?.zone === breadcrumb.zone, 'Breadcrumb has no saved local issuer');
                    result = resolveQuestSeed({
                        state,
                        breadcrumbId: breadcrumb.id,
                        zone: breadcrumb.zone,
                        settlementId: issuer.id
                    });
                    result.action = 'follow_breadcrumb';
                    result.breadcrumbId = breadcrumb.id;
                    break;
                }
                case 'quest_delivery': {
                    const state = clone(test.state);
                    const questId = test.questId;
                    assert(typeof questId === 'string' && questId.length > 0, 'Quest delivery requires an explicit questId');
                    ensureQuestJournal(state);
                    const quest = findQuestById(state, questId);

                    if (quest?.status === 'complete' && quest.structureV2?.family === 'retrieve_item') {
                        result = { ok: true, created: false, action: 'quest_delivery', questId, state };
                        break;
                    }

                    assert(
                        quest?.status === 'in_progress' && quest.structureV2?.family === 'retrieve_item',
                        `No in-progress retrieval quest awaits ${questId}`
                    );
                    assert(
                        quest.deliveryReady === true && Boolean(quest.objectiveResolution),
                        'Quest cargo has not returned ready for delivery'
                    );
                    assert(
                        state.currentLocationId === quest.turnIn?.locationId && !state.currentJourney,
                        'The crew is not free at this quest turn-in location'
                    );
                    const cargo = quest.discoveries?.find(item => item.id === quest.turnIn?.discoveryId);
                    assert(
                        cargo?.kind === 'quest_item' && cargo.state === 'acquired',
                        'The locked quest cargo has not been recovered'
                    );

                    if (test.deferCompletion === true) {
                        state.pendingQuestCompletions ||= [];
                        const pendingId = `delivered:${quest.id}`;
                        if (state.pendingQuestCompletions.some(entry => entry.id === pendingId)) {
                            result = {
                                ok: true,
                                created: false,
                                deferred: true,
                                action: 'quest_delivery',
                                questId: quest.id,
                                state
                            };
                            break;
                        }
                        state.pendingQuestCompletions.push({
                            id: pendingId,
                            kind: 'quest_delivery',
                            questId: quest.id
                        });
                        result = {
                            ok: true,
                            created: true,
                            deferred: true,
                            action: 'quest_delivery',
                            questId: quest.id,
                            state
                        };
                        break;
                    }

                    result = resolveQuestAction({
                        state,
                        questId: quest.id,
                        action: 'complete',
                        objectiveCompleted: true,
                        completionEvidence:
                            `Delivered ${cargo.name || quest.facts?.cargo || 'the quest cargo'} to ${quest.turnIn.recipient}.`
                    });
                    result.action = 'quest_delivery';
                    break;

                }
                case 'quest':
                    result = test.action ? resolveQuestAction(test) : resolveQuestSeed(test);
                    break;
                default:
                    throw new Error(`Unknown mechanics kind: ${test.kind}`);
            }

            results.push({
                name,
                ok: result != null && result.ok !== false,
                result
            });
        } catch (error) {
            results.push({
                name,
                ok: false,
                error: error instanceof Error ? error.message : String(error)
            });
        }
    }

    const passed = results.filter(item => item.ok).length;
    return {
        ok: passed === results.length,
        total: results.length,
        passed,
        failed: results.length - passed,
        results
    };
}

/*
 * Between-fight recovery happens on the first overland travel step or
 * instance room move after combat, not immediately at victory. Leaving
 * Q'tik's post-fight HP visible lets the aftermath scene reflect the
 * damage she took while her regeneration tops her off on the move, and
 * any loose Shadow-Weasels lost in the fight reform to loose capacity.
 *
 * Tansy deliberately receives no out-of-combat HP healing; Shadow-Mender
 * only leeches in active combat so inns and potions keep their friction.
 */
function applyOutOfCombatRecovery(previousState, nextState, oneCase) {
    const isMoveOperation =
        oneCase?.kind === 'travel' ||
        (
            oneCase?.kind === 'instance' &&
            ['enter', 'move', 'exit'].includes(oneCase.action)
        );

    if (
        !isMoveOperation ||
        ['active', 'spotted'].includes(previousState?.encounter?.status) ||
        nextState.crew?.qtik?.hp <= 0 ||
        nextState.crew?.tansy?.hp <= 0
    ) {
        return null;
    }

    const maxHp = derived(nextState.crew).qtikMaxHp;
    const beforeHp = nextState.crew.qtik.hp;
    const hpRecovered = Math.max(0, maxHp - beforeHp);
    if (hpRecovered > 0) {
        nextState.crew.qtik.hp = maxHp;
    }

    const totalSlots = 3 + Math.floor((nextState.crew.level || 1) / 2);
    const looseCapacity = Math.max(
        0,
        totalSlots - shadowMechanics(nextState.crew).slots
    );
    const beforeWeasels = Number(nextState.crew.weasels?.active || 0);
    let weaselsRestored = 0;

    if (nextState.crew.weasels) {
        nextState.crew.weasels.max = totalSlots;
        if (beforeWeasels < looseCapacity) {
            weaselsRestored = looseCapacity - beforeWeasels;
            nextState.crew.weasels.active = looseCapacity;
        }
    }

    if (hpRecovered === 0 && weaselsRestored === 0) {
        return null;
    }

    return {
        character: 'qtik',
        beforeHp,
        afterHp: nextState.crew.qtik.hp,
        recovered: hpRecovered,
        weaselsBefore: beforeWeasels,
        weaselsAfter: nextState.crew.weasels?.active ?? beforeWeasels,
        weaselsRestored,
        reason: 'movement_out_of_combat'
    };
}

/*
 * Serialize state operations so two simultaneous tool calls cannot
 * both read the same revision and overwrite each other's changes.
 */
let aethermoorQueue = Promise.resolve();
function queueAethermoor(task) {
    const pending = aethermoorQueue.then(task);
    aethermoorQueue = pending.catch(() => {});
    return pending;
}

const AETHERMOOR_METADATA_KEY = 'aethermoorV2';

/*
 * Manual reset replaces this chat's mechanics state, not its transcript
 * or another chat's metadata. Serialize it with ordinary operations so
 * an in-flight save cannot restore the old campaign afterward.
 */
async function resetAethermoorCampaign() {
    return queueAethermoor(async () => {
        const context = getContext();
        const metadata = context.chatMetadata;
        const stored = metadata?.[AETHERMOOR_METADATA_KEY];

        assert(
            metadata && stored?.state &&
            typeof context.saveMetadata === 'function',
            'This chat has no saved campaign to reset'
        );

        assert(
            !aethermoorInjectedHandoff ||
            aethermoorInjectedHandoff.metadata !== metadata ||
            aethermoorInjectedHandoff.consumed,
            'Wait for the current GM reply and handoff to finish before resetting'
        );

        const freshState = createInitialCampaignState();
        const previous = stored;

        assert(
            getContext().chatMetadata === metadata,
            'Chat changed; campaign was not reset'
        );

        metadata[AETHERMOOR_METADATA_KEY] = {
            revision: stored.revision + 1,
            state: freshState,
            handoffQueue: []
        };

        try {
            await context.saveMetadata();
        } catch (error) {
            metadata[AETHERMOOR_METADATA_KEY] = previous;
            throw error;
        }

        return {
            ok: true,
            summary: stateSummary(
                freshState,
                metadata[AETHERMOOR_METADATA_KEY].revision
            )
        };
    });
}

/*
 * A fresh chat must be playable without a manually supplied state export.
 * Start with no encounter or opportunities: the crew discovers those
 * through play. Initialization consumes no campaign RNG rolls.
 */
function createInitialCampaignState() {
    const state = {
        zone: 1,
        rngState: createWorldSeed(),
        crew: {
            level: 1,
            xp: 0,
            purse: 0,
            qtik: {
                hp: 150,
                maxHp: 150,
                def: 1,
                regen: 2
            },
            tansy: {
                hp: 50,
                maxHp: 50
            },
            weasels: {
                active: 3,
                max: 3
            },
            shadows: {
                deck: [],
                active: []
            },
            gear: {
                tansy: {},
                qtik: {}
            }
        },
        inventory: {
            consumables: [],
            bagReserves: [],
            activeTradeListings: [],
            curios: []
        },
        encounter: null,
        activeQuest: null,
        quests: {
            offered: [],
            accepted: [],
            completed: [],
            failed: [],
            declined: [],
            abandoned: [],
            cancelled: []
        },
        inquiries: {},
        socialSeeds: {},
        reputation: {},
        gearGrantIds: {},
        discoveries: {},
        travelSteps: {},
        places: {},
        leads: {},
        routeEdges: [],
        currentLocationId: 'outpost-z1',
        currentPosition: { nodeId: 'outpost-z1' },
        currentJourney: null
    };

    ensureWorldRecords(state);
    ensureWorldLocation(state);

    const stats = derived(state.crew);

    state.crew.qtik.hp = stats.qtikMaxHp;
    state.crew.qtik.maxHp = stats.qtikMaxHp;
    state.crew.qtik.def = stats.def;
    state.crew.qtik.regen = stats.regen;
    state.crew.tansy.hp = stats.tansyMaxHp;
    state.crew.tansy.maxHp = stats.tansyMaxHp;

    checkImportedState(state);
    return state;
}

function checkImportedState(state) {

    assert(
        state && typeof state === 'object' && !Array.isArray(state),
        'Import requires a state object'
    );
    assert(ZONES[state.zone], 'Import requires a valid state.zone');
    assert(state.crew && state.crew.gear,
        'Import requires state.crew and its gear');
    assert(state.crew.gear.tansy && state.crew.gear.qtik,
        'Import requires both gear owner containers');
    assert(
        state.crew.shadows &&
        Array.isArray(state.crew.shadows.deck) &&
        Array.isArray(state.crew.shadows.active),
        'Import requires state.crew.shadows.deck and .active'
    );
    assert(
        state.inventory &&
        Array.isArray(state.inventory.bagReserves) &&
        Array.isArray(state.inventory.activeTradeListings) &&
        Array.isArray(state.inventory.consumables),
        'Import requires complete top-level state.inventory'
    );
    assert(
        state.gearGrantIds &&
        typeof state.gearGrantIds === 'object' &&
        !Array.isArray(state.gearGrantIds),
        'Import requires top-level state.gearGrantIds'
    );
    assert(
        Number.isInteger(state.rngState) && state.rngState > 0,
        'Import requires the saved positive rngState'
    );
    assert(
        state.inquiries && state.socialSeeds && state.reputation,
        'Import requires inquiries, socialSeeds, and reputation'
    );

    state.places ||= {};
    state.leads ||= {};
    state.currentLocationId ||= routeNodeId(state.zone, 'outpost');

    const currentSettlement = Object.values(
        state.world?.settlements || {}
    ).find(entry =>
        entry.locationId === state.currentLocationId
    );

    state.places[state.currentLocationId] ||= {
        id: state.currentLocationId,
        label: currentSettlement?.label || state.currentLocationId,
        zone: currentSettlement?.zone || state.zone,
        ...(currentSettlement
            ? { settlementId: currentSettlement.id }
            : {}),
        kind: currentSettlement ? 'settlement' : 'place'
    };

    const stats = derived(state.crew);
    int(state.crew.xp, 'crew.xp');
    int(state.crew.purse, 'crew.purse');
    int(state.crew.qtik.hp, 'qtik.hp');
    int(state.crew.tansy.hp, 'tansy.hp');

    assert(state.crew.qtik.hp <= stats.qtikMaxHp,
        "Q'tik HP exceeds derived maximum");
    assert(state.crew.tansy.hp <= stats.tansyMaxHp,
        'Tansy HP exceeds derived maximum');

    normalizeConsumableInventory(state.inventory);

    if (state.encounter !== null) {
        validate(state);
    }

    return stats;
}

function stateSummary(state, revision) {
    const stats = derived(state.crew);

    return {
        revision,
        zone: state.zone,
        level: state.crew.level,
        xp: state.crew.xp,
        nextXp: nextXp(state.crew.level),
        purse: state.crew.purse,
        qtikHp: state.crew.qtik.hp,
        qtikMaxHp: stats.qtikMaxHp,
        tansyHp: state.crew.tansy.hp,
        tansyMaxHp: stats.tansyMaxHp,
        atk: stats.atk,
        def: stats.def,
        weasels: state.crew.weasels.active,
        encounter: state.encounter && {
            id: state.encounter.id,
            status: state.encounter.status,
        foes: state.encounter.foes.map(foe => ({
            id: foe.id,
            role: foe.role,
            level: foe.level,
            hp: foe.hp,
            maxHp: foe.maxHp,
            nextTelegraph: foe.nextTelegraph || null
        }))

        },
        bagItems: state.inventory.bagReserves.length,
        activeTradeListings:
            state.inventory.activeTradeListings.length
    };
}

function chestLootNarrationLines(cache) {
    if (cache.kind === 'curio' || cache.kind === 'rare_curio') {
        const curio = cache.curio;
        const interestGuidance = {
            uninterested:
                'LOCAL BUYER INTEREST (PRIVATE): Uninterested. Ordinary ' +
                'shopkeepers treat it as common junk or clutter and will ' +
                'NOT fawn over it; it is only worth modest pawn value ' +
                'unless the crew specifically hunts down a niche buyer.',
            practical:
                'LOCAL BUYER INTEREST (PRIVATE): Practical. A relevant ' +
                'tradesman or pawnbroker recognizes modest workmanship ' +
                'and will buy it without making a fuss.',
            collector:
                'LOCAL BUYER INTEREST (PRIVATE): Collector interest. A ' +
                'local scholar, jeweler, or antiquarian will genuinely ' +
                'care about its origin and gladly buy it.'
        }[curio.buyerInterest];

        return [
            `Found (${curio.rarity} Curio): ${curio.name} — ` +
                `locked resale value ${curio.value} silver.`,
            interestGuidance,
            'Display this exact System HTML card verbatim (visible to Q’tik and Tansy):',
            acquiredItemsCardHtml([{ kind: 'curio', curio }]),
            'Write a concise <template> note recording this curio’s name, ' +
                'physical appearance, locked value, and private buyer-interest ' +
                'attitude so future NPCs react consistently.'
        ];
    }

    if (cache.kind === 'consumable') {
        return [
            `Found (Consumable): 1× ${cache.item.name}` +
                (cache.item.heal
                    ? ` (heals ${cache.item.heal} HP).`
                    : ' (cleansing tonic).'),
            'Display this exact System HTML card verbatim (visible to Q’tik and Tansy):',
            acquiredItemsCardHtml([{ kind: 'consumable', item: cache.item }])
        ];
    }

    if (cache.kind === 'silver') {
        return [
            `Found (Coin Stash): ${cache.silver} silver added to the crew’s purse.`
        ];
    }

    if (cache.kind === 'gear') {
        return [
            `Found (Gear): ${cache.item.name} (${cache.item.rarity}, ` +
                `Stat ${cache.item.rawStat}) — placed in Bag Reserves, NOT equipped.`,
            'Display this exact System HTML card verbatim (visible to Q’tik and Tansy):',
            acquiredItemsCardHtml([{ kind: 'gear', item: cache.item }])
        ];
    }

    return [];
}

function instanceChestNarrationPacket(result) {
    const trinketLines = result.loot?.trinket
        ? [
            `Found (Keystone Trinket): ${result.loot.trinket.name} (${result.loot.trinket.rarity}, ` +
                `Stat ${result.loot.trinket.rawStat} · ${result.loot.trinket.trinket?.summary || ''}) — placed in Bag Reserves, NOT equipped.`,
            'Display this exact System HTML card verbatim (visible to Q’tik and Tansy):',
            acquiredItemsCardHtml([{ kind: 'gear', item: result.loot.trinket }])
        ]
        : [];

    return [
        '* **INSTANCE CHEST OPENED!**',
        `Location: ${result.instanceLabel} — ${result.roomLabel}.`,
        'Portray the crew opening the chest and discovering the exact ' +
            'contents below. The contents are ALREADY added to saved state. ' +
            'Do not add extra coin, gear, traps, or combat.',
        ...chestLootNarrationLines(result.loot),
        ...trinketLines,
        ...(result.status === 'exhausted'
            ? ['All threats and chests in this instance are cleared. The instance is now exhausted.']
            : [])
    ].join('\n');
}

function instanceNarrationPacket(result) {
    if (result.action === 'exit') {
        const quickExit =
            Boolean(result.exitedFromRoomId) &&
            result.exitedFromRoomId !== 'entrance';

        return [
            quickExit
                ? 'The instance is cleared; the crew made their way back out ' +
                    'to the surface (retracing the cleared halls or taking a ' +
                    'side passage out).'
                : 'The crew left the instance through its entrance.',
            'They are at the saved overland entrance; no travel segment ' +
                'or random encounter was rolled.',
            'Previously visited rooms and room threats remain saved.'
        ].join('\n');
    }

    const lines = [
        `The crew ${result.action === 'enter'
            ? 'entered'
            : 'moved within'} the instance.`,
        `Current room: ${result.roomLabel}.`,
        ...(Array.isArray(result.passedThrough) && result.passedThrough.length > 0
            ? [
                `They retraced their steps through ${result.passedThrough.join(' → ')} ` +
                    'to reach this room (those rooms are already cleared; summarize the walk briefly in passing).'
            ]
            : []),
        result.firstVisit
            ? 'This is the first visit to this room.'
            : 'This room was already visited. Do not treat this revisit ' +
                'as a new discovery or reward roll.'
    ];

    if (result.encounter) {
        lines.push(
            `The room contains its saved ${result.encounter.type} threat.`,
            `Encounter ${result.encounter.id} is spotted, not engaged.`,
            'Describe signs of the threat and leave engagement, avoidance, ' +
                'or retreat to the protagonists.',
            'Do not create another encounter if the protagonists return ' +
                'to this room.'
        );
    } else if (result.roomThreatStatus === 'cleared') {
        lines.push(
            'This room’s saved threat has already been cleared.',
            'Do not create another encounter or reward here.'
        );
    } else if (result.roomFeature === 'lore' && result.firstVisit) {
        lines.push(
            'This dead-end side room has no combat threat. It holds a quiet ' +
                'narrative scrap of local or Pre-Calamity lore (e.g., an ' +
                'inscription, weathered mural, forgotten ledger, or architectural ' +
                'clue). Purely narrative world-building—no mechanical loot, XP, ' +
                'or quest.'
        );
    } else if (result.roomFeature === 'scenic' && result.firstVisit) {
        lines.push(
            'This dead-end side room has no combat threat. Portray it as a ' +
                'memorable scenic or liminal pocket (ecological reclamation, ' +
                'still water, striking ruins, or quiet atmosphere). No mechanical ' +
                'loot, XP, or quest.'
        );
    } else {
        lines.push(
            'This room has no combat threat in the current instance plan.'
        );
    }

    if (result.chest) {
        if (!result.chest.opened) {
            lines.push(
                '* **UNOPENED CHEST SPOTTED!** This chamber holds a sealed ' +
                    'or hidden chest/container.',
                ...(result.chest.obstacle
                    ? [
                        `Environmental obstacle around the chest: ${result.chest.obstacle}. ` +
                            'Stage this as a brief fictional complication for the crew to deal with.'
                    ]
                    : []),
                'Do NOT open the chest or invent its contents yet. Wait for ' +
                    'the player to open it in the fiction.'
            );
        } else {
            lines.push(
                'The chest in this chamber has already been opened and emptied.'
            );
        }
    }

    lines.push(
        `Visible exits: ${
            result.knownExits.map(exit =>
                exit.blocked
                    ? `${exit.label} (blocked until this room is cleared)`
                    : exit.label
            ).join(', ') || 'none'
        }.`,
        result.status === 'exhausted'
            ? 'All required instance content has been cleared. The ' +
                'instance is exhausted.'
            : 'Other instance content may remain unresolved.',
        'Describe only architecture, atmosphere, and the engine-established ' +
            'threat or chest. Do not add extra loot, quests, bosses, or rewards.'
    );

    return lines.join('\n');
}

function travelNarrationPacket(result) {
    const regionLabel = zoneDisplayName(result.state, result.zone);
    const lines = [
        `One travel step was resolved in ${regionLabel}.`
    ];

    if (result.event === 'quiet_travel') {
        lines.push(
            'Nothing notable was discovered on this stretch.'
        );
    } else if (result.event === 'passing_vignette') {
        lines.push(
            'PASSING VIGNETTE — weave one brief, zero-mechanics living-world ' +
                'moment into this stretch for the crew to notice or react to ' +
                '(fits the current scene, region, or companions — e.g. passing ' +
                'locals or Immortals, weather or terrain quirk, weasel antics, ' +
                'or a Pre-Calamity detail).',
            'Keep it purely diegetic: do NOT start combat, grant loot or silver, ' +
                'offer a quest, or invent a rumor destination.'
        );
    } else if (result.event === 'hidden_cache' && result.cache) {
        lines.push(
            '* **HIDDEN CACHE FOUND!** Tansy’s shadow-weasels sniffed out ' +
                'a hidden stash, buried box, or tucked-away cache along the route.',
            'Portray the weasels alerting Tansy and the crew recovering ' +
                'the cache. Dress the hiding spot to fit the saved geography.',
            'The contents below are ALREADY added to saved state. Do not ' +
                'add extra coin, gear, traps, or combat.',
            ...chestLootNarrationLines(result.cache)
        );
    } else if (result.event === 'hidden_instance' && result.hiddenInstance) {
        const site = result.hiddenInstance;
        lines.push(
            '* **RARE HIDDEN INSTANCE DISCOVERED!**',
            site.atEntrance
                ? 'Tansy’s shadow-weasels or the crew uncovered the concealed ' +
                    'entrance to a rare, one-time hidden site right here ' +
                    '(e.g., a collapsed smuggling tunnel, sealed Pre-Calamity ' +
                    'cellar, forgotten vault, or hidden shrine). They are ' +
                    'standing at its entrance and may enter or leave it for later.'
                : 'Along the route, the crew spotted the concealed entrance to ' +
                    'a rare, one-time hidden site tucked off the path. Its ' +
                    'location is now recorded for a future visit while their ' +
                    'current journey continues.',
            'Do NOT enter the site, start combat, or grant loot automatically.'
        );
    } else if (result.event === 'environmental_sign') {
        lines.push(
            `Environmental sign: ${result.environmentalSign}.`,
            'Portray this roadside sign naturally without resolving what lies behind it. Leave the choice to pause and investigate or keep moving to the protagonists.'
        );
    } else if (result.event === 'point_of_interest' && result.discovery) {

        const { xp, levelUps = [] } = result.discovery;

        lines.push(
            '* **LANDMARK DISCOVERED!** The crew came across a memorable ' +
                'landmark, vista, Pre-Calamity monument, natural wonder, or ' +
                'local curiosity fitting the saved geography and regional flavor ' +
                '(bigger and more lasting than a minor passing vignette).',
            'Give the landmark an evocative name and weave a short blurb of ' +
                'local or Pre-Calamity lore around it. Do NOT add hidden loot, ' +
                'encounters, or quests.',
            `Discovery XP (+${xp} XP) is ALREADY applied to saved state. ` +
                'Display this exact System HTML card verbatim (visible to Q’tik ' +
                'and Tansy, not ordinary NPCs), replacing ONLY [Landmark Name] ' +
                'and [Short 1–2 sentence lore blurb]:',
            landmarkDiscoveredCardHtml(xp, result.state?.crew),
            ...(levelUps.length > 0
                ? xpProgressNarrationLines(result.state?.crew, levelUps)
                : [])
        );

    } else if (result.event === 'wild_encounter') {
        lines.push(
            `The crew spotted encounter ${result.encounterId}.`,
            'The encounter remains spotted, not engaged. Narrate signs of the group and leave the response to the protagonists.'
        );
    } else if (result.event === 'social_opportunity') {
        lines.push(
            'The crew has encountered a traveler.',
            `First-meeting manner: ${result.social.demeanor}.`,
            `Private inclination: ${
                result.social.inclination ||
                result.social.sincerity ||
                'not recorded'
            }.`,
            'The manner is observable; the inclination is not. ' +
            'Give any consequential hidden truth a plausible, ' +
            'scene-specific one-line <template> precommit. ' +
            'If the inclination is no_hidden_complication, do not invent a secret ' +
            'or create a <template> merely to fill the profile.',
            'This traveler has already been seeded. Do not report them ' +
            'again with INTRODUCE_NPC if they acquire a name.'
        );

        if (result.rumor) {
            lines.push(
                `The traveler shares this claim: ${result.rumor.claim}`,
                `The claim points to ${result.rumor.targetLabel}.`,
                'Whether the claim is true has not been established. ' +
                'The crew has not visited that place or received a quest.'
            );
        } else {
            lines.push(
                'The traveler offers no rumor or quest lead.'
            );
        }

    }
    if (result.movement?.arrivalOnly) {
        lines.push(
            result.movement.journeySegmentConsumed
                ? `The crew completed the final route segment and ` +
                  `arrived at ${result.destinationLabel}.`
                : `Arrival at ${result.destinationLabel} was finalized ` +
                  'without consuming another route segment.',
            'No random travel event was rolled for this arrival.',
            'Any destination opportunity or threat must come from the ' +
                'established quest, rumor, or site mechanics.'
        );
       } else if (result.journey) {
        const journey = result.journey;

        if (journey.status === 'paused') {
            lines.push(
                `The journey toward ${journey.destinationLabel} is paused ` +
                'by a spotted encounter. The crew has not reached the destination.',
                'Do not narrate arrival. The crew must resolve or avoid the encounter before travel continues.'
            );
        } else {
            lines.push(
                `The crew is still traveling toward ${journey.destinationLabel}.`,
                'Describe the journey naturally. Do not mention numeric segment counters.'
            );
        }
    }

    for (const questGate of result.questGates || []) {
        const questLabel = questGate.questId
            ? ` for quest ${questGate.questId}`
            : '';

        lines.push(
            `Evidence found at the destination${questLabel}: ` +
                `${questGate.evidence || 'established arrival evidence'}.`,
            `Quest gate ${questGate.completed.step} completed: ` +
                `${questGate.completed.objective}`,
            questGate.next
                ? `Next gate ${questGate.next.step}: ` +
                    `${questGate.next.objective}`
                : 'This gate has no further field objective.',
            'This gate clearance alone granted no quest payout.'
        );
    }
    for (const ready of result.deliveryReadyList || []) {
        lines.push(
            `${ready.cargo} has returned to ${ready.recipient}'s settlement.`,
            `Cargo handover is ready for quest ${ready.questId}.`,
            'Arrival did not hand over the cargo or pay quest rewards. ' +
                'Leave the actual handover to the player.'
        );
    }

    for (const completion of result.questCompletions || []) {
        const completedQuest = result.state
            ? findQuestById(result.state, completion.questId)
            : null;
        lines.push(
            `The missing person reached safety; the System completed ${completion.title}.`,
            'Display this exact System completion HTML card verbatim (visible to Q’tik and Tansy):',
            contractCompleteCardHtml({
                title: completion.title,
                rank: completedQuest?.rank || null,
                rewards: completion.rewards,
                isMsq: completedQuest?.isMsq === true
            }),
            ...xpProgressNarrationLines(
                result.state?.crew,
                completion.levelUps || []
            )
        );
    }

    for (const secured of result.questObjectiveSecuredList || []) {
        if (!secured.questCompletion) continue;
        const rewards = secured.questCompletion.rewards;
        const completedQuest = result.state
            ? findQuestById(result.state, secured.questId)
            : null;

        lines.push(
            'The System completed the quest at its final objective.',
            'Display this exact System completion HTML card verbatim (visible to Q’tik and Tansy but not to ordinary NPCs):',
            contractCompleteCardHtml({
                title: completedQuest?.title || 'Contract',
                rank: completedQuest?.rank || null,
                rewards,
                isMsq: completedQuest?.isMsq === true
            }),
            ...xpProgressNarrationLines(
                result.state?.crew,
                secured.questCompletion.levelUps || []
            )
        );
    }

    if (result.zoneTransition) {
        const transition = result.zoneTransition;
        const flavor = transition.flavor;

        lines.push(
            `The crew crossed into ${transition.toRegion}.`,
            `Terrain transition: from ${transition.fromGeography || 'the previous region'} ` +
                `toward ${transition.toGeography || 'the next region'}.`,
            ...(flavor
                ? [
                    `Regional flavor: ${flavor.label} — ${flavor.hook}`,
                    ...(flavor.transitBridge
                        ? [`Diegetic route bridge: ${flavor.transitBridge}.`]
                        : []),
                    ...(flavor.splinterVariant
                        ? [
                            'SPLINTER VARIANT: This flavor appeared earlier' +
                                (flavor.previousRegionName
                                    ? ` in ${flavor.previousRegionName}`
                                    : '') +
                                '. Twist it into a distinct splinter tradition, ' +
                                'rival guild, or local mutation.'
                        ]
                        : [])
                ]
                : []),
            'Describe the geographic transition gradually. Do not treat the region change as a teleport.'
        );
    }

    return lines.join('\n');
}

function trailSignInvestigationNarrationPacket(result) {
    const lines = [
        `The crew paused to investigate the roadside sign: ${result.sign}.`,
        'No journey segment was consumed by this detour.'
    ];

    if (result.event === 'cold_trail') {
        lines.push(
            'INVESTIGATION RESULT: Cold trail / benign oddity.',
            'Following the sign leads to a grounded, mundane explanation or a trail that fades out cleanly. ' +
                'Make it clear there is nothing further to find here—do not add encounters, loot, or quests.'
        );
    } else if (result.event === 'wild_encounter') {
        lines.push(
            `INVESTIGATION RESULT: Following the sign led to spotted encounter ${result.encounterId}.`,
            'The encounter is spotted, not engaged. Leave the choice to engage, avoid, or retreat to the protagonists.'
        );
    } else if (result.event === 'hidden_cache' && result.cache) {
        lines.push(
            '* **INVESTIGATION RESULT: HIDDEN CACHE FOUND!**',
            'Following the sign led the crew to a tucked-away stash or salvageable cache. ' +
                'The contents below are ALREADY added to saved state. Do not add extra coin, gear, traps, or combat.',
            ...chestLootNarrationLines(result.cache)
        );
    } else if (result.event === 'social_opportunity' && result.social) {
        lines.push(
            'INVESTIGATION RESULT: Following the sign led to a traveler or local nearby.',
            `First-meeting manner: ${result.social.demeanor}.`,
            `Private inclination: ${result.social.inclination || 'not recorded'}.`,
            'The manner is observable; the inclination is not. Give any consequential hidden truth a plausible, ' +
                'scene-specific one-line <template> precommit. Do not report this traveler with INTRODUCE_NPC.',
            ...(result.rumor
                ? [
                    `The traveler shares this claim: ${result.rumor.claim}`,
                    `The claim points to ${result.rumor.targetLabel}.`,
                    'Whether the claim is true has not been established.'
                ]
                : ['The traveler offers no rumor or quest lead.'])
        );
    } else if (result.event === 'point_of_interest' && result.discovery) {
        const { xp, levelUps = [] } = result.discovery;
        lines.push(
            '* **INVESTIGATION RESULT: LANDMARK DISCOVERED!** Following the sign revealed a memorable local landmark or Pre-Calamity curiosity.',
            `Discovery XP (+${xp} XP) is ALREADY applied to saved state. Display this exact System HTML card verbatim (replacing ONLY [Landmark Name] and [Short 1–2 sentence lore blurb]):`,
            landmarkDiscoveredCardHtml(xp, result.state?.crew),
            ...(levelUps.length > 0
                ? xpProgressNarrationLines(result.state?.crew, levelUps)
                : [])
        );
    }

    return lines.join('\n');
}

const NARRATIVE_ROLE_CUES = {
    brute: 'frontline bruiser',
    archer: 'ranged attacker (weapons like bow, sling, or spell, or natural like spit or thrown hazard)',
    mender: 'healer / support',
    hexer: 'debuffer / hexer',
    buffer: 'pack protector / buffer',
    elite: 'elite threat',
    boss: 'regional boss threat'
};

function discoveryNarrationPacket(encounter, state = null) {
    const foes = encounter.foes.map((foe, index) => {
        const label = narrativeFoeLabel(foe, index);
        const cue = NARRATIVE_ROLE_CUES[foe.role];
        return cue ? `${label} (${cue})` : label;
    });
    const regionLabel = state
        ? zoneDisplayName(state, encounter.zone)
        : 'the current region';

    return [
        'A new encounter has been discovered.',
        `Region: ${regionLabel}.`,
        `${foes.length} distinct opponent(s): ${foes.join('; ')}.`,
        'These cues describe combat roles, not fixed species or gear. ' +
            'Dress each opponent to fit the saved quest and location so ' +
            'their role makes fictional sense (e.g., if a beast pack has a ' +
            'ranged attacker or healer, explain how—such as a rider, ' +
            'spitting variant, or shamanic leader). Keep the opponent count consistent.',
        ...(encounter.type === 'normal_pack' &&
            encounter.packTactic?.id !== 'none'
            ? [
                `Pack tactic: ${encounter.packTactic.label}.`,
                encounter.packTactic.description
            ]
            : []),
        'They are spotted, not engaged. Do not narrate an attack or ' +
            'assume a special ability was used before combat records it.',
        'Leave the choice to engage, avoid, investigate, negotiate, ' +
            'or retreat to the protagonists.'
    ].join('\n');
}

const PUBLIC_QUEST_FACT_KEYS = {
    sealed_cache: ['cache', 'place', 'stakes'],
    dormant_hazard: ['site', 'threat', 'stakes'],
    missing_person: ['sponsor', 'person', 'place', 'stakes'],
    local_bounty: ['sponsor', 'site', 'threat', 'stakes'],
    field_job: ['sponsor', 'task', 'place', 'stakes'],
    courier_recovery: ['sponsor', 'item', 'place', 'stakes']
};

function publicQuestFactLines(quest) {
    const keys = PUBLIC_QUEST_FACT_KEYS[quest.archetype?.id] || [];
    return keys
        .filter(key => typeof quest.facts?.[key] === 'string')
        .map(key =>
            `${key === 'sponsor' ? 'affected party' : key}: ` +
            quest.facts[key]
        );
}

function sidequestSpineGuidance(quest, state) {
    if (!quest || quest.isMsq === true) return [];

    const zone = quest.seed?.zone ?? state?.zone;
    const spine = state?.world?.zones?.[zone]?.spine;

    if (quest.seed?.channel === 'instance') {
        return [
            'INDEPENDENT RUIN LEAD: Keep this ancient site strictly ' +
                'independent of current town politics. At most allow ambient ' +
                'resonance (e.g. old salvage relevant to local needs), never ' +
                'a convenient main-plot MacGuffin.'
        ];
    }

    if (!spine?.established) return [];

    if (quest.spineTieIn === 'fallout') {
        return [
            `ZONE SPINE TIE-IN (FALLOUT): Tie this contract into the region’s ` +
                `open tension ("${spine.publicTension}") and active factions ` +
                `(${spine.keyFactions.join(', ')}) — e.g. collateral fallout, ` +
                'pressured workers, or local friction. Do NOT resolve the ' +
                'region’s main conflict or expose hidden conspiracies.'
        ];
    }

    if (quest.spineTieIn === 'ripple') {
        return [
            `ZONE SPINE TIE-IN (COLLATERAL RIPPLE): You may link this ` +
                `wilderness lead as a loose side-effect of "${spine.publicTension}", ` +
                'without turning it into a main-plot MacGuffin.'
        ];
    }

    return [
        'ORDINARY LIFE / WILDCARD: Keep this job grounded in everyday local ' +
            'or frontier life, separate from the region’s main faction tension.'
    ];
}

function msqOfferNarrationPacket(quest, state) {
    const zone = quest.msq?.zone ?? quest.seed?.zone ?? state?.zone;
    const spine = state?.world?.zones?.[zone]?.spine;
    const shape = ZONE_ARC_SHAPES.find(
        entry => entry.id === spine?.arcShape
    );
    const phase = quest.msq?.phase || 'opening';

    const secretLines = phase === 'finale'
        ? [
            `HIDDEN TRUTH (CLIMAX): ${spine?.hiddenTruth || ''}`,
            `ZONE BOSS CONCEPT: ${spine?.bossConcept || ''}`,
            'This is the regional Main Story Finale culminating in the Zone Boss showdown. ' +
                'Build directly on the NPCs, factions, and choices established in chat.'
        ]
        : phase === 'escalation'
            ? [
                `HIDDEN TRUTH (NOW SURFACING): ${spine?.hiddenTruth || ''}`,
                'The deeper conspiracy or root cause is now coming into focus. ' +
                    'Weave this chapter directly out of what the crew has already done in chat. ' +
                    'Do NOT spawn or reveal the Zone Boss yet.'
            ]
            : [
                'EARLY CHAPTER: Keep this grounded in the open local tension and ' +
                    'everyday fallout. Do NOT reveal the hidden truth or Zone Boss yet.'
            ];

    return [
        '* **MAIN STORY CHAPTER OFFERED!**',
        `Region: ${zoneDisplayName(state, zone)}.`,
        ...(shape ? [`Arc Shape: ${shape.label} — ${shape.guidance}`] : []),
        ...(spine
            ? [
                `Open Tension: ${spine.publicTension}`,
                `Active Factions: ${spine.keyFactions.join(', ')}.`
            ]
            : []),
        ...secretLines,
        `Mechanical Skeleton: ${quest.pitch}`,
        ...publicQuestFactLines(quest),
        `First objective: ${quest.currentGate.objective}`,
        'Portray the story hook naturally in-world first (NPCs cannot see System ' +
            'windows; do NOT mention total chapter count or meta story structure). ' +
            'Then display this exact System HTML card verbatim (visible only to Q’tik and Tansy):',
        contractOfferedCardHtml(quest)
    ].join('\n');
}

function questOfferNarrationPacket(quest, state = null) {
    const sourceText =
        quest.seed?.channel === 'instance'
            ? 'Examining the ruin clue revealed an old Pre-Calamity lead (no living town sponsor).'
            : {
                rumor: 'Following the rumor revealed a local concern.',
                pack_drop: 'Following the pack breadcrumb revealed a lead.',
                social: 'A local concern was discovered.',
                debug_test: 'A test trigger created this offer.'
            }[quest.seed?.source] ||
              'A local concern has been established.';

    return [
        '* **QUEST OFFERED!**',
        sourceText,
        `Concern: ${quest.pitch || quest.title}`,
        ...publicQuestFactLines(quest),
        ...sidequestSpineGuidance(quest, state),
        `First objective: ${quest.currentGate.objective}`,
        'First portray the concern in-world (NPCs do not know about System ' +
            'rewards). Then display this exact System offer HTML card verbatim ' +
            '(visible only to Q’tik and Tansy; do not accept it for them):',
        contractOfferedCardHtml(quest)
    ].join('\n');
}

function inventoryActionNarrationPacket(result, action) {
    if (action === 'equip') {
        return [
            'PRIVATE EQUIPMENT RESULT — do not recite this heading.',
            `${result.equipped.owner === 'qtik' ? "Q'tik" : 'Tansy'} ` +
                `equipped ${result.equipped.name}.`,
            ...(result.replaced?.name
                ? [`Replaced ${result.replaced.name}; it is now in Bag Reserves.`]
                : []),
            'The engine has already applied the equipment and stat changes. ' +
                'Describe the change naturally; do not apply it again.'
        ].join('\n');
    }

    return [
        'PRIVATE CONSUMABLE RESULT — do not recite this heading.',
        `${result.itemName} was used on ` +
            `${result.recipient === 'qtik' ? "Q'tik" : 'Tansy'}.`,
        `Actual HP restored: ${result.healing}.`,
        `Bottles remaining: ${result.stockAfter}.`,
        'The bottle and healing have already been applied. ' +
            'Describe the use naturally; do not consume or heal again.'
    ].join('\n');
}

function innRestNarrationPacket(result) {
    const recovery = result.restRecovery;
    if (!recovery) return null;

    const healedParts = [];
    if (recovery.qtikHealed > 0) {
        healedParts.push(
            `Q'tik (+${recovery.qtikHealed} HP, now ${recovery.qtikHp}/${recovery.qtikMaxHp})`
        );
    }
    if (recovery.tansyHealed > 0) {
        healedParts.push(
            `Tansy (+${recovery.tansyHealed} HP, now ${recovery.tansyHp}/${recovery.tansyMaxHp})`
        );
    }

    return [
        'PRIVATE INN REST RESULT — do not recite this heading.',
        `The crew rented ${recovery.roomLabel} (${result.receipt.cost}s total spent at the inn).`,
        healedParts.length
            ? `Resting for at least two in-world hours (a nap or overnight sleep) restored full HP: ${healedParts.join('; ')}.`
            : 'Both protagonists were already at full HP.',
        'The silver deduction and full-HP recovery are already applied to saved state; portray the rest naturally.'
    ].join('\n');
}

function questDiscoveryContextPacket(quest, state) {
    if (
        quest?.status !== 'in_progress' ||
        quest.objectiveResolution
    ) {
        return null;
    }

    const discovery = quest.discoveries?.find(
        item => item.id === quest.currentGate?.requiredDiscoveryId
    );

    if (!discovery || discovery.state === 'acquired') return null;

    const similarQuestsElsewhere = (state.quests?.accepted || [])
        .filter(other =>
            other.id !== quest.id &&
            other.status === 'in_progress' &&
            other.archetype?.id === quest.archetype?.id &&
            other.destinationId !== quest.destinationId
        );

    const stageHasObstacleLock =
        quest.currentGate?.decisive === true ||
        quest.currentGate?.stage === 'find_access';

    const lines = [
        '* **QUEST OBJECTIVE HERE — portray this in the current scene.**',
        `* **This site belongs to quest:** ${quest.id}.`,
        `* **Objective:** ${quest.currentGate.objective}`,
        `* **Established subject:** ${discovery.name}.`,
        `* **Where:** ${discovery.hidingPlace}.`,
        `* **Saved state:** ${discovery.state}.`,
        ...(similarQuestsElsewhere.length
            ? [
                '* **Separate accepted work:** Other quests of this type ' +
                    'have their own saved destination and discovery. Even if ' +
                    'its objectives sound identical only one quest is completed. ' +
                    'Do not narrate both as finished or report the other ' +
                    'quest’s discovery ID here.'
            ]
            : []),
        '* **Do now:** Describe the current site and give the crew ' +
            'a clear, in-world opportunity to interact with the ' +
            'established subject at its authored location.',
        '* **Stop before success:** Arrival alone does not perform the ' +
          'required action, acquire the object, complete the gate, or ' +
          'award rewards. Leave the next action to the player.',
        `* **Required action:** ${
            discovery.requiredAction || 'expose the object'
        }.`,
        `* **Significance once found:** ${discovery.significance}`,
        ...(stageHasObstacleLock
            ? [
                '* **Lock the obstacle in <template> (once per gate):** ' +
                    'If no <template> exists yet in chat locking this gate’s ' +
                    'obstacle, write one now recording: (1) the concrete ' +
                    'physical, mechanical, or social snag standing in the way, ' +
                    '(2) the clear warning sign (telegraph) and what goes wrong ' +
                    'if the crew rushes or uses an ill-suited method, and ' +
                    '(3) what condition solves it (keep solutions open to any ' +
                    'clever use of powers, gear, or mundane work—never require ' +
                    'one secret password). If a <template> for this gate ' +
                    'already exists, enforce it strictly; do not soften or rewrite it.',
                '* **Goal vs. method:** If the player states a desired outcome ' +
                    'without a workable method (e.g. "we clear it out of the way"), ' +
                    'narrate them starting the attempt, hitting the locked snag, ' +
                    'and stopping on that concrete resistance so they must decide how to tackle it.',
                '* **Telegraph before break:** If the crew tries a risky or ' +
                    'mismatched approach, show the clear warning sign once ' +
                    '(e.g. metal groaning before shearing, footing slipping) and ' +
                    'pause so they can back off or pivot. Only if they push past ' +
                    'the warning, enforce the failure mode. If they then invent ' +
                    'a genuinely clever way to improvise past the setback, let ' +
                    'them try it; if the objective is ruined or abandoned, ' +
                    'withhold <AETHERMOOR:FOUND>.'
            ]
            : []),
         '* **Report only what happens in the scene:** Do not emit a ' +
          'discovery tag merely because this context appeared or the ' +
          'player stated a desired outcome. Judge what their actions ' +
          'actually accomplish.',
        ...(quest.structureV2?.family === 'rescue_person' &&
            quest.currentGate?.decisive === true
            ? [
                '* **FINDING IS NOT COMPLETION:** Once the missing person ' +
                    'is found, do NOT show a completion window or award ' +
                    'rewards yet.',
                '* **Return:** Escort the person safely back to the origin ' +
                    'settlement. The System completes and pays this quest ' +
                    'automatically upon confirmed arrival there.'
            ]
            : []),
        ...(quest.structureV2?.family === 'retrieve_item' &&
            quest.currentGate?.decisive === true
            ? quest.requiresDelivery === false
                ? [
                    quest.archetype?.id === 'field_job'
                        ? '* **ON-SITE FIELD JOB:** Completing this task finishes ' +
                            'the contract immediately once reported—no town ' +
                            'delivery is required. Do NOT show a completion ' +
                            'window yet; emit <AETHERMOOR:FOUND> and the System ' +
                            'completion card will arrive on the next reply.'
                        : '* **SPONSOR-FREE CACHE:** Opening or claiming this cache ' +
                            'completes the contract immediately once reported—no ' +
                            'town delivery is required. Do NOT show a completion ' +
                            'window yet; emit <AETHERMOOR:FOUND> and the System ' +
                            'completion card will arrive on the next reply.'
                ]

                : [
                    '* **RECOVERY IS NOT DELIVERY:** Once the required object ' +
                        'is recovered, portray it as secured quest cargo. ' +
                        'Do NOT show a completion window, award rewards, ' +
                        'or claim the recipient has received it.',
                    `* **Return:** Bring this quest’s locked cargo to ${
                        quest.turnIn.recipient
                    } at the issuing settlement. The System pays only ` +
                        'after the actual handover is reported. Other ' +
                        'accepted retrieval quests remain separate.'
                ]
            : [])

    ];

    if (discovery.contents) {
        lines.push(
            '* **Contents:** Reveal these only if the object is opened ' +
              'or inspected:',
            ...discovery.contents.map(item => `  - ${item}`),
            '  These are quest cargo, not personal loot.'
        );
    }
    lines.push(
        '* **If the object is actually recovered or exposed, report:**',
        `<plan><AETHERMOOR:FOUND quest_item=${discovery.id}></plan>`,
        '* Keep the story in-world. Do not recite these instructions, ' +
          'tags, or extension mechanics to the players.'
    );

    return lines.join('\n');
}

function questTerminalNarrationPacket(encounter, quest) {
    return [
        `The linked threat for ${quest.title} has been spotted.`,
        `It has ${encounter.foes.length} distinct opponent(s).`,
        `Quest target: ${
            quest.structureV2?.facts?.target ||
            quest.facts?.beast ||
            quest.facts?.threat ||
            'the established threat'
        }.`,
        'Use the encounter’s opponent references consistently. ' +
            'The linked fight is spotted, not engaged. Do not add ' +
            'opponents or preemptively narrate abilities. Leave the ' +
            'decision to engage or avoid to the protagonists.'
    ].join('\n');
}

function questDiscoveryNarrationPacket(result, quest) {
    const discovery = result.discovery;
    const lines = [
        `Discovery validated: ${discovery.name}.`,
        `State: ${discovery.state}.`
    ];

    if (discovery.questCargo) {
        lines.push(
            'The recovered object and its contents remain quest cargo, not personal wealth.'
        );
    }

    if (result.questGate?.objectiveSecured) {
        const completion = result.questGate.questCompletion;

        if (completion) {
            const isSealedCache = quest?.archetype?.id === 'sealed_cache';
            const isFieldJob = quest?.archetype?.id === 'field_job';
            lines.push(
                isSealedCache
                    ? 'SEALED CACHE CLAIMED — The System completed the contract ' +
                      'immediately. Portray the locked salvage item and silver below ' +
                      'as physically resting inside the opened cache (while the System ' +
                      'chimes XP and Rep). Display this exact System completion HTML ' +
                      'card verbatim (visible to Q’tik and Tansy):'
                    : isFieldJob
                        ? 'FIELD JOB COMPLETED — The System validated the on-site task ' +
                          'and completed the contract immediately. Display this exact ' +
                          'System completion HTML card verbatim (visible to Q’tik and Tansy):'
                        : 'The System validated this quest’s final objective and completed ' +
                          'the contract. Display this exact System completion HTML card ' +
                          'verbatim (visible to Q’tik and Tansy):',
                contractCompleteCardHtml({
                    title: completion.title || quest?.title || 'Contract',
                    rank: completion.rank || quest?.rank || null,
                    rewards: completion.rewards,
                    isMsq: quest?.isMsq === true
                }),
                ...xpProgressNarrationLines(
                    result.state?.crew,
                    completion.levelUps || []
                ),
                'Rewards are already applied to saved state; do not add extra loot or coin.'
            );
        } else {
            lines.push(
                quest?.structureV2?.family === 'retrieve_item'
                    ? 'The required item is secured as quest cargo. Return ' +
                      'to the locked recipient; no quest rewards have ' +
                      'been paid and no completion window appeared.'
                    : 'The missing person has been found or freed; bring them ' +
                      'safely to the origin settlement before the System ' +
                      'completes the quest.'
            );
        }

    } else if (result.questGate?.next) {
        lines.push(
            `Gate ${result.questGate.completed.step} completed.`,
            `Next objective: ${result.questGate.next.objective}`
        );

        if (result.questGate.linkedEncounter) {
            lines.push(
                'That next objective has revealed its linked threat. ' +
                'The encounter is spotted, not engaged; the crew must choose how to respond.'
            );
        }
    }

    return lines.join('\n');
}

function questDeliveryNarrationPacket(
    result,
    quest,
    { preHandover = false } = {}
) {
    const rewards = result.rewards || {
        xp: 0,
        silver: 0,
        repSteps: 0,
        loot: []
    };

    const timingLines = preHandover
        ? [
            'If the crew has not handed over the cargo yet, portray them ' +
                'delivering it to the recipient in this reply, then display ' +
                'the System cards above immediately after the handover.',
            'If the handover was already portrayed in the previous reply, ' +
                'continue from it naturally without staging a second delivery.'
        ]
        : [
            'In the next reply, continue from the already-described handover ' +
                'and report these exact rewards naturally.',
            'This retrieval quest has locked turn-in cargo: it was handed ' +
                'over in the previous reply. Do not stage a second delivery.'
        ];

    return [
        'AUTHORITATIVE QUEST COMPLETION CONTRACT — use these values exactly.',
        `Quest completed: ${quest.title}.`,
        `Handover recipient: ${quest.turnIn?.recipient || quest.facts?.sponsor || quest.town}.`,
        'Display this exact System completion HTML card verbatim (visible to Q’tik and Tansy):',
        contractCompleteCardHtml({
            title: quest.title,
            rank: quest.rank,
            rewards,
            isMsq: quest.isMsq === true
        }),
        ...xpProgressNarrationLines(
            result.state?.crew,
            result.levelUps || []
        ),
        ...timingLines,
        'The System, not the recipient, supplied the rewards after that handover.',
        'Do not calculate, alter, repeat, or grant any additional rewards.',
        'Do not mention software, extensions, protocol tags, or reward administration in story prose.'
    ].join('\n');
}

function questActionNarrationPacket(result, questAction) {
    const quest = result.quest;

    if (questAction === 'accept') {
        return [
            `The crew accepted the quest offer: ${quest.title}.`,
            `The quest has ${quest.gates} gate(s).`,
            `The payout is ${quest.payout.xp} XP and ` +
                `${quest.payout.silver} silver, plus ` +
                `${quest.payout.repSteps} reputation step(s).`,
            `The offered salvage is ${quest.salvage.name} ` +
                `(${quest.salvage.rarity}).`,
            quest.pitch || 'The accepted request is now active.',
            ...publicQuestFactLines(quest),
            `The current gate is ${quest.currentGate.mode}: ` +
                `${quest.currentGate.objective}`,
            'Do not reveal coreTruth or change established quest facts.'

        ].join('\n');
    }

    if (questAction === 'decline') {
        return [
            `The crew declined the quest offer: ${quest.title}.`,
            'No quest rewards were paid and no objective was completed.',
            'The crew remains free to pursue other leads or explore.'
        ].join('\n');
    }

    if (questAction === 'cancel') {
        return [
            `The crew cancelled the active quest: ${quest.title}.`,
            'No quest rewards or reputation were granted.',
            'The quest was not completed and remains recorded in the quest history.'
        ].join('\n');
    }
    if (questAction === 'fail') {
        return [
            `The crew failed the active quest: ${quest.title}.`,
            'No quest rewards, salvage, or reputation were granted.',
            quest.isMsq === true
                ? 'This Main Story chapter failed forward—the regional story ' +
                  'continues with the worse fallout from this setback.'
                : 'The quest is closed as failed. The crew is free to pursue other plans.'
        ].join('\n');
    }

    if (questAction === 'complete') {
        const rewards = result.rewards;

        return [
            `System contract completed: ${quest.title}.`,
            quest.structureV2?.family === 'rescue_person'
                ? `${quest.facts.person} reached the origin settlement safely.`
                : 'The final field objective was validated.',
            'Display this exact System completion HTML card verbatim (visible to Q’tik and Tansy but not ordinary NPCs):',
            contractCompleteCardHtml({
                title: quest.title,
                rank: quest.rank,
                rewards,
                isMsq: quest.isMsq === true
            }),
            ...xpProgressNarrationLines(
                result.state?.crew,
                result.levelUps || []
            ),
            'NPC reactions may be narrated separately. No NPC handover ' +
                'or additional reward is required.'
        ].join('\n');
    }

    return null;
}

function avoidEncounterNarrationPacket(encounter) {
    return [
        `The crew chose to avoid spotted encounter ${encounter.id}.`,
        'Combat did not begin. No combat rewards were earned.',
        'Narrate the crew leaving or bypassing the group in a way consistent with the user’s stated approach. Do not claim the enemies were defeated.'
    ].join('\n');
}

function combatNarrationPacket(result, actions) {
    if (actions?.flee === true) {
        return [
            'COMBAT ESCAPE RESULT — narrate naturally.',
            result.flee?.success
                ? (result.death
                    ? 'The surviving crew member escaped.'
                    : 'The crew escaped the encounter.')
                : 'Escape failed; one enemy response was resolved.',
            ...(result.death
                ? [
                    `Death XP penalty for this encounter: ` +
                        `${result.death.xpLost}.`,
                    result.death.totalDefeat
                        ? 'Both protagonists fell and respawned at the ' +
                            'zone’s primary settlement.'
                        : result.death.respawned
                            ? 'The fallen protagonist respawned at the ' +
                                'stone when the survivor escaped. The ' +
                                'survivor did not respawn.'
                            : 'One protagonist remains at 0 HP; the ' +
                                'survivor may try to flee again.'
                ]
                : []),
            'No combat rewards were granted for fleeing.'
        ].join('\n');
    }

    const qtikActions = {
        fire_melee: 'Fire Melee',
        bodyguard: 'Bodyguard',
        stun: 'Stun',
        ice_patch: 'Ice Patch',
        frost_stomp: 'Frost Stomp',
        drink: 'Drink'
    };

    const tansyActions = {
        visor: 'Visor',
        vitals: 'Vitals',
        overrun: 'Overrun',
        recall: 'Recall',
        surge: 'Surge',
        drink: 'Drink',
        raise_shadow: 'Raise Shadow',
        unfuse_shadow: 'Unfuse Shadow'
    };

    const roster = result.summary?.encounter?.foes || [];
    const foeNames = new Map(
        roster.map((foe, index) => [
            foe.id,
            narrativeFoeLabel(foe, index)
        ])
    );
    const foeName = id => foeNames.get(id) || id;
    const qtikLabel =
        (qtikActions[actions?.qtik] || actions?.qtik || 'an action') +
        (actions?.qtik === 'drink' && result.itemUse?.qtik?.itemName
            ? ` (${result.itemUse.qtik.itemName})`
            : '');
    const shadowActionName =
        (actions?.tansy === 'raise_shadow' || actions?.tansy === 'unfuse_shadow') && actions?.shadowId
            ? (SHADOW_TYPE_LABELS[String(actions.shadowId).replace(/^shadow-/, '')] || actions.shadowId)
            : null;
    const tansyLabel =
        (tansyActions[actions?.tansy] || actions?.tansy || 'a command') +
        (actions?.tansy === 'drink' && result.itemUse?.tansy?.itemName
            ? ` (${result.itemUse.tansy.itemName})`
            : shadowActionName
                ? ` (${shadowActionName})`
                : '');

    const lines = [
        'COMBAT SCENE RESULT.',
        `Q'tik used ${qtikLabel}.`,
        `Tansy used ${tansyLabel}.`,
        'Dramatize these established events as a coherent scene. ' +
        'Add atmosphere, pacing, dialogue, and physical description, ' +
        'but do not add attacks, injuries, decisions, enemy behavior, ' +
        'or outcomes absent from this result.'
    ];

    if (actions?.target) {
        lines.push(`The selected target was ${foeName(actions.target)}.`);
    }

    if (result.death) {
        lines.push(
            `${result.death.fallen.map(owner =>
                owner === 'qtik' ? "Q'tik" : 'Tansy'
            ).join(' and ')} fell.`,
            `Shared XP death penalty: ${result.death.xpLost}.`,
            result.death.respawned
                ? result.death.totalDefeat
                    ? 'Both respawned at the zone’s primary settlement. ' +
                        'The encounter ended without victory rewards.'
                    : 'The fallen protagonist respawned at the stone ' +
                        'when combat ended. The survivor did not respawn.'
                : 'The fallen protagonist remains at 0 HP. Combat is ' +
                    'still active; the survivor can attempt to flee.'
        );
    }

    const narrativeTurn =
        result.state?.encounter?.narrativeTurns?.at(-1);

    const notableBeats = (narrativeTurn?.exchanges || [])
        .flatMap(exchange => exchange.events || []);

    if (notableBeats.length > 0) {
        lines.push(
            'Established battle beats: ' +
            notableBeats.join(' ')
        );
    }

    const living = (result.summary?.encounter?.foes || [])
        .filter(foe => foe.hp > 0)
        .map(foe => foeName(foe.id));

    if (result.rewards?.applied) {
        lines.push(
            `The encounter was cleared. Rewards applied: ` +
            `${result.rewards.xp} XP and ${result.rewards.silver} silver.`
        );
        if ((result.rewards.loot || []).length > 0) {
            lines.push(
                'Display this exact System loot HTML card verbatim (visible to Q’tik and Tansy but not to ordinary NPCs):',
                acquiredItemsCardHtml(result.rewards.loot)
            );
        }

        if (
            result.rewards.packDrop?.result ===
            'diegetic_quest_breadcrumb'
        ) {
            lines.push(
                'The cleared pack left a visible quest breadcrumb.',
                `Breadcrumb reference: ${
                    result.rewards.packDrop.breadcrumbId
                }.`,
                'Give it a modest, setting-fitting physical form. ' +
                    'Do not invent its eventual quest, sponsor, objective, ' +
                    'destination, or reward.',
                'Finding it is not the decision to pursue it. Leave ' +
                    'that choice to the protagonists.'
            );
        }
        lines.push(
            ...xpProgressNarrationLines(
                result.state?.crew,
                result.levelUps || []
            )
        );

        if (result.shadowImprints?.imprints?.length > 0) {
            lines.push(
                'SHADOW IMPRINTS DETECTED — display this exact class HTML card verbatim, separate from the victory/loot cards (visible only to Tansy and Q’tik; leave binding or dismissing to the player):',
                shadowImprintsCardHtml(result.shadowImprints)
            );
        }
    } else if (result.packCleared) {

        lines.push(
            'The encounter was cleared; no rewards were applied.'
        );

    } else if (!result.death) {
        lines.push(
            living.length
                ? `Enemies still standing: ${living.join(', ')}.`
                : 'No enemies remain standing.'
        );
    }

    if (result.summary) {
        lines.push(
            `After the fight: Q'tik ` +
                `${result.summary.qtikHp}/${result.summary.qtikMaxHp} HP; ` +
                `Tansy ${result.summary.tansyHp}/` +
                `${result.summary.tansyMaxHp} HP.`
        );
    }

    for (const questGate of result.questGates ||
        (result.questGate ? [result.questGate] : [])) {
        lines.push(
            `Quest gate ${questGate.completed.step} completed` +
                (
                    questGate.questId
                        ? ` for quest ${questGate.questId}`
                        : ''
                ) +
                '.',
            questGate.next
                ? `Next objective: ${questGate.next.objective}`
                : questGate.questCompletion
                    ? 'The System completed this quest and applied its rewards.'
                    : 'The missing person is free; bring them safely to the origin settlement.'
        );

        if (questGate.questCompletion) {
            const rewards = questGate.questCompletion.rewards;
            const completedQuest = result.state && questGate.questId
                ? findQuestById(result.state, questGate.questId)
                : null;
            lines.push(
                'Display this exact System completion HTML card verbatim (visible to Q’tik and Tansy but not ordinary NPCs):',
                contractCompleteCardHtml({
                    title: completedQuest?.title || 'Contract',
                    rank: completedQuest?.rank || null,
                    rewards,
                    isMsq: completedQuest?.isMsq === true
                })
            );
        }

    }

    lines.push(
        'Use natural story language. Do not mention extension internals, ' +
        'numeric travel counters, per-exchange HP bookkeeping, or this result packet.'
    );

    return lines.join('\n');
}

function migrateAethermoorHandoffs(stored) {
    return Array.isArray(stored?.handoffQueue) ? clone(stored.handoffQueue) : [];
}

function appendAethermoorHandoff(queue, entry, revision) {
    queue.push({
        id: `${revision}-${queue.length + 1}`,
        type: entry.type,
        packet: entry.packet,
        ...(entry.encounterId
            ? { encounterId: entry.encounterId }
            : {})
    });
}

const aethermoorContractNotifications = [];
let aethermoorContractNotificationBusy = false;
let aethermoorContractNotificationEpoch = 0;

function clearAethermoorContractNotifications() {
    aethermoorContractNotificationEpoch++;
    aethermoorContractNotifications.length = 0;
    aethermoorContractNotificationBusy = false;
    document.getElementById('aethermoor_contract_popup')?.remove();
    document.getElementById('aethermoor_shadow_imprint_popup')?.remove();
}

function scheduleAethermoorContractNotifications(before, after, metadata) {

    const oldJournal = ensureQuestJournal(clone(before));
    const newJournal = ensureQuestJournal(clone(after));

    const oldOffers = new Set(
        oldJournal.offered.map(quest => quest.id)
    );
    const oldCompleted = new Set(
        oldJournal.completed.map(quest => quest.id)
    );
    const oldAccepted = new Map(
        oldJournal.accepted.map(quest => [quest.id, quest])
    );

    const notices = [];

    for (const quest of newJournal.offered) {
        if (!oldOffers.has(quest.id)) {
            notices.push({
                type: 'offered',
                questId: quest.id
            });
        }
    }

    for (const quest of newJournal.accepted) {
        const previous = oldAccepted.get(quest.id);
        if (
            previous &&
            (quest.completedGates?.length || 0) >
                (previous.completedGates?.length || 0)
        ) {
            notices.push({
                type: 'gate',
                quest: clone(quest),
                gate: clone(quest.completedGates.at(-1))
            });
        }
    }

    for (const quest of newJournal.completed) {
        if (!oldCompleted.has(quest.id)) {
            notices.push({
                type: 'complete',
                quest: clone(quest)
            });
        }
    }

    const oldImprintId = before?.pendingShadowImprints?.encounterId || null;
    const newImprints = after?.pendingShadowImprints;
    if (
        newImprints?.imprints?.length > 0 &&
        newImprints.encounterId !== oldImprintId
    ) {
        notices.push({
            type: 'shadow_imprints',
            encounterId: newImprints.encounterId
        });
    }

    if (!notices.length) return;
    const epoch = aethermoorContractNotificationEpoch;
    const scheduledNotices = notices.map(notice => ({
        ...notice,
        metadata
    }));

    // Ignore callbacks scheduled by a campaign that has since been reset.
    setTimeout(() => {
        if (
            epoch !== aethermoorContractNotificationEpoch ||
            getContext().chatMetadata !== metadata
        ) {
            return;
        }

        aethermoorContractNotifications.push(...scheduledNotices);
        void showNextAethermoorContractNotification();
    }, 0);
}

async function showNextAethermoorContractNotification() {
    if (
        aethermoorContractNotificationBusy ||
        !aethermoorContractNotifications.length
    ) {
        return;
    }

    aethermoorContractNotificationBusy = true;
    const notice = aethermoorContractNotifications.shift();
    const epoch = aethermoorContractNotificationEpoch;

    if (getContext().chatMetadata !== notice.metadata) {
        aethermoorContractNotificationBusy = false;
        void showNextAethermoorContractNotification();
        return;
    }

    try {
        if (notice.type === 'offered') {
            await showAethermoorContractOffer(
                notice.questId,
                notice.metadata,
                epoch
            );
        } else if (notice.type === 'shadow_imprints') {
            await showAethermoorShadowImprintPopup(
                notice.metadata,
                epoch,
                true
            );
        } else if (
            epoch === aethermoorContractNotificationEpoch &&
            getContext().chatMetadata === notice.metadata
        ) {
            showAethermoorContractProgress(notice);
        }
    } catch (error) {
        if (epoch !== aethermoorContractNotificationEpoch) return;

        aethermoorContractNotificationBusy = false;
        reportAethermoorError(
            error,
            'Contract notification failed'
        );
        void showNextAethermoorContractNotification();
    }
}

function finishAethermoorContractNotification() {
    document.getElementById('aethermoor_contract_popup')?.remove();
    document.getElementById('aethermoor_shadow_imprint_popup')?.remove();
    aethermoorContractNotificationBusy = false;
    void showNextAethermoorContractNotification();
}

async function runStoredMechanic(args) {
    return queueAethermoor(async () => {
        const context = getContext();
        const metadata = context.chatMetadata;

        assert(
            metadata && typeof context.saveMetadata === 'function',
            'Open a chat with metadata saving available'
        );

        let stored = metadata[AETHERMOOR_METADATA_KEY];

        /*
         * World migration uses the same serialized save path as mechanics.
         * Preserve the full stored wrapper, including queued handoffs.
         * Never alter the original state until the save succeeds.
         */
        if (stored?.state) {
            const migratedState = clone(stored.state);

            if (ensureWorldRecords(migratedState)) {
                const previousStored = stored;

                assert(
                    getContext().chatMetadata === metadata,
                    'Chat changed during world initialization'
                );

                metadata[AETHERMOOR_METADATA_KEY] = {
                    ...stored,
                    revision: stored.revision + 1,
                    state: migratedState
                };

                try {
                    await context.saveMetadata();
                } catch (error) {
                    metadata[AETHERMOOR_METADATA_KEY] = previousStored;
                    throw error;
                }

                stored = metadata[AETHERMOOR_METADATA_KEY];
            }
        }

        /*
         * Batch cases were independent test fixtures before persistence.
         * Accept exactly one live operation per call so there is no
         * ambiguous choice of which result should become saved state.
         */
        const batch = Array.isArray(args.cases);

        if (batch) {
            assert(args.cases.length === 1,
                'Persistent mode accepts exactly one case per call');
        }

        const oneCase = batch ? args.cases[0] : null;

        if (oneCase?.kind === 'state') {
            if (oneCase.action === 'export') {
                assert(stored?.state, 'No saved Aethermoor state; initialize it first');
                return { ok: true, revision: stored.revision, state: clone(stored.state) };
            }

            assert(oneCase.action === 'initialize', 'State action must be initialize or export');
            assert(!stored, 'This chat already has saved state; initialization will not overwrite it');

            const initial = createInitialCampaignState();
            assert(getContext().chatMetadata === metadata, 'Chat changed during initialization; nothing was saved');

            metadata[AETHERMOOR_METADATA_KEY] = { revision: 1, state: initial };
            try {
                await context.saveMetadata();
            } catch (error) {
                delete metadata[AETHERMOOR_METADATA_KEY];
                throw error;
            }

            return { ok: true, initialized: true, summary: stateSummary(initial, 1) };
        }

        assert(stored?.state,
            'No saved Aethermoor state; import it first');

        assert(args.state === undefined,
            'State is stored by the extension; omit top-level state');
        assert(!batch || oneCase.state === undefined,
            'State is stored by the extension; omit case.state');

        const savedState = clone(stored.state);
        const input = batch
            ? {
                ...args,
                cases: [{
                    ...oneCase,
                    state: savedState
                }]
            }
            : {
                ...args,
                state: savedState
            };

        const output = batch
            ? resolveBatch(input)
            : resolveTurn(input);

        assert(output?.ok !== false,
            batch
                ? output.results?.[0]?.error ||
                  'Mechanics case failed; state unchanged'
                : output.error ||
                  'Mechanics operation failed; state unchanged'
        );

        const caseResult = batch
            ? output.results[0].result
            : output;

        /*
         * Reference, stock, and food-list operations do not return
         * mutated state. They are read-only.
         */
        if (!caseResult?.state) {
            return output;
        }

        // A repeated [moved] message reuses its locked result without
        // saving another revision or replacing a pending handoff.
        if (
            batch &&
            caseResult.created === false &&
            (
                oneCase.kind === 'travel' ||
                oneCase.kind === 'investigate_sign' ||
                oneCase.kind === 'instance' ||
                oneCase.kind === 'encounter_request' ||
                oneCase.kind === 'stock_names' ||
                oneCase.kind === 'zone_spine' ||
                oneCase.kind === 'msq' ||
                oneCase.kind === 'follow_breadcrumb' ||
                oneCase.kind === 'quest_event' ||
                oneCase.kind === 'quest_delivery' ||
                (

                    oneCase.kind === 'social' &&
                    [
                        'check_work',
                        'reveal_work',
                        'prepare_npc_seeds',
                        'claim_npc_seed'
                    ].includes(oneCase.action)
                )
            )
        ) {

            const { state: _saved, ...visibleResult } = caseResult;
            return {
                ok: true,
                total: 1,
                passed: 1,
                failed: 0,
                results: [{
                    ...output.results[0],
                    result: visibleResult
                }],
                summary: stateSummary(stored.state, stored.revision)
            };
        }

        /*
         * Resolve known rumors only at a confirmed location: an unfinished
         * journey, including deferred final-segment arrival, blocks this.
         * Running here also allows a deferred hook to become an offer after
         * the quest slot becomes available while the crew remains at the site.
         *
         * State reads return earlier and never run this integration.
         * Rumor state and its narration packets share the operation's save,
         * so a failed save cannot leave an independently committed outcome.
         */
        const arrivedRumors = resolveArrivedRumors(caseResult.state);
        const nextState = arrivedRumors.state;

        const recovery = applyOutOfCombatRecovery(
            savedState,
            nextState,
            oneCase
        );

        if (recovery) {
            caseResult.outOfCombatRecovery = recovery;
        }

        const unlockedAchievements = evaluateAethermoorAchievements(
            savedState,
            nextState,
            caseResult,
            oneCase,
            recovery
        );

        if (unlockedAchievements.length > 0) {
            caseResult.unlockedAchievements = unlockedAchievements.map(a => a.id);

            if (
                nextState.encounter?.victoryReceipt?.postFightHp &&
                nextState.encounter.victoryReceipt.encounterId ===
                    nextState.encounter.id
            ) {
                const postStats = derived(nextState.crew);
                nextState.encounter.victoryReceipt.postFightHp.qtik =
                    nextState.crew.qtik.hp;
                nextState.encounter.victoryReceipt.postFightHp.qtikMax =
                    postStats.qtikMaxHp;
                nextState.encounter.victoryReceipt.postFightHp.tansy =
                    nextState.crew.tansy.hp;
                nextState.encounter.victoryReceipt.postFightHp.tansyMax =
                    postStats.tansyMaxHp;
            }
        }

        caseResult.state = nextState;

        if (arrivedRumors.resolutions.length > 0) {
            caseResult.rumorArrivals = arrivedRumors.resolutions;
        }

        assert(getContext().chatMetadata === metadata,
            'Chat changed during operation; nothing was saved');

        const previous = metadata[AETHERMOOR_METADATA_KEY];
        const revision = previous.revision + 1;

        const isCombatTurn = batch
            ? oneCase?.kind === 'turn'
            : Boolean(args.actions);

        /*
         * A player may resolve the whole fight in the UI before sending
         * their next fictional reply. At victory, use the saved receipt
         * for the entire fight, not just the final turn's result.
         * Unfinished fights retain their ordinary current-turn handoff.
         */
        const completedFightReceipt =
            isCombatTurn &&
            nextState.encounter?.status === 'cleared' &&
            nextState.encounter.victoryReceipt?.encounterId ===
                nextState.encounter.id
                ? nextState.encounter.victoryReceipt
                : null;

        const narrationPacket = completedFightReceipt
            ? [
                'PRIVATE COMPLETED FIGHT — narrate in this reply; do not recite this heading.',
                'Continue directly from the player’s fictional decision to engage.',
                'The UI has already resolved the entire encounter. Do not ask',
                'whether to fight, restart combat, or resolve another turn.',
                combatRecapPrompt(completedFightReceipt)
            ].join('\n')
            : isCombatTurn
                ? combatNarrationPacket(
                    {
                        ...caseResult,
                        summary: stateSummary(nextState, revision)
                    },
                    batch ? oneCase.actions : args.actions
                )
                : null;

        const questActionPacket =
            batch &&
            oneCase?.kind === 'quest' &&
            ['accept', 'decline', 'cancel', 'fail', 'complete']
                .includes(oneCase.action)
                ? questActionNarrationPacket(
                    {
                        ...caseResult,
                        quest: caseResult.quest
                    },
                    oneCase.action
                )
                : null;

        const questDeliveryPacket =
            batch &&
            oneCase?.kind === 'quest_delivery' &&
            caseResult.created !== false &&
            caseResult.deferred !== true
                ? questDeliveryNarrationPacket(
                    caseResult,
                    caseResult.quest,
                    { preHandover: oneCase.name === 'manual_quest_delivery' }
                )
                : null;

        const previousEncounter = savedState.encounter;
        const nextEncounter = nextState.encounter;
        const beganNewEncounter =
            ['active', 'spotted'].includes(nextEncounter?.status) &&
            nextEncounter.id !== previousEncounter?.id;

        const discoveryPacket =
            batch &&
            oneCase?.kind === 'quest_reveal_terminal' &&
            caseResult.created !== false
                ? [
                    discoveryNarrationPacket(nextState.encounter, nextState),
                    questTerminalNarrationPacket(
                        nextState.encounter,
                        findQuestById(
                            nextState,
                            nextState.encounter.questTerminal.questId
                        )
                    )
                ].join('\n\n')

            : batch &&
              oneCase?.kind === 'instance' &&
              oneCase.action === 'open_chest' &&
              caseResult.created
                ? instanceChestNarrationPacket(caseResult)

            : batch &&
              oneCase?.kind === 'instance' &&
              ['enter', 'move', 'exit'].includes(oneCase.action) &&
              caseResult.created
                ? [
                    instanceNarrationPacket(caseResult),
                    ...(caseResult.encounter
                        ? [
                            discoveryNarrationPacket(
                                nextState.encounter,
                                nextState
                            )
                        ]
                        : [])
                ].join('\n\n')

            : beganNewEncounter
                ? [
                    discoveryNarrationPacket(nextEncounter, nextState),
                    ...(nextEncounter.questTerminal
                        ? [
                            questTerminalNarrationPacket(
                                nextEncounter,
                                findQuestById(
                                    nextState,
                                    nextEncounter.questTerminal.questId
                                )
                            )
                        ]
                        : []),
                    ...(batch &&
                        oneCase?.kind === 'quest_event' &&
                        caseResult.created &&
                        caseResult.questGate
                        ? [
                            questDiscoveryNarrationPacket(
                                caseResult,
                                findQuestById(
                                    nextState,
                                    caseResult.questId
                                )
                            )
                        ]
                        : []),
                    ...(
                        caseResult.journey ||
                        (
                            batch &&
                            oneCase?.kind === 'travel' &&
                            caseResult.created
                        )
                            ? [travelNarrationPacket(caseResult)]
                            : []
                    ),
                    ...(
                        batch &&
                        oneCase?.kind === 'investigate_sign' &&
                        caseResult.created
                            ? [trailSignInvestigationNarrationPacket(caseResult)]
                            : []
                    )
                ].join('\n\n')

            : batch &&
              oneCase?.kind === 'shadows' &&
              oneCase.action === 'bind_imprints' &&
              Array.isArray(caseResult.bound) &&
              caseResult.bound.length > 0
                ? shadowBindNarrationPacket(caseResult)

            : batch &&
              oneCase?.kind === 'gear' &&
              oneCase.action === 'equip'
                ? inventoryActionNarrationPacket(caseResult, 'equip')

            : batch &&
              oneCase?.kind === 'consumable' &&
              oneCase.action === 'use' &&
              caseResult.recipient
                ? inventoryActionNarrationPacket(caseResult, 'use')

            : batch &&
              oneCase?.kind === 'inn' &&
              caseResult.restRecovery
                ? innRestNarrationPacket(caseResult)

            : batch &&
              oneCase?.kind === 'trade' &&
              ['settle', 'settle_all'].includes(oneCase.action) &&
              Array.isArray(caseResult.settlements) &&
              caseResult.settlements.length > 0
                ? tradeSettleNarrationPacket(caseResult)

            : batch && oneCase?.kind === 'follow_breadcrumb' &&
              caseResult.created &&
              caseResult.quest
                ? questOfferNarrationPacket(caseResult.quest, nextState)

            : batch &&
              oneCase?.kind === 'msq' &&
              caseResult.created &&
              caseResult.quest
                ? msqOfferNarrationPacket(caseResult.quest, nextState)

            : questDeliveryPacket
                ? questDeliveryPacket

            : questActionPacket
                ? questActionPacket

            : batch &&
              oneCase?.kind === 'quest_event' &&
              caseResult.created &&
              caseResult.deferred !== true
                ? questDiscoveryNarrationPacket(
                    caseResult,
                    caseResult.quest ||
                        findQuestByDiscoveryId(
                            nextState,
                            oneCase.questItemId
                        )
                )

            : batch &&
              oneCase?.kind === 'avoid' &&
              caseResult.created
                ? avoidEncounterNarrationPacket(nextEncounter)

            : batch &&
              oneCase?.kind === 'investigate_sign' &&
              caseResult.created
                ? trailSignInvestigationNarrationPacket(caseResult)

            : batch &&
              oneCase?.kind === 'travel' &&
              caseResult.created
                ? travelNarrationPacket(caseResult)

            : null;

        const handoffQueue = migrateAethermoorHandoffs(stored);

        /*
         * Only the latest report for this encounter should reach the
         * next GM reply. On victory, that report contains the saved
         * full-fight recap. Do not discard handoffs for other encounters
         * or unrelated quest, travel, and discovery results.
         */
        if (narrationPacket && nextState.encounter?.id) {
            for (let index = handoffQueue.length - 1; index >= 0; index--) {
                if (
                    handoffQueue[index].type === 'combat' &&
                    handoffQueue[index].encounterId ===
                        nextState.encounter.id
                ) {
                    handoffQueue.splice(index, 1);
                }
            }
        }

        if (batch && oneCase?.kind === 'shadows' && oneCase.action === 'dismiss_imprints') {
            for (const entry of handoffQueue) {
                if (entry.type === 'combat' && typeof entry.packet === 'string') {
                    entry.packet = entry.packet.replace(
                        /\nSHADOW IMPRINTS DETECTED — [^\n]*\n[^\n]*/g,
                        ''
                    );
                }
            }
        }

        if (discoveryPacket) {
            appendAethermoorHandoff(
                handoffQueue,
                {
                    type: 'discovery',
                    packet: discoveryPacket
                },
                revision
            );
        }

        if (narrationPacket) {
            appendAethermoorHandoff(
                handoffQueue,
                {
                    type: 'combat',
                    encounterId: nextState.encounter?.id,
                    packet: narrationPacket
                },
                revision
            );
        }

        const rumorPackets = arrivedRumors.packets;
        for (const packet of rumorPackets) {
            appendAethermoorHandoff(
                handoffQueue,
                {
                    type: 'rumor_arrival',
                    packet
                },
                revision
            );
        }

        if (unlockedAchievements.length > 0) {
            appendAethermoorHandoff(
                handoffQueue,
                {
                    type: 'achievement',
                    packet: [
                        'ACHIEVEMENT UNLOCKED — display this exact System HTML card ' +
                            'verbatim (visible to Q’tik and Tansy, not ordinary NPCs):',
                        achievementUnlockedCardHtml(unlockedAchievements),
                        'The stat bonuses are already applied to saved state.'
                    ].join('\n')
                },
                revision
            );
        }


        metadata[AETHERMOOR_METADATA_KEY] = {
            revision,
            state: nextState,
            handoffQueue
        };

        try {
            await context.saveMetadata();

        } catch (error) {
            metadata[AETHERMOOR_METADATA_KEY] = previous;
            throw error;
        }

        if (oneCase?.deferNotifications !== true) {
            scheduleAethermoorContractNotifications(
                savedState,
                nextState,
                metadata
            );
        }

        /*
         * The full machine state stays in chat metadata, rather than
         * being copied through the prompt or tool response.
         */
        const { state: _saved, ...visibleResult } = caseResult;

        if (batch) {
            return {
                ok: true,
                total: 1,
                passed: 1,
                failed: 0,
                results: [{
                    ...output.results[0],
                    result: visibleResult
                }],
                summary: stateSummary(nextState, revision)
            };
        }

        return {
            ...visibleResult,
            summary: stateSummary(nextState, revision)
        };
    });
}

const LOOT_RARITY_INFO = {
    common:   { label: 'Common',   color: '#ffffff' },
    uncommon: { label: 'Uncommon', color: '#4ade80' },
    rare:     { label: 'Rare',     color: '#38bdf8' },
    epic:     { label: 'Epic',     color: '#c084fc' },
    legendary:{ label: 'Legendary',color: '#fbbf24' }
};

const ZONE_MATERIAL_NAMES = {
    1: 'Valley Iron',
    2: 'Fen-Bronze',
    3: 'Cold Bog-Iron',
    4: 'Karst Chitin',
    5: 'Highgate Steel'
};

const ZONE_LOOT_MATERIALS = new Proxy({}, {
    get(_target, key) {
        const zone = zoneNumber(key);
        if (zone === null) return undefined;

        return ZONE_MATERIAL_NAMES[zone] || ZONES[zone].name;

    }
});

function usable(owner, slot, variant = null) {
    return { owner, slot, variant, usable: true };
}

function restricted(slot, restriction) {
    return {
        owner: null,
        slot,
        variant: null,
        usable: false,
        restriction
    };
}

const OFF_CLASS_LOOT = [
    restricted('heavy_plate', 'Off-Class Heavy Plate / Brigandine'),
    restricted('great_weapon', 'Off-Class 2H Greatsword / Halberd'),
    restricted('shield', 'Off-Class Tower Shield / Buckler'),
    restricted(
        'heavy_mail',
        'Off-Class Heavy Mail Gauntlets / Greathelm'
    ),
    restricted(
        'skill_tome',
        'Off-Class Martial / Mage Skill Tome'
    )
];

/*
 * These are separate source tables. Keep their order aligned with
 * the original SillyTavern random-option lists.
 */
const WILD_ELITE_LOOT_SLOTS = [
    usable('tansy', 'weapon'),
    usable('tansy', 'gloves'),
    usable('tansy', 'chest'),
    usable('tansy', 'trousers'),
    usable('tansy', 'ring1', 'vitality'),
    usable('tansy', 'ring1', 'luck'),
    usable('tansy', 'neck', 'vitality'),
    usable('tansy', 'boots', 'luck'),
    usable('qtik', 'ring1', 'bulwark'),
    usable('qtik', 'ring1', 'vitality'),
    usable('qtik', 'amulet', 'bulwark'),
    usable('qtik', 'wristCuffs', 'vitality'),
    ...OFF_CLASS_LOOT
];

const BOSS_LOOT_SLOTS = [
    usable('tansy', 'weapon'),
    usable('tansy', 'gloves'),
    usable('tansy', 'chest'),
    usable('tansy', 'trousers'),
    usable('tansy', 'ring1', 'vitality'),
    usable('tansy', 'neck', 'luck'),
    usable('qtik', 'ring1', 'bulwark'),
    usable('qtik', 'amulet', 'vitality'),
    usable('qtik', 'wristCuffs', 'bulwark'),
    ...OFF_CLASS_LOOT
];

function lootRarityFromRoll(roll) {
    assert(
        Number.isInteger(roll) && roll >= 1 && roll <= 6,
        'rarityRoll must be 1-6'
    );

    if (roll <= 3) return 'common';
    if (roll <= 5) return 'uncommon';
    return 'rare';
}

function lootStatFromRarity(zone, rarity) {
    const base = ZONES[zone].base;

    if (rarity === 'common') return base;
    if (rarity === 'uncommon') {
        return Math.max(base + 1, Math.round(base * 1.25));
    }
    if (rarity === 'rare') {
        return Math.max(base + 3, Math.round(base * 1.45));
    }
    if (rarity === 'epic') {
        return Math.max(base + 5, Math.round(base * 1.7));
    }
    if (rarity === 'legendary') {
        return Math.max(base + 8, Math.round(base * 2));
    }

    throw new Error(`Unsupported loot rarity: ${rarity}`);
}

function lootBonus(owner, slot, variant, stat) {
    const result = {
        crewAtk: 0,
        tansyMaxHp: 0,
        qtikMaxHp: 0,
        frontlineDef: 0,
        crewLuk: 0
    };

    if (owner === 'tansy') {
        if (slot === 'weapon') {
            result.crewAtk = stat * 2;
        } else if (slot === 'gloves') {
            result.crewAtk = stat;
        } else if (slot === 'chest' || slot === 'trousers') {
            result.tansyMaxHp = stat * 5;
            result.crewLuk = 1;
        } else if (variant === 'vitality') {
            result.tansyMaxHp = stat * 5;
        } else if (variant === 'luck') {
            result.crewLuk = stat;
        }
    }

    if (owner === 'qtik') {
        if (variant === 'bulwark') {
            result.frontlineDef = stat * 2;
        } else if (variant === 'vitality') {
            result.qtikMaxHp = stat * 15;
        }
    }

    return result;
}

function lootItemName(material, loot) {
    if (!loot.usable) {
        return `${material} ${loot.restriction}`;
    }

    const variantName = loot.variant
        ? ` ${loot.variant[0].toUpperCase()}${loot.variant.slice(1)}`
        : '';

    const slotNames = {
        weapon: 'Focus',
        gloves: 'Bracers',
        chest: 'Chest',
        trousers: 'Trousers',
        ring1: 'Ring',
        neck: 'Necklace',
        boots: 'Boots',
        amulet: 'Amulet',
        wristCuffs: 'Wrist Cuffs'
    };

    return `${material}${variantName} ${slotNames[loot.slot]}`;
}

function rollLootFromState(
    state,
    source,
    zone = state.encounter?.zone ?? state.zone
) {
    assert(ZONES[zone], `Unknown loot zone: ${zone}`);

    const slots = source === 'boss'
        ? BOSS_LOOT_SLOTS
        : WILD_ELITE_LOOT_SLOTS;

    const slotRoll = roll(state, slots.length);
    const rarityRoll = source === 'wild'
        ? roll(state, 6)
        : undefined;

    return {
        ...resolveLootSeed({
            zone,
            source,
            slotRoll,
            rarityRoll
        }, state),
        rolls: { slotRoll, rarityRoll }
    };
}

function resolveLootSeed(test, state = null) {
    assert(ZONES[test.zone], `Unknown zone: ${test.zone}`);

    assert(
        ['wild', 'elite', 'boss'].includes(test.source),
        `Unsupported loot source: ${test.source}`
    );

    const slots = test.source === 'boss'
        ? BOSS_LOOT_SLOTS
        : WILD_ELITE_LOOT_SLOTS;

    assert(
        Number.isInteger(test.slotRoll) &&
        test.slotRoll >= 1 &&
        test.slotRoll <= slots.length,
        `slotRoll must be 1-${slots.length} for ${test.source}`
    );

    const loot = slots[test.slotRoll - 1];

    const rarity = test.source === 'wild'
        ? lootRarityFromRoll(test.rarityRoll)
        : test.source === 'elite'
            ? 'uncommon'
            : 'epic';

    const rarityInfo = LOOT_RARITY_INFO[rarity];
    const rawStat = lootStatFromRarity(test.zone, rarity);
    const fallbackName = lootItemName(
        ZONE_LOOT_MATERIALS[test.zone],
        loot
    );

    const item = {
        name: loot.usable && state
            ? cosmeticStockName(
                state,
                gearCosmeticStockKey(loot.owner, loot.slot, loot.variant),
                fallbackName,
                test.zone
            )
            : fallbackName,

        source: test.source,
        slot: loot.slot,
        owner: loot.owner,
        variant: loot.variant,
        rarity: rarityInfo.label,
        rarityColor: rarityInfo.color,
        rawStat,
        bound: false,
        sellValue: rawStat * 2,
        bonus: lootBonus(
            loot.owner,
            loot.slot,
            loot.variant,
            rawStat
        ),
        classRestricted: !loot.usable,

        // Any never-equipped gear is unbound and may be listed.
        tradeStreamEligible: true
    };

    if (!loot.usable) {
        item.restriction = loot.restriction;
    }

    // The Trade-Stream values skill tomes using S=10. Their
    // NPC pawn value still follows the raw-stat gear rule.
    if (loot.slot === 'skill_tome') {
        item.tradeStat = 10;
    }

    return { ok: true, item };
}

function combatFoeLabel(foe, index) {
    const roleNames = {
        brute: 'Brute',
        archer: 'Ranged',
        mender: 'Mender',
        hexer: 'Hexer',
        buffer: 'Buffer',
        elite: 'Elite',
        boss: 'Boss'
    };

    return `${roleNames[foe.role] || foe.role} ${index + 1}`;
}

function narrativeFoeLabel(_foe, index) {
    return `Opponent ${index + 1}`;
}

function formatQuestStatus(quest) {

    if (!quest) {
        return 'No active quest offer.';
    }

    const variantLabels = {
        paymaster_strongbox: 'Paymaster Strongbox',
        cipher_compartment: 'Cipher Compartment',
        scout_dead_drop: 'Scout Dead-Drop',
        rogue_automaton: 'Rogue Pre-Calamity Construct',
        breached_seal: 'Breached Sister-Vault',
        leyline_anomaly: 'Leaking Conduit Anomaly',
        lost: 'Lost Person',
        abducted: 'Abducted Person'
    };

    const lines = [
        `Quest: ${quest.title}`,
        `Status: ${quest.status}`,
        `Rank: ${quest.rank}`,
        ...(variantLabels[quest.variant?.id]
            ? [`Variant: ${variantLabels[quest.variant.id]}`]
            : []),
        `Gates: ${quest.gates}`,
        `Payout: ${quest.payout.xp} XP, ` +
            `${quest.payout.silver} silver, ` +
            `${quest.payout.repSteps} reputation step(s)`,
        `Salvage: ${quest.salvage.name} ` +
            `(${quest.salvage.rarity})`,
        ''
    ];

    if (quest.status === 'offered') {
        lines.push(
            'This quest has been offered but not accepted.',
            `First objective: ${quest.currentGate?.objective || 'not established'}`
        );
    }
else if (quest.status === 'in_progress') {
        lines.push(
            `Current gate: ${quest.currentGate?.step || 1}/` +
            `${quest.currentGate?.total || quest.gates}`,
            `Mode: ${quest.currentGate?.mode || 'not established'}`,
            `Objective: ${quest.currentGate?.objective || 'not established'}`,
            `Terminal threat: ${
                quest.terminalThreat?.revealed
                    ? quest.terminalThreat.resolved
                        ? 'resolved'
                        : 'revealed'
                    : 'not revealed'
            }`

        );
            } else if (quest.status === 'abandoned') {
        lines.push(
            `Abandoned at gate ${quest.abandonedAtGate || 'unknown'}.`,
            'No quest rewards or reputation were granted.'
        );
            
            } else if (quest.status === 'cancelled') {
        lines.push(
            `Cancelled at gate ${quest.cancelledAtGate || 'unknown'}.`,
            'No quest rewards or reputation were granted.'
        );
    } else if (quest.status === 'failed') {
        lines.push(
            `Failed at gate ${quest.failedAtGate || 'unknown'}.`,
            'No quest rewards or reputation were granted.'
        );

    } else if (quest.status === 'declined') {
        lines.push('This quest was declined.');
    } else if (quest.status === 'complete') {
        lines.push('This quest has been completed.');
    } else if (quest.status === 'retired_test') {
        lines.push(
            `This test quest was retired: ${
                quest.retiredReason || 'no reason recorded'
            }.`,
            'No rewards were granted.'
        );
    }

    if (
        quest.status === 'in_progress' &&
        quest.objectiveResolution &&
        quest.structureV2?.family === 'rescue_person'
    ) {
        lines.push(
            'The person must reach the origin settlement safely. ' +
            'Confirmed arrival completes the quest automatically.'
        );
    }

    return lines.join('\n');
}

function openAethermoorTab(tab) {
    aethermoorActiveTab = tab;

    if (aethermoorPanelOpen && aethermoorPanelElement?.hidden === false) {
        renderAethermoorTab(tab);
    } else {
        openAethermoorPanel();
    }
}

